(window.CLAVE_ARTF=window.CLAVE_ARTF||{})[19]=[["Artículo 140","<p><b>1.ª</b> Que la víctima sea <mark class=\"m-autoridad\">menor</mark> de <mark class=\"m-resp r-ia\" data-q=\"19-ia-1003\">dieciséis</mark> años de edad, o se trate de una <mark class=\"m-autoridad\">persona</mark> especialmente vulnerable por razón de su edad, enfermedad o discapacidad.</p><p><b>2.ª</b> Que el hecho fuera subsiguiente <span class=\"ex-plg\"><span class=\"ex-plg-t\">a un delito contra la libertad sexual que el autor hubiera cometido sobre la víctima.</span></span>  <mark class=\"m-resp ex-q\" data-q=\"19-229\">🎯 1 pregunta</mark></p><p><b>3.ª</b> Que el delito se hubiera cometido por quien <mark class=\"m-resp r-ia\" data-q=\"19-ia-1004\">perteneciere a un grupo u organización criminal</mark>.</p></div></div><div class=\"vis\"><div class=\"vis-t\"><i>⇄</i>HOMICIDIO Y SUS FORMAS (cuadro del temario · arts. 138-140)</div><div class=\"vis-comp\" style=\"--n:3\"><div class=\"vis-col\"><h5>HOMICIDIO · art. 138</h5><ul><li>Matar a otra <mark class=\"m-autoridad\">persona</mark>.</li><li>En su <mark class=\"m-destacable\">forma</mark> agravada → ASESINATO.</li></ul></div><div class=\"vis-col\"><h5>ASESINATO · arts. 139 y 140</h5><ul><li>Alevosía.</li><li><u class=\"m-clave\">Precio</u>, recompensa o promesa.</li><li><mark class=\"m-personalizado\">Ensañamiento</mark>, aumentando deliberada e inhumanamente el dolor del ofendido.</li><li>Para facilitar otro <mark class=\"m-personalizado\">delito</mark> o <u class=\"m-clave\">evitar</u> que se descubra.</li></ul></div><div class=\"vis-col\"><h5>PRISIÓN PERMANENTE REVISABLE · art. 140</h5><ul><li>Que <mark class=\"m-personalizado\">la víctima sea</mark> <mark class=\"m-autoridad\">menor de</mark> dieciséis <mark class=\"m-personalizado\">años</mark> <mark class=\"m-personalizado\">de edad</mark>, o se trate de una <mark class=\"m-autoridad\">persona</mark> <mark class=\"m-personalizado\">especialmente</mark> vulnerable <u class=\"m-clave\">por razón</u> de su <mark class=\"m-personalizado\">edad</mark>, <mark class=\"m-personalizado\">enfermedad</mark> <mark class=\"m-personalizado\">o discapacidad</mark>.</li><li>Que el <u class=\"m-clave\">hecho</u> fuera subsiguiente a un <mark class=\"m-personalizado\">delito</mark> <mark class=\"m-autoridad\">contra</mark> la <u class=\"m-clave\">libertad</u> <u class=\"m-clave\">sexual</u> que el <mark class=\"m-autoridad\">autor</mark> <u class=\"m-clave\">hubiera</u> <mark class=\"m-personalizado\">cometido</mark> sobre la <mark class=\"m-personalizado\">víctima</mark>.</li><li>Que <mark class=\"m-personalizado\">el delito</mark> se <u class=\"m-clave\">hubiera</u> <mark class=\"m-personalizado\">cometido</mark> por <u class=\"m-clave\">quien</u> perteneciere a un grupo u <u class=\"m-clave\">organización</u> criminal.</li><li>Reo de asesinato que <u class=\"m-clave\">hubiera</u> <u class=\"m-clave\">sido</u> condenado por <mark class=\"m-personalizado\">la muerte</mark> de más de <u class=\"m-clave\">dos</u> <mark class=\"m-autoridad\">personas</mark>.</li></ul></div></div></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo</mark> 140 bis: <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-1005\">🎯 1 pregunta más de este artículo</mark></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo</mark> 143: <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-1007\">🎯 1 pregunta más de este artículo</mark>"],["Artículo 145","<p><b>3.</b> En todo caso, el <mark class=\"m-autoridad\">juez o tribunal</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-accion\">impondrá</mark> las penas respectivamente previstas en este artículo en su mitad superior cuando la conducta se llevare a cabo a partir de la vigésimo segunda semana de gestación.</span></span>  <mark class=\"m-resp ex-q\" data-q=\"19-218\">🎯 1 pregunta</mark></p></div></div><div class=\"vis\"><div class=\"vis-t\"><i>▦</i>DELITO DE ABORTO · arts. 144 y 145 CP (cuadro del temario)</div><div class=\"vis-tabla\"><div class=\"vt-cab\"><span>Conducta típica</span><span>Sujeto activo</span></div><div class=\"vt-nodo\"><div class=\"vt-et o\">Producir el aborto de una mujer SIN su CONSENTIMIENTO</div><div class=\"vt-hijos\"><div class=\"vt-hoja\"><span class=\"vt-p o\">Sin consentimiento</span><div class=\"vt-t\">Habiendo obtenido la anuencia de la mujer mediante violencia, amenaza o engaño.</div></div><div class=\"vt-hoja\"><span class=\"vt-p v\">Sujeto activo</span><div class=\"vt-t\">Cualquier persona.</div></div></div></div><div class=\"vt-nodo\"><div class=\"vt-et v\">Producir el aborto de una mujer CON su CONSENTIMIENTO</div><div class=\"vt-hijos\"><div class=\"vt-hoja\"><span class=\"vt-p v\">Con consentimiento</span><div class=\"vt-t\">Fuera de los casos permitidos por la ley.</div></div><div class=\"vt-hoja\"><span class=\"vt-p v\">Sujeto activo</span><div class=\"vt-t\">Cualquier persona.</div></div></div></div><div class=\"vt-nodo\"><div class=\"vt-et c\">Cuando fuera de los casos permitidos por la ley</div><div class=\"vt-hijos\"><div class=\"vt-hoja\"><span class=\"vt-p c\">La mujer</span><div class=\"vt-t\">Produce su propio aborto, o consiente que otra persona se lo cause.</div></div><div class=\"vt-hoja\"><span class=\"vt-p v\">Sujeto activo</span><div class=\"vt-t\">Propia mujer embarazada.</div></div></div></div>"],["<mark class=\"m-destacable\">Artículo 156 bis</mark>","<p style=\"margin-left:18px\"><b>a)</b> La <mark class=\"m-resp r-ia\" data-q=\"19-ia-1016\">extracción u obtención ilícita de <mark class=\"m-autoridad\">órganos</mark> humanos ajenos</mark>. <span class=\"ex-plg\"><span class=\"ex-plg-t\">Dicha extracción u obtención <mark class=\"m-accion\">será</mark> ilícita si se produce concurriendo cualquiera de las circunstancias siguientes:</span></span></p><p><b>9.</b> En todo caso, las penas <span class=\"ex-plg\"><span class=\"ex-plg-t\">previstas en este artículo <mark class=\"m-accion\">se impondrán</mark> sin perjuicio de las que correspondan, en su caso, por el delito del artículo 177 bis de este</span></span> Código y demás delitos efectivamente <mark class=\"m-resp r-ia\" data-q=\"19-ia-2736\">cometidos</mark>.</p><p><b>10.</b> Las condenas de <mark class=\"m-autoridad\">jueces o tribunales extranjeros</mark> por <span class=\"ex-plg\"><span class=\"ex-plg-t\">delitos de la misma naturaleza que los previstos en este</span></span> artículo <mark class=\"m-accion\">producirán</mark> los efectos de <mark class=\"m-resp\" data-q=\"19-261\">reincidencia, salvo que el antecedente penal haya sido cancelado o pueda serlo con arreglo al Derecho español</mark>.</p></div></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo</mark> 156 ter: <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-1017\">🎯 1 pregunta más de este artículo</mark>"],["Artículo 161","<p><b>2.</b> <span class=\"ex-plg\"><span class=\"ex-plg-t\">Para proceder por este delito <mark class=\"m-accion\">será</mark> precisa denuncia de la <mark class=\"m-autoridad\">persona</mark> agraviada o de su representante legal.</span></span> Cuando aquélla sea <mark class=\"m-autoridad\">menor</mark> de edad, <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-autoridad\">persona</mark> con discapacidad necesitada de especial protección o una <mark class=\"m-autoridad\">persona</mark> desvalida, también <mark class=\"m-accion\">podrá denunciar</mark> el <mark class=\"m-autoridad\"><mark class=\"m-resp\" data-q=\"19-262,19-ia-1021\">Ministerio Fiscal</mark>.</mark></span></span></p>"],["Artículo 163","<p><b>1.</b> El <mark class=\"m-resp\" data-q=\"19-231,19-ia-1022\">particular que encerrare o detuviere a otro, privándole de su libertad</mark>, <mark class=\"m-accion\">será castigado</mark> con la pena de prisión de cuatro a seis años.</p></div></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo</mark> 164: <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-1023\">🎯 1 pregunta más de este artículo</mark></div><div class=\"vis\"><div class=\"vis-t\"><i>⇄</i>DETENCIONES ILEGALES · SECUESTRO (cuadro del temario · arts. 163 a 165)</div><div class=\"vis-comp\" style=\"--n:3\"><div class=\"vis-col\"><h5>DETENCIONES ILEGALES</h5><ul><li>TIPO BÁSICO: El <u class=\"m-clave\">particular</u> que encerrare o detuviere a otro, privándole de su <u class=\"m-clave\">libertad</u>.</li><li>OTROS TIPOS · ATENUADO: <mark class=\"m-autoridad\">si el culpable</mark> diera <u class=\"m-clave\">libertad</u> al encerrado o <mark class=\"m-personalizado\">detenido</mark> <mark class=\"m-plazo\">dentro de los tres primeros días</mark> de su <mark class=\"m-personalizado\">detención</mark>, <u class=\"m-clave\">sin</u> haber logrado el <mark class=\"m-personalizado\">objeto</mark> que se había propuesto.</li><li>OTROS TIPOS · AGRAVADO: <mark class=\"m-personalizado\">si</mark> el encierro o <mark class=\"m-personalizado\">detención</mark> ha durado <mark class=\"m-plazo\">más de <u class=\"m-clave\">quince días</u></mark>.</li><li>El <u class=\"m-clave\">particular</u> que, <u class=\"m-clave\">fuera de</u> <mark class=\"m-personalizado\">los casos</mark> permitidos por las <mark class=\"m-personalizado\">leyes</mark>, aprehendiere a una <mark class=\"m-autoridad\">persona</mark> para presentarla inmediatamente a <mark class=\"m-autoridad\">la autoridad</mark>.</li></ul></div><div class=\"vis-col\"><h5>SECUESTRO</h5><ul><li>TIPO BÁSICO: Secuestro de una <mark class=\"m-autoridad\">persona</mark> exigiendo <mark class=\"m-personalizado\">alguna</mark> <mark class=\"m-personalizado\">condición</mark> para ponerla en <u class=\"m-clave\">libertad</u>.</li><li>OTROS TIPOS · AGRAVADO: <mark class=\"m-personalizado\">si</mark> <mark class=\"m-personalizado\">el secuestro</mark> ha durado <mark class=\"m-plazo\">más de <u class=\"m-clave\">quince días</u></mark>.</li><li>OTROS TIPOS · ATENUADO: <mark class=\"m-autoridad\">si el culpable</mark> diera la <u class=\"m-clave\">libertad</u> al secuestrado dentro de los <mark class=\"m-plazo\">tres primeros días</mark>, <u class=\"m-clave\">sin</u> haber logrado el <mark class=\"m-personalizado\">objeto</mark> que se había propuesto.</li></ul></div><div class=\"vis-col\"><h5>ART. 165 · MITAD SUPERIOR (ambos)</h5><ul><li><mark class=\"m-personalizado\">Cuando</mark> se ha <mark class=\"m-personalizado\">cometido</mark> con <u class=\"m-clave\">simulación</u> de <mark class=\"m-autoridad\">autoridad o</mark> <u class=\"m-clave\">función</u> <mark class=\"m-personalizado\">pública</mark>, o la <mark class=\"m-personalizado\">víctima</mark> fuere <mark class=\"m-autoridad\">menor de</mark> <mark class=\"m-personalizado\">edad o</mark> <mark class=\"m-autoridad\">persona</mark> <mark class=\"m-personalizado\">con discapacidad necesitada de especial protección</mark>, <mark class=\"m-personalizado\">o funcionario público</mark> <mark class=\"m-personalizado\">en el ejercicio de sus funciones</mark>.</li></ul></div></div></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo</mark> 166: <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-1024,19-ia-1025\">🎯 2 preguntas más de este artículo</mark></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo</mark> 167: <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-1026\">🎯 1 pregunta más de este artículo</mark>"],["Artículo 172 <span class=\"ex-sello\">EX</span>","<p data-ex=\"EX\"><b>1.</b> <span class=\"ex-plg\"><span class=\"ex-plg-t\">El que, sin estar legítimamente autorizado, impidiere a otro con violencia hacer lo que la ley no prohíbe, o le compeliere a efectuar lo</span></span> que no quiere, <mark class=\"m-resp r-ia\" data-q=\"19-ia-1031\">sea justo o injusto</mark>, <mark class=\"m-accion\">será castigado</mark> con la pena de prisión de seis meses a tres años o con multa de 12 a 24 meses, según la gravedad de la coacción o de los medios empleados. <mark class=\"m-resp ex-q\" data-q=\"19-8,19-51,19-173,19-209\">🎯 4 preguntas</mark></p></div></div><div class=\"vis\"><div class=\"vis-t\"><i>⇄</i>DELITOS DE COACCIONES (cuadro del temario · art. 172.1)</div><div class=\"vis-comp\" style=\"--n:2\"><div class=\"vis-col\"><h5>El que, SIN ESTAR LEGÍTIMAMENTE AUTORIZADO</h5><ul><li>Impidiere a otro con <mark class=\"m-personalizado\">violencia</mark> hacer lo que la ley <u class=\"m-clave\">no</u> prohíbe.</li><li>Compeliere a otro a efectuar lo que <u class=\"m-clave\">no</u> quiere, sea justo o injusto.</li></ul></div><div class=\"vis-col\"><h5>PENA EN SU MITAD SUPERIOR</h5><ul><li>Impidiere a otro el <mark class=\"m-personalizado\">ejercicio</mark> de un <mark class=\"m-personalizado\">derecho</mark> fundamental (<mark class=\"m-personalizado\">salvo que</mark> el <u class=\"m-clave\">hecho</u> tuviera señalada mayor <mark class=\"m-personalizado\">pena</mark> en <mark class=\"m-personalizado\">otro precepto</mark> de <mark class=\"m-personalizado\">este Código</mark>).</li><li>Impidiere a otro el <mark class=\"m-personalizado\">legítimo disfrute de la vivienda</mark>.</li></ul></div></div></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo</mark> 172 bis: <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-1032,19-ia-1033\">🎯 2 preguntas más de este artículo</mark>"],["Artículo <mark class=\"m-personalizado\">172 ter</mark>","<p><b><mark class=\"m-personalizado\">1.</mark></b> <mark class=\"m-accion\">Será castigado</mark> con la pena de prisión de tres meses a dos años o multa de seis a veinticuatro meses el que acose a una <mark class=\"m-autoridad\">persona</mark> llevando a cabo de forma insistente y reiterada, y sin estar legítimamente autorizado, alguna de las conductas siguientes y, de esta forma, altere el normal desarrollo de su vida cotidiana:  <mark class=\"m-resp ex-q\" data-q=\"19-98\">🎯 1 pregunta</mark></p><p><b>3.ª</b> Mediante el uso indebido de sus datos personales, <mark class=\"m-resp\" data-q=\"19-260\">adquiera productos o mercancías, o contrate servicios, o haga que terceras <mark class=\"m-autoridad\">personas</mark> se pongan en contacto con ella</mark>.</p></div></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo</mark> 172 quater: <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-1034,19-ia-1035\">🎯 2 preguntas más de este artículo</mark>"],["Artículo 173","<p><b>2.</b> <mark class=\"m-personalizado\">El</mark> que habitualmente ejerza violencia <span class=\"ex-plg\"><span class=\"ex-plg-t\">física o psíquica sobre quien sea o haya sido su cónyuge o sobre <mark class=\"m-autoridad\">persona</mark> que esté o haya estado</span></span> ligada a él por una <mark class=\"m-resp r-ia\" data-q=\"19-ia-1037\">análoga relación de afectividad aun sin convivencia</mark>, o sobre los descendientes, ascendientes o hermanos por naturaleza, adopción o afinidad, propios o del cónyuge o conviviente, o sobre los <mark class=\"m-autoridad\">menores o personas</mark> con discapacidad necesitadas de especial protección que con él convivan o que se hallen sujetos a la potestad, tutela, curatela, acogimiento o guarda de hecho del cónyuge o conviviente, o sobre <mark class=\"m-autoridad\">persona</mark> amparada en cualquier otra relación por la que se encuentre integrada en el núcleo de su convivencia familiar, así como sobre las <mark class=\"m-autoridad\">personas</mark> que por su especial vulnerabilidad se encuentran sometidas a custodia o guarda en centros públicos o privados, <mark class=\"m-accion\">será castigado</mark> con la pena de prisión de seis meses a tres años, privación del derecho a la tenencia y porte de armas de tres a cinco años y, en su caso, cuando el <mark class=\"m-autoridad\">juez o tribunal</mark> lo estime adecuado al interés del <mark class=\"m-autoridad\">menor o persona</mark> con discapacidad necesitada de especial protección, inhabilitación especial para el ejercicio de la patria potestad, tutela, curatela, guarda o acogimiento por tiempo de uno a cinco años, sin perjuicio de las penas que pudieran corresponder a los delitos en que se hubieran concretado los actos de violencia física o psíquica.</p><p><b>3.</b> Para apreciar la habitualidad a <span class=\"ex-plg\"><span class=\"ex-plg-t\">que se refiere el apartado anterior, <mark class=\"m-accion\">se atenderá</mark> al <mark class=\"m-personalizado\">número de actos</mark> de violencia que resulten acreditados, así como a la proximidad temporal de los mismos, <mark class=\"m-personalizado\">con</mark> independencia de que dicha violencia</span></span> se haya ejercido sobre la <mark class=\"m-resp r-ia\" data-q=\"19-ia-1038\">misma o diferentes víctimas de las comprendidas en este artículo</mark>, <span class=\"ex-plg\"><span class=\"ex-plg-t\">y de que los actos violentos hayan sido o no <mark class=\"m-personalizado\">objeto de enjuiciamiento</mark> en procesos anteriores.</span></span> <mark class=\"m-resp ex-q\" data-q=\"19-94,19-ia-1039\">🎯 2 preguntas</mark></p><p>Los delitos tipificados en los dos <span class=\"ex-plg\"><span class=\"ex-plg-t\">párrafos anteriores sólo <mark class=\"m-accion\">serán</mark> perseguibles mediante denuncia de la <mark class=\"m-autoridad\">persona</mark> agraviada o su representante legal.</span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-1040\">🎯 1 pregunta</mark></p></div></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo</mark> 174: <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-1041\">🎯 1 pregunta más de este artículo</mark></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo</mark> 177: <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-1101\">🎯 1 pregunta más de este artículo</mark>"],["Artículo 177 bis <span class=\"ex-sello\">EXOF</span> <span class=\"ex-sello\">EX</span>","<p data-ex=\"EXOF\"><b>1.</b> <mark class=\"m-accion\">Será castigado</mark> con la pena de cinco a ocho años de prisión como reo de trata de seres humanos el que, sea en territorio español, sea desde España, en tránsito <mark class=\"m-personalizado\">o</mark> con destino <mark class=\"m-personalizado\">a ella,</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">empleando violencia, intimidación o engaño, o abusando de una</span></span> situación de superioridad <span class=\"m-caja\">o</span> de necesidad o de vulnerabilidad de la víctima nacional o <mark class=\"m-autoridad\">extranjera,</mark> o mediante la <mark class=\"m-personalizado\">entrega o recepción</mark> de pagos o beneficios para lograr el consentimiento de la <mark class=\"m-autoridad\">persona</mark> que <mark class=\"m-personalizado\">poseyera el control sobre la víctima, la captare, transportare,</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">trasladare, acogiere, o recibiere, incluido el intercambio o transferencia de</span></span> control sobre esas <mark class=\"m-autoridad\">personas,</mark> con cualquiera de las finalidades siguientes: <mark class=\"m-resp ex-q\" data-q=\"19-150,19-277,19-ia-1102\">🎯 3 preguntas</mark></p><p style=\"margin-left:18px\" data-ex=\"EX\"><b>b)</b> La <mark class=\"m-personalizado\">explotación sexual,</mark> incluyendo la pornografía.</p><p><b><mark class=\"m-accion\">3.</mark></b> <mark class=\"m-accion\">El consentimiento de una víctima de trata de seres humanos será irrelevante cuando se haya recurrido a</mark> alguno de los <span class=\"ex-plg\"><span class=\"ex-plg-t\">medios indicados en el apartado primero de este artículo.</span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-1104\">🎯 1 pregunta</mark></p><p style=\"margin-left:18px\" data-ex=\"EX\"><b>b)</b> la víctima sea especialmente vulnerable por razón de <mark class=\"m-resp\" data-q=\"19-278\">enfermedad, estado gestacional, discapacidad o situación personal, o sea <mark class=\"m-autoridad\">menor</mark> de edad</mark>.</p><p><b>10.</b> Las condenas de <mark class=\"m-autoridad\">jueces o tribunales extranjeros</mark> por <span class=\"ex-plg\"><span class=\"ex-plg-t\">delitos de la misma naturaleza que los previstos en este artículo <mark class=\"m-accion\">producirán</mark> los efectos de reincidencia, salvo que</span></span> el antecedente penal haya sido <mark class=\"m-resp r-ia\" data-q=\"19-ia-1105\">cancelado o pueda serlo con arreglo al Derecho español</mark>.</p><p><b>11.</b> Sin perjuicio de la aplicación <span class=\"ex-plg\"><span class=\"ex-plg-t\">de las reglas generales de este Código, la víctima de trata de seres humanos <mark class=\"m-accion\">quedará</mark> exenta de pena por las infracciones penales que haya cometido en la situación de explotación sufrida, siempre que su participación en ellas haya sido consecuencia directa de la situación de violencia, intimidación, engaño o abuso a que haya sido sometida y que</span></span> exista una adecuada proporcionalidad entre <mark class=\"m-resp r-ia\" data-q=\"19-ia-1106\">dicha situación y el hecho criminal realizado</mark>.</p>"],["Artículo 178 <span class=\"ex-sello\">EX</span>","<p data-ex=\"EX\"><b>1.</b> <mark class=\"m-accion\">Será castigado</mark> con la pena de <mark class=\"m-personalizado\">prisión</mark> de uno a cuatro años, como <mark class=\"m-autoridad\">responsable de agresión sexual,</mark> el que realice <mark class=\"m-personalizado\">cualquier acto</mark> que atente contra la <mark class=\"m-personalizado\">libertad sexual</mark> de otra <mark class=\"m-autoridad\">persona</mark> <mark class=\"m-personalizado\">sin su consentimiento.</mark> <mark class=\"m-accion\">Sólo se entenderá</mark> que <mark class=\"m-personalizado\">hay</mark> <mark class=\"m-destacable\">consentimiento</mark> cuando <mark class=\"m-personalizado\">se</mark> haya <mark class=\"m-destacable\">manifestado libremente</mark> <mark class=\"m-personalizado\">mediante actos</mark> que, en atención a las <mark class=\"m-personalizado\">circunstancias del caso, expresen de manera clara la voluntad</mark> de la <mark class=\"m-autoridad\">persona.</mark> <mark class=\"m-resp ex-q\" data-q=\"19-279,19-ia-1107\">🎯 2 preguntas</mark></p><p><b>2.</b> <mark class=\"m-accion\">Se consideran en todo caso</mark> <mark class=\"m-destacable\">agresión sexual</mark> los <mark class=\"m-personalizado\">actos de contenido sexual</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">que se realicen <mark class=\"m-personalizado\">empleando violencia, intimidación o abuso</mark> de una situación de <mark class=\"m-personalizado\">superioridad o de vulnerabilidad</mark> de la víctima, así <mark class=\"m-personalizado\">como los que se</mark> ejecuten sobre <mark class=\"m-autoridad\">personas</mark> que se hallen privadas de <mark class=\"m-personalizado\">sentido o de cuya situación mental se abusare y</mark> los que se realicen cuando la víctima tenga <mark class=\"m-personalizado\">anulada por cualquier causa su voluntad.</mark></span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-1108\">🎯 1 pregunta</mark></p><p><b>4.</b> <mark class=\"m-autoridad\">El órgano sentenciador,</mark> <mark class=\"m-destacable\">razonándolo en la sentencia,</mark> y siempre que <mark class=\"m-destacable\">no medie violencia o intimidación o</mark> que la víctima tuviera <mark class=\"m-destacable\">anulada</mark> por cualquier causa su voluntad <mark class=\"m-destacable\">o no concurran las circunstancias</mark> del artículo 180, <mark class=\"m-accion\">podrá imponer</mark> la pena de prisión en su <mark class=\"m-personalizado\">mitad inferior o multa</mark> de dieciocho a veinticuatro meses, en atención a la <mark class=\"m-autoridad\">menor</mark> entidad del hecho y a las circunstancias personales del culpable.  <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-1109\">🎯 1 pregunta</mark></p>"],["Artículo 179","<p><b>1.</b> Cuando la agresión sexual consista en <mark class=\"m-destacable\">acceso carnal</mark> por <mark class=\"m-personalizado\">vía vaginal, anal o bucal,</mark> <mark class=\"m-destacable\">o introducción</mark> de <mark class=\"m-personalizado\">miembros corporales u objetos</mark> por alguna de <mark class=\"m-personalizado\">las dos primeras vías,</mark> el responsable <mark class=\"m-accion\">será castigado</mark> como reo <mark class=\"m-personalizado\">de violación</mark> con la pena de prisión de cuatro a doce años.  <mark class=\"m-resp ex-q\" data-q=\"19-86,19-112\">🎯 2 preguntas</mark></p></div></div><div class=\"vis\"><div class=\"vis-t\"><i>⇄</i>AGRESIÓN SEXUAL (cuadro del temario · arts. 178, 179 y 180)</div><div class=\"vis-comp\" style=\"--n:3\"><div class=\"vis-col\"><h5>TIPO BÁSICO · art. 178 · Agresión sexual</h5><ul><li>El que realice <mark class=\"m-personalizado\">cualquier acto</mark> que atente <mark class=\"m-autoridad\">contra</mark> la <u class=\"m-clave\">libertad</u> <u class=\"m-clave\">sexual</u> de otra <mark class=\"m-autoridad\">persona</mark> <u class=\"m-clave\">sin su consentimiento</u>.</li><li><mark class=\"m-personalizado\">Hay</mark> <mark class=\"m-personalizado\">consentimiento</mark> <mark class=\"m-personalizado\">cuando</mark> se <mark class=\"m-personalizado\">haya</mark> <mark class=\"m-destacable\">manifestado libremente</mark> <mark class=\"m-personalizado\">mediante actos</mark> que, en atención a las <mark class=\"m-personalizado\">circunstancias del caso, expresen de manera clara la voluntad</mark> de la <mark class=\"m-autoridad\">persona</mark>.</li><li><mark class=\"m-accion\">Se consideran en todo caso</mark> agresión <u class=\"m-clave\">sexual</u> los <mark class=\"m-personalizado\">actos de</mark> contenido <u class=\"m-clave\">sexual</u> que se <u class=\"m-clave\">realicen</u> empleando: <mark class=\"m-destacable\">violencia, intimidación</mark> o abuso de una <mark class=\"m-destacable\">situación</mark> de <mark class=\"m-personalizado\">superioridad o de vulnerabilidad</mark> de la <mark class=\"m-personalizado\">víctima</mark>; los que se ejecuten sobre <mark class=\"m-autoridad\">personas</mark> privadas de sentido o <mark class=\"m-personalizado\">de cuya</mark> <mark class=\"m-destacable\">situación</mark> mental se abusare; y los que se <u class=\"m-clave\">realicen</u> <mark class=\"m-personalizado\">cuando</mark> la <mark class=\"m-personalizado\">víctima</mark> tenga <mark class=\"m-personalizado\">anulada por cualquier causa su voluntad</mark>.</li></ul></div><div class=\"vis-col\"><h5>TIPO CUALIFICADO · art. 179 · Violación sexual</h5><ul><li><mark class=\"m-personalizado\">Cuando</mark> la agresión <u class=\"m-clave\">sexual</u> consista en <mark class=\"m-destacable\">acceso carnal</mark> por <mark class=\"m-personalizado\">vía vaginal, anal o bucal</mark>, o en <mark class=\"m-destacable\">introducción</mark> de <u class=\"m-clave\">miembros</u> <mark class=\"m-personalizado\">corporales</mark> u objetos por <mark class=\"m-personalizado\">alguna</mark> de las <u class=\"m-clave\">dos</u> primeras vías.</li></ul></div><div class=\"vis-col\"><h5>SUBTIPOS CUALIFICADOS · art. 180 · Circunstancias</h5><ul><li><u class=\"m-clave\">Actuación</u> conjunta de <u class=\"m-clave\">dos</u> o más <mark class=\"m-autoridad\">personas</mark>.</li><li>Agresión <u class=\"m-clave\">sexual</u> precedida o acompañada de <mark class=\"m-destacable\">violencia de extrema gravedad o</mark> de <mark class=\"m-personalizado\">actos</mark> con <u class=\"m-clave\">carácter</u> <mark class=\"m-destacable\">particularmente degradante o vejatorio</mark>.</li><li><mark class=\"m-destacable\">Hechos</mark> <mark class=\"m-personalizado\">cometidos</mark> <mark class=\"m-autoridad\">contra</mark> una <mark class=\"m-autoridad\">persona</mark> en <mark class=\"m-destacable\">situación de especial vulnerabilidad por</mark> <u class=\"m-clave\">razón</u> de <mark class=\"m-personalizado\">su edad, enfermedad, discapacidad o</mark> <mark class=\"m-personalizado\">cualquier otra</mark> circunstancia, <mark class=\"m-personalizado\">salvo</mark> lo dispuesto en <mark class=\"m-personalizado\">el artículo</mark> 181.</li><li><mark class=\"m-personalizado\">La víctima sea</mark> o <mark class=\"m-personalizado\">haya</mark> <u class=\"m-clave\">sido</u> <mark class=\"m-destacable\">esposa o mujer</mark> ligada por <mark class=\"m-personalizado\">análoga relación</mark> de afectividad, <mark class=\"m-personalizado\">aun</mark> <u class=\"m-clave\">sin</u> <u class=\"m-clave\">convivencia</u>.</li><li><mark class=\"m-personalizado\">El responsable</mark> se <u class=\"m-clave\">hubiera</u> <mark class=\"m-personalizado\">prevalido</mark> de una <mark class=\"m-destacable\">situación</mark> o relación de <u class=\"m-clave\">convivencia</u> <mark class=\"m-destacable\">o de parentesco</mark> o de una relación de <mark class=\"m-destacable\">superioridad</mark> <mark class=\"m-personalizado\">respecto</mark> a la <mark class=\"m-personalizado\">víctima</mark>.</li><li><mark class=\"m-personalizado\">Uso</mark> de <u class=\"m-clave\">armas</u> u otros <u class=\"m-clave\">medios</u> <mark class=\"m-personalizado\">igualmente</mark> <mark class=\"m-personalizado\">peligrosos</mark>, <mark class=\"m-personalizado\">susceptibles</mark> de producir <mark class=\"m-personalizado\">la muerte</mark> o <mark class=\"m-personalizado\">alguna</mark> de <mark class=\"m-personalizado\">las lesiones</mark> de los artículos 149 y 150, <u class=\"m-clave\">sin</u> <mark class=\"m-personalizado\">perjuicio</mark> del <mark class=\"m-personalizado\">artículo</mark> 194 bis.</li><li>Haber <mark class=\"m-destacable\">anulado la voluntad</mark> de la <mark class=\"m-personalizado\">víctima</mark> suministrándole <mark class=\"m-personalizado\">fármacos, drogas o cualquier otra sustancia</mark> natural o química idónea.</li></ul></div></div></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo</mark> 180: <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-1111,19-ia-1112,19-ia-1113,19-ia-1114,19-ia-1115\">🎯 5 preguntas más de este artículo</mark>"],["Artículo 181","<p><b>1.</b> El que <mark class=\"m-accion\">realizare</mark> actos <mark class=\"m-autoridad\">de carácter sexual con un menor de <mark class=\"m-resp r-ia\" data-q=\"19-ia-1116\">dieciséis años</mark>,</mark> <mark class=\"m-accion\">será castigado</mark> con la pena de <mark class=\"m-personalizado\">prisión</mark> de dos a seis años.</p><p>A estos efectos se consideran <mark class=\"m-personalizado\">incluidos</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">en los actos de carácter sexual los que <mark class=\"m-personalizado\">realice el</mark> <mark class=\"m-autoridad\">menor</mark> <mark class=\"m-personalizado\">con un tercero o sobre sí mismo a instancia del autor.</mark></span></span>  <mark class=\"m-resp ex-q\" data-q=\"19-2,19-ia-1117\">🎯 2 preguntas</mark></p><p style=\"margin-left:18px\"><b><mark class=\"m-destacable\">c)</mark></b> Cuando los hechos se cometan contra una <mark class=\"m-autoridad\">persona</mark> que se halle en una <mark class=\"m-destacable\">situación de especial vulnerabilidad por</mark> razón de su edad, enfermedad, discapacidad <mark class=\"m-destacable\">o por cualquier otra circunstancia, y, en todo caso, cuando sea</mark> <mark class=\"m-autoridad\">menor</mark> <mark class=\"m-destacable\">de <mark class=\"m-resp r-ia\" data-q=\"19-ia-1118\">cuatro años</mark>.</mark> <mark class=\"m-resp ex-q\" data-q=\"19-83\">🎯 1 pregunta</mark></p><p style=\"margin-left:18px\"><b>h)</b> Cuando la infracción se haya <span class=\"ex-plg\"><span class=\"ex-plg-t\">cometido en el <mark class=\"m-destacable\">seno de una organización o de un grupo criminal</mark> que se dedicare a la realización de tales actividades.</span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-1119\">🎯 1 pregunta</mark></p><p><b>7.</b> En todos los casos previstos en este artículo, cuando el culpable se hubiera prevalido de su <mark class=\"m-personalizado\">condición</mark> de <mark class=\"m-autoridad\">autoridad, agente de esta o funcionario público,</mark> <mark class=\"m-accion\">se impondrá,</mark> <mark class=\"m-personalizado\">además,</mark> la pena de <mark class=\"m-personalizado\"><mark class=\"m-resp r-ia\" data-q=\"19-ia-1120\">inhabilitación absoluta</mark></mark> de seis a doce años.</p></div></div><div class=\"vis\"><div class=\"vis-t\"><i>⇄</i>AGRESIONES SEXUALES A MENORES DE DIECISÉIS AÑOS (cuadro del temario · art. 181)</div><div class=\"vis-comp\" style=\"--n:3\"><div class=\"vis-col\"><h5>ACTOS DE CARÁCTER SEXUAL · art. 181</h5><ul><li>El que <mark class=\"m-accion\">realizare</mark> <mark class=\"m-personalizado\">actos de</mark> <u class=\"m-clave\">carácter</u> <u class=\"m-clave\">sexual</u> con un <mark class=\"m-autoridad\">menor de</mark> dieciséis <mark class=\"m-personalizado\">años</mark>, o los que <mark class=\"m-personalizado\">realice el</mark> <mark class=\"m-autoridad\">menor</mark> con un <mark class=\"m-personalizado\">tercero</mark> o sobre sí <u class=\"m-clave\">mismo</u> a instancia del <mark class=\"m-autoridad\">autor</mark>.</li><li>O el <mark class=\"m-personalizado\">acto</mark> <u class=\"m-clave\">sexual</u> consista en <mark class=\"m-destacable\">acceso carnal</mark> por <mark class=\"m-personalizado\">vía vaginal, anal o bucal</mark>, o en <mark class=\"m-destacable\">introducción</mark> de <u class=\"m-clave\">miembros</u> <mark class=\"m-personalizado\">corporales</mark> u objetos por <mark class=\"m-personalizado\">alguna</mark> de las <u class=\"m-clave\">dos</u> primeras vías.</li><li>Las <mark class=\"m-personalizado\">conductas</mark> <mark class=\"m-accion\">serán castigadas</mark> <mark class=\"m-personalizado\">con la pena de prisión</mark> correspondiente en su <mark class=\"m-plazo\"><u class=\"m-clave\">mitad</u> <u class=\"m-clave\">superior</u></mark> <mark class=\"m-personalizado\">cuando</mark> <mark class=\"m-personalizado\">concurra alguna</mark> <mark class=\"m-personalizado\">de las siguientes</mark> <mark class=\"m-personalizado\">circunstancias</mark>:</li></ul></div><div class=\"vis-col\"><h5>CIRCUNSTANCIAS (1)</h5><ul><li><u class=\"m-clave\">Actuación</u> conjunta de <u class=\"m-clave\">dos</u> o más <mark class=\"m-autoridad\">personas</mark>.</li><li>Agresión <u class=\"m-clave\">sexual</u> precedida o acompañada de <mark class=\"m-destacable\">violencia de extrema gravedad o</mark> de <mark class=\"m-personalizado\">actos</mark> particularmente degradantes o vejatorios.</li><li><mark class=\"m-destacable\">Hechos</mark> <mark class=\"m-autoridad\">contra</mark> <mark class=\"m-autoridad\">persona</mark> en <mark class=\"m-destacable\">situación de especial vulnerabilidad por</mark> <u class=\"m-clave\">razón</u> de <mark class=\"m-personalizado\">su edad, enfermedad, discapacidad o</mark> <mark class=\"m-personalizado\">cualquier otra</mark> circunstancia y, <mark class=\"m-personalizado\">en todo caso</mark>, <mark class=\"m-personalizado\">cuando</mark> sea <mark class=\"m-autoridad\">menor</mark> <mark class=\"m-plazo\">de cuatro años</mark>.</li></ul></div><div class=\"vis-col\"><h5>CIRCUNSTANCIAS (2) y (3)</h5><ul><li><mark class=\"m-personalizado\">La víctima sea</mark> o <mark class=\"m-personalizado\">haya</mark> <u class=\"m-clave\">sido</u> pareja del <mark class=\"m-autoridad\">autor</mark>, <mark class=\"m-personalizado\">aun</mark> <u class=\"m-clave\">sin</u> <u class=\"m-clave\">convivencia</u>.</li><li><mark class=\"m-personalizado\">El responsable</mark> se <u class=\"m-clave\">hubiera</u> <mark class=\"m-personalizado\">prevalido</mark> de una relación de <u class=\"m-clave\">convivencia</u>, parentesco o <mark class=\"m-destacable\">superioridad</mark>.</li><li><mark class=\"m-personalizado\">Uso</mark> de <u class=\"m-clave\">armas</u> u otros <u class=\"m-clave\">medios</u> <mark class=\"m-personalizado\">igualmente</mark> <mark class=\"m-personalizado\">peligrosos</mark> (arts. 149 y 150, <u class=\"m-clave\">sin</u> <mark class=\"m-personalizado\">perjuicio</mark> del 194 bis).</li><li>Haber <mark class=\"m-destacable\">anulado la voluntad</mark> de la <mark class=\"m-personalizado\">víctima</mark> suministrándole <mark class=\"m-personalizado\">fármacos, drogas o cualquier otra sustancia</mark> idónea.</li><li><mark class=\"m-destacable\">La infracción</mark> se <mark class=\"m-personalizado\">haya</mark> <mark class=\"m-personalizado\">cometido</mark> en <mark class=\"m-personalizado\">el seno</mark> de una <u class=\"m-clave\">organización</u> o <mark class=\"m-destacable\">grupo criminal</mark> que se <mark class=\"m-personalizado\">dedicare a</mark> la <mark class=\"m-personalizado\">realización de tales actividades</mark>.</li></ul></div>"],["Artículo 182 <span class=\"ex-sello\">EXOF</span>","<p data-ex=\"EXAMEN,EXOF\"><b>1.</b> El que, con <mark class=\"m-personalizado\">fines sexuales, haga presenciar</mark> a un <mark class=\"m-autoridad\">menor de dieciséis años actos de carácter sexual,</mark> aunque el autor no participe en <mark class=\"m-personalizado\">ellos,</mark> <mark class=\"m-accion\">será castigado</mark> con una pena de <mark class=\"m-personalizado\">prisión</mark> de seis meses a dos años. <mark class=\"m-resp ex-q\" data-q=\"19-15,19-17,19-ia-1121\">🎯 3 preguntas</mark></p><p><b>2.</b> Si los actos de carácter sexual que se <mark class=\"m-personalizado\">hacen presenciar</mark> al <mark class=\"m-autoridad\">menor de dieciséis años constituyeran un delito contra la</mark> libertad sexual, la pena <mark class=\"m-accion\">será</mark> <mark class=\"m-personalizado\">de prisión</mark> de uno a tres años.  <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-1122\">🎯 1 pregunta</mark></p>"],["Artículo 187 <span class=\"ex-sello\">✱</span>","<p data-ex=\"*\"><b>1.</b> El que, <mark class=\"m-resp\" data-q=\"19-280\">empleando violencia, intimidación o engaño, o abusando de una situación de superioridad o de necesidad o vulnerabilidad de la víctima</mark>, determine a una <mark class=\"m-autoridad\">persona</mark> mayor de edad a ejercer o a mantenerse en la prostitución, <mark class=\"m-accion\"><mark class=\"m-resp r-ia\" data-q=\"19-ia-1130\">será castigado</mark></mark> con las penas de prisión de dos a cinco años y multa de doce a veinticuatro meses.</p><p style=\"margin-left:18px\"><b>a)</b> <mark class=\"m-resp\" data-q=\"19-225,19-ia-1131\">Que la víctima se encuentre en una situación de vulnerabilidad personal o económica</mark>.</p><p style=\"margin-left:18px\"><b>c)</b> Cuando el culpable hubiere puesto en peligro, de forma dolosa o por imprudencia grave, la <mark class=\"m-resp r-ia\" data-q=\"19-ia-1132\">vida o salud de la víctima</mark>.</p></div></div><div class=\"vis\"><div class=\"vis-t\"><i>⇄</i>PROSTITUCIÓN DE MAYORES DE EDAD (cuadro del temario · art. 187)</div><div class=\"vis-comp\" style=\"--n:2\"><div class=\"vis-col\"><h5>TIPO BÁSICO · art. 187.1</h5><ul><li>El que, empleando <mark class=\"m-destacable\">violencia, intimidación</mark> o <mark class=\"m-personalizado\">engaño</mark>, o abusando de una <mark class=\"m-destacable\">situación</mark> de <mark class=\"m-destacable\">superioridad</mark>, <u class=\"m-clave\">necesidad</u> o vulnerabilidad, determine a una <mark class=\"m-autoridad\">persona</mark> mayor <mark class=\"m-personalizado\">de edad</mark> a <mark class=\"m-accion\">ejercer</mark> o mantenerse en la <mark class=\"m-personalizado\">prostitución</mark>.</li><li><u class=\"m-clave\">Quien</u> se lucre explotando la <mark class=\"m-personalizado\">prostitución</mark> de otra <mark class=\"m-autoridad\">persona</mark>, <u class=\"m-clave\">aun con el consentimiento</u> de la <u class=\"m-clave\">misma</u>. <mark class=\"m-personalizado\">Hay</mark> explotación <mark class=\"m-personalizado\">cuando</mark> <mark class=\"m-personalizado\">concurra alguna</mark> de estas <mark class=\"m-personalizado\">circunstancias</mark>: que la <mark class=\"m-personalizado\">víctima</mark> se encuentre en <mark class=\"m-destacable\">situación</mark> de vulnerabilidad <u class=\"m-clave\">personal</u> o económica; que se le impongan para su <mark class=\"m-personalizado\">ejercicio</mark> <mark class=\"m-destacable\">condiciones</mark> gravosas, desproporcionadas o abusivas.</li></ul></div><div class=\"vis-col\"><h5>TIPO CUALIFICADO · art. 187.2 · AGRAVANTE → MITAD SUPERIOR</h5><ul><li>Prevalerse de su <mark class=\"m-personalizado\">condición</mark> <mark class=\"m-autoridad\">de autoridad, agente de ésta o funcionario público</mark>.</li><li>Pertenecer a una <u class=\"m-clave\">organización</u> o <mark class=\"m-destacable\">grupo criminal</mark> que se <mark class=\"m-personalizado\">dedicare a</mark> la <mark class=\"m-personalizado\">realización de tales actividades</mark>.</li><li>Poner en <u class=\"m-clave\">peligro</u>, <mark class=\"m-personalizado\">de forma</mark> dolosa o por <u class=\"m-clave\">imprudencia</u> <u class=\"m-clave\">grave</u>, la <mark class=\"m-personalizado\">vida</mark> <mark class=\"m-personalizado\">o salud de</mark> la <mark class=\"m-personalizado\">víctima</mark>.</li></ul></div>"],["Artículo 188","<p><b>1.</b> <mark class=\"m-personalizado\">El que <u class=\"m-clave\"><mark class=\"m-resp\" data-q=\"19-127\">induzca</mark>, promueva, favorezca</u> o <u class=\"m-clave\">facilite</u> la prostitución de un</mark> <mark class=\"m-autoridad\">menor</mark> de edad o una <mark class=\"m-autoridad\">persona</mark> con <span class=\"m-circulo\"><mark class=\"m-destacable\">discapacidad</mark></span> <mark class=\"m-personalizado\">necesitada de especial protección, o se lucre</mark> con ello, o <mark class=\"m-personalizado\"><u class=\"m-clave\">explote</u></mark> de algún otro modo a un <mark class=\"m-autoridad\">menor</mark> o a una <mark class=\"m-autoridad\">persona</mark> con discapacidad para estos fines, <mark class=\"m-accion\">será castigado</mark> con las penas de prisión de dos a cinco años y multa de doce a veinticuatro meses. <mark class=\"m-resp ex-q\" data-q=\"19-133\">🎯 1 pregunta</mark></p><p>Si la víctima fuera <mark class=\"m-autoridad\">menor de</mark> <mark class=\"m-resp r-ia\" data-q=\"19-ia-1133\">dieciséis años</mark>, <mark class=\"m-accion\">se impondrá</mark> la pena de prisión de cuatro a ocho años y multa de doce a veinticuatro meses.</p><p style=\"margin-left:18px\"><b>a)</b> Cuando la víctima se halle <span class=\"ex-plg\"><span class=\"ex-plg-t\"><u class=\"m-clave\">en</u> una situación de <mark class=\"m-personalizado\">especial vulnerabilidad</mark> por razón de <mark class=\"m-personalizado\">su edad, enfermedad, discapacidad <u class=\"m-clave\">o</u></mark> por cualquier <mark class=\"m-personalizado\">otra</mark> circunstancia.</span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-1134\">🎯 1 pregunta</mark></p>"],["Artículo 189 <span class=\"ex-sello\">✱</span>","<p style=\"margin-left:18px\"><b>a)</b> El que captare o utilizare <span class=\"ex-plg\"><span class=\"ex-plg-t\">a <mark class=\"m-autoridad\">menores</mark> de edad o a <mark class=\"m-autoridad\">personas</mark> con discapacidad necesitadas de especial protección con fines o en espectáculos exhibicionistas o pornográficos, tanto públicos como privados, o para elaborar cualquier clase de material pornográfico, cualquiera</span></span> que sea su soporte, o <mark class=\"m-resp r-ia\" data-q=\"19-ia-1202\">financiare cualquiera de estas actividades o se lucrare con ellas</mark>.</p><p style=\"margin-left:18px\"><b>b)</b> El que produjere, vendiere, distribuyere, <span class=\"ex-plg\"><span class=\"ex-plg-t\">exhibiere, ofreciere o facilitare la producción, venta, difusión o exhibición por cualquier medio de pornografía infantil o en cuya elaboración hayan sido utilizadas <mark class=\"m-autoridad\">personas</mark> con discapacidad necesitadas de especial protección, o</span></span> lo poseyere para estos fines, <mark class=\"m-resp r-ia\" data-q=\"19-ia-1203\">aunque el material tuviere su origen en el <mark class=\"m-autoridad\">extranjero</mark> o fuere desconocido</mark>.</p><p style=\"margin-left:18px\"><b>c)</b> Todo material que represente de <span class=\"ex-plg\"><span class=\"ex-plg-t\">forma visual a una <mark class=\"m-autoridad\">persona</mark> que parezca ser un <mark class=\"m-autoridad\">menor</mark> participando en una conducta sexualmente explícita, real o simulada, o cualquier representación de los <mark class=\"m-autoridad\">órganos</mark> sexuales de una <mark class=\"m-autoridad\">persona</mark> que parezca ser un <mark class=\"m-autoridad\">menor,</mark> con fines principalmente sexuales, salvo que la <mark class=\"m-autoridad\">persona</mark> que parezca ser un</span></span> <mark class=\"m-autoridad\">menor</mark> resulte tener en realidad <mark class=\"m-resp r-ia\" data-q=\"19-ia-1205\">dieciocho años o más en el momento de obtenerse las imágenes</mark>. <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-1204\">🎯 1 pregunta</mark></p><p style=\"margin-left:18px\"><b>d)</b> Imágenes realistas de un <mark class=\"m-autoridad\">menor</mark> participando en una conducta sexualmente explícita o <mark class=\"m-resp r-ia\" data-q=\"19-ia-1206\">imágenes realistas de los <mark class=\"m-autoridad\">órganos</mark> sexuales de un <mark class=\"m-autoridad\">menor,</mark> con fines principalmente sexuales</mark>.</p><p style=\"margin-left:18px\"><b>c)</b> Cuando se utilice a <mark class=\"m-autoridad\">personas menores</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">de edad que <u class=\"m-clave\">se</u> hallen en una <mark class=\"m-personalizado\">situación de especial vulnerabilidad</mark> por razón de <mark class=\"m-personalizado\">enfermedad, discapacidad o</mark> por cualquier <mark class=\"m-personalizado\">otra</mark> circunstancia.</span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-1207\">🎯 1 pregunta</mark></p><p style=\"margin-left:18px\"><b>e)</b> Cuando el <mark class=\"m-personalizado\">material</mark> pornográfico fuera de <mark class=\"m-personalizado\"><u class=\"m-clave\">notoria</u> importancia.</mark> <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-1208\">🎯 1 pregunta</mark></p><p style=\"margin-left:18px\"><b>g)</b> Cuando el <mark class=\"m-personalizado\">responsable sea <u class=\"m-clave\">ascendiente,</u> tutor, curador, guardador, maestro o cualquier</mark> otra <mark class=\"m-autoridad\">persona</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-personalizado\">encargada, de hecho, aunque fuera provisionalmente, o</mark> de <mark class=\"m-personalizado\">derecho,</mark> de la <mark class=\"m-autoridad\">persona menor</mark> de <mark class=\"m-personalizado\">edad o</mark> <mark class=\"m-autoridad\">persona</mark> <mark class=\"m-personalizado\">con</mark> discapacidad necesitada de especial protección, <mark class=\"m-personalizado\">o se</mark> trate de cualquier <mark class=\"m-autoridad\">persona</mark> que <mark class=\"m-personalizado\"><u class=\"m-clave\">conviva</u> con él o</mark> de otra <mark class=\"m-autoridad\">persona</mark> que haya <mark class=\"m-personalizado\">actuado abusando</mark> de su posición reconocida de <mark class=\"m-personalizado\">confianza o</mark> <mark class=\"m-autoridad\">autoridad.</mark></span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-1209\">🎯 1 pregunta</mark></p><p style=\"margin-left:18px\"><b>h)</b> Cuando concurra la agravante de <mark class=\"m-personalizado\"><mark class=\"m-resp r-ia\" data-q=\"19-ia-1210\">reincidencia</mark>.</mark></p><p><b>4.</b> <mark class=\"m-personalizado\">El que asistiere <u class=\"m-clave\">a sabiendas</u> a <u class=\"m-clave\">espectáculos</u> exhibicionistas o pornográficos</mark> en los que participen <mark class=\"m-autoridad\">menores</mark> <mark class=\"m-personalizado\">de edad o</mark> <mark class=\"m-autoridad\">personas</mark> con <mark class=\"m-personalizado\">discapacidad</mark> necesitadas de especial protección, <mark class=\"m-accion\"><mark class=\"m-resp r-ia\" data-q=\"19-ia-1211\">será castigado</mark></mark> con la pena de seis meses a dos años de <mark class=\"m-personalizado\">prisión.</mark></p><p><b>5.</b> <mark class=\"m-personalizado\">El que para su propio uso <u class=\"m-clave\">adquiera o posea pornografía infantil</u> o</mark> en cuya elaboración se hubieran <mark class=\"m-personalizado\">utilizado</mark> <mark class=\"m-autoridad\">personas</mark> <mark class=\"m-personalizado\">con discapacidad necesitadas de</mark> especial protección, <mark class=\"m-accion\"><mark class=\"m-resp r-ia\" data-q=\"19-ia-1212\">será castigado</mark></mark> con la pena de tres meses a un año de prisión o con multa de seis meses a dos años.</p><p>La <mark class=\"m-personalizado\">misma pena</mark> <mark class=\"m-accion\">se impondrá</mark> <mark class=\"m-personalizado\">a quien <u class=\"m-clave\">acceda</u> a sabiendas a</mark> pornografía infantil <span class=\"ex-plg\"><span class=\"ex-plg-t\">o en cuya elaboración se hubieran utilizado <mark class=\"m-autoridad\">personas</mark> con discapacidad necesitadas de especial protección, <mark class=\"m-personalizado\"><mark class=\"m-resp r-ia\" data-q=\"19-ia-1213\">por medio de las tecnologías de la información y la comunicación</mark>.</mark></span></span></p><p data-ex=\"*\"><b>6.</b> <mark class=\"m-personalizado\">El que tuviere bajo su <u class=\"m-clave\">potestad,</u> tutela, guarda o acogimiento</mark> a un <mark class=\"m-autoridad\">menor</mark> de edad o <mark class=\"m-personalizado\">una</mark> <mark class=\"m-autoridad\">persona</mark> con discapacidad necesitada de especial protección y que, con <mark class=\"m-personalizado\">conocimiento de su estado</mark> de prostitución o <mark class=\"m-personalizado\">corrupción, no haga lo posible para <u class=\"m-clave\">impedir</u></mark> <u class=\"m-clave\">su</u> continuación en <mark class=\"m-personalizado\">tal</mark> estado, <mark class=\"m-personalizado\">o no <u class=\"m-clave\">acuda a la</u></mark> <mark class=\"m-autoridad\"><u class=\"m-clave\">autoridad</u> competente</mark> para el mismo <mark class=\"m-personalizado\">fin <u class=\"m-clave\">si carece de medios</u> para la custodia</mark> del <mark class=\"m-autoridad\">menor o persona</mark> con discapacidad necesitada de especial protección, <mark class=\"m-accion\"><mark class=\"m-resp r-ia\" data-q=\"19-ia-1214\">será castigado</mark></mark> con la pena de <mark class=\"m-personalizado\">prisión</mark> de tres a seis meses o multa de seis a doce meses.</p><p><b>7.</b> El <mark class=\"m-autoridad\">Ministerio Fiscal</mark> <mark class=\"m-accion\">promoverá</mark> las acciones <span class=\"ex-plg\"><span class=\"ex-plg-t\">pertinentes con objeto de privar de <mark class=\"m-personalizado\">la patria potestad,</mark> tutela, guarda o acogimiento familiar, en su caso, a la <mark class=\"m-autoridad\">persona</mark> que incurra en alguna de</span></span> las conductas descritas en el <mark class=\"m-resp r-ia\" data-q=\"19-ia-1215\">apartado anterior</mark>.</p><p><b>8.</b> Los <mark class=\"m-autoridad\">jueces y tribunales</mark> <mark class=\"m-accion\">ordenarán</mark> la adopción <span class=\"ex-plg\"><span class=\"ex-plg-t\">de las <mark class=\"m-personalizado\">medidas</mark> necesarias para <mark class=\"m-personalizado\">la retirada de las</mark> páginas web o aplicaciones de internet que contengan o difundan pornografía infantil o en cuya elaboración se hubieran utilizado <mark class=\"m-autoridad\">personas</mark> con discapacidad necesitadas de especial protección <mark class=\"m-personalizado\">o,</mark> en su caso, para bloquear el acceso a las mismas a los usuarios de Internet que se encuentren en <mark class=\"m-personalizado\"><u class=\"m-clave\">territorio</u> español.</mark></span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-1216\">🎯 1 pregunta</mark></p><p><mark class=\"m-personalizado\">Estas medidas</mark> <mark class=\"m-accion\">podrán ser acordadas</mark> <mark class=\"m-personalizado\">con carácter cautelar a petición del</mark> <mark class=\"m-autoridad\"><mark class=\"m-resp r-ia\" data-q=\"19-ia-1217\">Ministerio Fiscal</mark>.</mark></p></div></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo</mark> 189 bis: <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-1218,19-ia-1219\">🎯 2 preguntas más de este artículo</mark>"],["Artículo 193","<p><mark class=\"m-personalizado\">En las sentencias</mark> condenatorias por delitos contra la <span class=\"ex-plg\"><span class=\"ex-plg-t\">libertad sexual, <mark class=\"m-personalizado\">además</mark> del pronunciamiento correspondiente a la <mark class=\"m-personalizado\">responsabilidad civil,</mark> <mark class=\"m-accion\">se harán,</mark> <mark class=\"m-personalizado\">en su caso, los que procedan</mark> en orden a la <mark class=\"m-destacable\">filiación y <mark class=\"m-resp\" data-q=\"19-123\">fijación de alimentos</mark>.</mark></span></span> <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-1227\">🎯 1 pregunta</mark></p>"],["Artículo 196","<p>El profesional que, estando obligado a ello, <mark class=\"m-personalizado\">denegare asistencia sanitaria o abandonare los servicios sanitarios, cuando de</mark> la denegación o abandono se derive riesgo grave para la salud de las <mark class=\"m-autoridad\">personas,</mark> <mark class=\"m-accion\">será castigado</mark> con las penas del artículo precedente en su mitad superior y con la de inhabilitación especial para empleo o cargo público, profesión u oficio, por tiempo de seis meses a tres años.  <mark class=\"m-resp ex-q\" data-q=\"19-215,19-ia-1228\">🎯 2 preguntas</mark></p></div></div><div class=\"vis\"><div class=\"vis-t\"><i>▦</i>OMISIÓN DEL DEBER DE SOCORRO (cuadro del temario · arts. 195 y 196)</div><div class=\"vis-tabla\"><div class=\"vt-cab\"><span>Conducta típica</span><span>Requisitos</span></div><div class=\"vt-nodo\"><div class=\"vt-et o\">Omisión de socorro personal · art. 195.1</div><div class=\"vt-hijos\"><div class=\"vt-hoja\"><span class=\"vt-p o\">Conducta</span><div class=\"vt-t\">NO SOCORRER cuando pudiere hacerlo <u class=\"m-clave\">sin riesgo propio ni de terceros</u>.</div></div><div class=\"vt-hoja\"><span class=\"vt-p v\">Requisitos</span><div class=\"vt-t\">Sujeto pasivo: persona que se halle desamparada y en peligro manifiesto y grave.</div></div></div></div><div class=\"vt-nodo\"><div class=\"vt-et v\">Omisión de petición de socorro · art. 195.2</div><div class=\"vt-hijos\"><div class=\"vt-hoja\"><span class=\"vt-p o\">Conducta</span><div class=\"vt-t\">NO DEMANDAR con urgencia auxilio ajeno.</div></div><div class=\"vt-hoja\"><span class=\"vt-p v\">Requisitos</span><div class=\"vt-t\">Imposibilidad de prestar socorro.</div></div></div></div><div class=\"vt-nodo\"><div class=\"vt-et c\">Omisión de socorro a la víctima del accidente · art. 195.3</div><div class=\"vt-hijos\"><div class=\"vt-hoja\"><span class=\"vt-p o\">Conducta</span><div class=\"vt-t\">OMITIR AUXILIO a la víctima del accidente ocasionado.</div></div><div class=\"vt-hoja\"><span class=\"vt-p v\">Requisitos</span><div class=\"vt-t\">Que el accidente se haya ocasionado de forma fortuita o imprudente.</div></div></div></div><div class=\"vt-nodo\"><div class=\"vt-et o\">Omisión de prestar asistencia sanitaria · art. 196 (pena: MITAD SUPERIOR)</div><div class=\"vt-hijos\"><div class=\"vt-hoja\"><span class=\"vt-p o\">Conducta</span><div class=\"vt-t\">DENEGAR ASISTENCIA SANITARIA o ABANDONAR los SERVICIOS SANITARIOS.</div></div><div class=\"vt-hoja\"><span class=\"vt-p v\">Requisitos</span><div class=\"vt-t\">Sujeto activo: profesional obligado a prestar asistencia sanitaria. Que la denegación o abandono se derive riesgo grave para la salud de las personas.</div></div></div></div>"],["<mark class=\"m-destacable\">Artículo 208</mark>","<p>Las injurias que consistan en la imputación de hechos <mark class=\"m-accion\">no se considerarán</mark> graves, <mark class=\"m-resp\" data-q=\"19-274\">salvo cuando se hayan llevado a cabo con conocimiento de su falsedad o temerario desprecio hacia la verdad</mark>.</p></div></div><div class=\"vis\"><div class=\"vis-t\"><i>➜</i>DELITO DE INJURIAS · arts. 208 a 210 (cuadro del temario)</div><div class=\"vis-flujo\"><div class=\"vis-paso o\"><span class=\"et\">Conducta · art. 208</span><mark class=\"m-personalizado\">Acción</mark> o expresión que lesionen la dignidad de otra <mark class=\"m-autoridad\">persona</mark>, menoscaben su fama o <mark class=\"m-personalizado\">atenten contra su</mark> propia estimación. Solo son <mark class=\"m-personalizado\">delito</mark> las <mark class=\"m-personalizado\">que, por</mark> su naturaleza, <mark class=\"m-personalizado\">efectos</mark> y <mark class=\"m-personalizado\">circunstancias</mark>, <u class=\"m-clave\">sean</u> tenidas en el concepto <mark class=\"m-destacable\">público</mark> por <mark class=\"m-plazo\">graves</mark>.</div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso v\"><span class=\"et\">«Exceptio veritatis» · art. 210</span>El acusado de injuria <mark class=\"m-accion\">quedará</mark> <u class=\"m-clave\">EXENTO</u> de responsabilidad probando la <u class=\"m-clave\">verdad</u> de las imputaciones <mark class=\"m-personalizado\">cuando</mark> éstas se dirijan <mark class=\"m-autoridad\">contra</mark> <u class=\"m-clave\">funcionarios</u> <u class=\"m-clave\">públicos</u> sobre <mark class=\"m-destacable\">hechos</mark> concernientes al <mark class=\"m-personalizado\">ejercicio</mark> de sus cargos o referidos a la <mark class=\"m-autoridad\">comisión de</mark> <mark class=\"m-personalizado\">infracciones</mark> administrativas.</div></div></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo 210</mark>: <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-1243\">🎯 1 pregunta más de este artículo</mark>"],["Artículo 223 <span class=\"ex-sello\">EX</span>","<p data-ex=\"EX\">El <mark class=\"m-resp\" data-q=\"19-124,19-ia-1304\">que, <mark class=\"m-personalizado\">teniendo a su cargo la <u class=\"m-clave\">custodia</u></mark> <u class=\"m-clave\">de un</u> <mark class=\"m-autoridad\">menor</mark> de edad o una <mark class=\"m-autoridad\">persona</mark> con <mark class=\"m-personalizado\">discapacidad</mark> necesitada de especial <span class=\"m-circulo\">protección,</span> no <mark class=\"m-personalizado\"><u class=\"m-clave\">lo presentare</u> a sus padres o guardadores</mark> sin <mark class=\"m-personalizado\">justificación</mark> <mark class=\"m-destacable\">para ello,</mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">cuando fuere</u> requerido</mark> por ellos</mark>, <mark class=\"m-accion\">será castigado</mark> con la pena <mark class=\"m-personalizado\">de prisión</mark> de <mark class=\"m-destacable\">seis</mark> meses a dos <mark class=\"m-personalizado\">años, sin perjuicio</mark> de que los hechos <mark class=\"m-personalizado\">constituyan otro delito más grave.</mark></p></div></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo</mark> 224: <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-1305,19-ia-1306\">🎯 2 preguntas más de este artículo</mark>"],["Artículo 225 bis","<p><b>1.</b> El progenitor que sin causa justificada para ello sustrajere a su hijo <mark class=\"m-autoridad\">menor</mark> <mark class=\"m-accion\">será castigado</mark> con la pena de prisión de dos a cuatro años e inhabilitación especial para el ejercicio del derecho de patria potestad por tiempo de cuatro a diez años.  <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-1308\">🎯 1 pregunta</mark></p><p><b>1.º</b> El traslado de una <mark class=\"m-autoridad\">persona menor</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">de edad de su lugar de residencia habitual sin consentimiento del otro progenitor o de las <mark class=\"m-autoridad\">personas</mark> o instituciones a las cuales estuviese confiada su guarda o custodia.</span></span>  <mark class=\"m-resp ex-q\" data-q=\"19-10,19-80,19-ia-1309\">🎯 3 preguntas</mark></p><p><b>2.º</b> La <mark class=\"m-resp\" data-q=\"19-125,19-ia-1310\">retención de una <mark class=\"m-autoridad\">persona menor</mark> de edad incumpliendo gravemente el deber establecido por resolución judicial o administrativa</mark>. <mark class=\"m-resp ex-q\" data-q=\"19-249\">🎯 1 pregunta</mark></p><p><b>3.</b> Cuando el <mark class=\"m-autoridad\">menor</mark> sea trasladado <mark class=\"m-resp r-ia\" data-q=\"19-ia-1311\">fuera de España o fuese exigida alguna condición para su restitución</mark> la <span class=\"ex-plg\"><span class=\"ex-plg-t\">pena señalada en el apartado 1 <mark class=\"m-accion\">se impondrá</mark> en su mitad superior.</span></span></p><p><b>4.</b> Cuando el sustractor haya comunicado <span class=\"ex-plg\"><span class=\"ex-plg-t\">el lugar de estancia al otro progenitor o a quien corresponda legalmente</span></span> su cuidado dentro de las <mark class=\"m-resp r-ia\" data-q=\"19-ia-1312\">veinticuatro horas</mark> siguientes a la sustracción con el compromiso de devolución inmediata que efectivamente lleve a cabo, o la ausencia no hubiere sido superior a dicho plazo de veinticuatro horas, <mark class=\"m-accion\">quedará</mark> exento de pena. <mark class=\"m-resp ex-q\" data-q=\"19-95,19-121\">🎯 2 preguntas</mark></p><p>Si la restitución la hiciere, sin <span class=\"ex-plg\"><span class=\"ex-plg-t\">la comunicación a que se refiere el</span></span> párrafo anterior, dentro de los <mark class=\"m-resp\" data-q=\"19-151\">quince días siguientes a la sustracción</mark>, le <mark class=\"m-accion\">será</mark> impuesta la pena de prisión de seis meses a dos años.</p><p>Estos plazos <mark class=\"m-accion\">se computarán</mark> desde la <mark class=\"m-resp r-ia\" data-q=\"19-ia-1313\">fecha de la denuncia de la sustracción</mark>.</p><p><b>5.</b> Las penas señaladas en este <span class=\"ex-plg\"><span class=\"ex-plg-t\">artículo <mark class=\"m-accion\">se impondrán</mark> igualmente a los ascendientes del <mark class=\"m-autoridad\">menor</mark> y a los</span></span> parientes del progenitor hasta el <mark class=\"m-resp r-ia\" data-q=\"19-ia-1314\">segundo grado de consanguinidad o afinidad</mark> que <span class=\"ex-plg\"><span class=\"ex-plg-t\">incurran en las conductas anteriormente descritas.</span></span></p>"],["Artículo 233","<p><b>2.</b> Si el culpable ostentare la guarda del <mark class=\"m-autoridad\">menor</mark> por <mark class=\"m-personalizado\">su condición de funcionario</mark> público, se le <mark class=\"m-accion\">impondrá</mark> además la pena de inhabilitación especial <mark class=\"m-destacable\">para empleo o cargo público</mark> por tiempo de dos a seis años.  <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-1325\">🎯 1 pregunta</mark></p><p><b>3.</b> <mark class=\"m-personalizado\">En todo caso,</mark> <mark class=\"m-autoridad\">el <mark class=\"m-resp\" data-q=\"19-184\">Ministerio Fiscal</mark></mark> <mark class=\"m-accion\">instará</mark> <mark class=\"m-personalizado\">de la</mark> <mark class=\"m-autoridad\">autoridad competente</mark> las medidas pertinentes para la debida <mark class=\"m-personalizado\">custodia y protección</mark> del <mark class=\"m-autoridad\">menor.</mark> <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-1326\">🎯 1 pregunta</mark></p>"],["<mark class=\"m-personalizado\">Artículo 234</mark>","<p><b><mark class=\"m-personalizado\">1.</mark></b> <mark class=\"m-personalizado\">El que, con ánimo de lucro, tomare las cosas muebles ajenas <mark class=\"m-resp r-ia\" data-q=\"19-ia-1327\">sin la voluntad de su dueño</mark></mark> <mark class=\"m-accion\">será castigado,</mark> <mark class=\"m-personalizado\">como reo de hurto, con la pena de prisión de seis a dieciocho meses si la cuantía de lo sustraído excediese de <mark class=\"m-resp\" data-q=\"19-240\">400 euros</mark>.</mark> <mark class=\"m-resp ex-q\" data-q=\"19-252\">🎯 1 pregunta</mark></p></div></div><div class=\"vis\"><div class=\"vis-t\"><i>➜</i>DE LOS HURTOS · arts. 234 a 236 (cuadro del temario)</div><div class=\"vis-flujo\"><div class=\"vis-paso o\"><span class=\"et\">Art. 234 · Hurto</span><u class=\"m-clave\">Ánimo de</u> lucro: tomar <mark class=\"m-personalizado\">cosas</mark> muebles ajenas, <u class=\"m-clave\">sin la voluntad de su dueño</u>. Según la <u class=\"m-clave\">cuantía</u> de lo sustraído: <mark class=\"m-personalizado\">si</mark> excediese de 400 euros → <mark class=\"m-personalizado\">prisión</mark>; <mark class=\"m-personalizado\">si</mark> <u class=\"m-clave\">NO</u> excediese de 400 euros → <mark class=\"m-personalizado\">multa</mark> (<mark class=\"m-personalizado\">salvo que</mark> <mark class=\"m-personalizado\">concurra alguna</mark> de las <mark class=\"m-personalizado\">circunstancias</mark> del art. 235).</div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso c\"><span class=\"et\">Mitad superior</span><mark class=\"m-personalizado\">Cuando</mark> en la <mark class=\"m-autoridad\">comisión</mark> del <u class=\"m-clave\">hecho</u> se hubieran neutralizado, eliminado o inutilizado dispositivos de alarma o <mark class=\"m-personalizado\">seguridad</mark> instalados <mark class=\"m-personalizado\">en las cosas</mark> sustraídas por <mark class=\"m-personalizado\">cualquier</mark> <mark class=\"m-personalizado\">medio</mark>: <u class=\"m-clave\">mitad</u> <u class=\"m-clave\">superior</u> de <mark class=\"m-personalizado\">las penas</mark> <u class=\"m-clave\">anteriores</u>, en sus respectivos <mark class=\"m-personalizado\">casos</mark>.</div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso v\"><span class=\"et\">Art. 235 · Hurtos agravados</span><mark class=\"m-personalizado\">Cuando</mark> se produzca <mark class=\"m-personalizado\">alguna</mark> de las <mark class=\"m-personalizado\">circunstancias</mark> del art. 235.</div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso v\"><span class=\"et\">Art. 236 · Hurto de cosa propia</span><mark class=\"m-personalizado\">Cuando</mark>, siendo dueño de una cosa mueble o actuando con el <mark class=\"m-personalizado\">consentimiento</mark> de éste, la <mark class=\"m-destacable\">sustrajere</mark> de <u class=\"m-clave\">quien</u> la tenga legítimamente <u class=\"m-clave\">en su poder</u>, con <mark class=\"m-personalizado\">perjuicio</mark> del <u class=\"m-clave\">mismo</u> o de un <mark class=\"m-personalizado\">tercero</mark>.</div>"],["Artículo 238","<p><b>1.º</b> <mark class=\"m-resp\" data-q=\"19-248\">Escalamiento</mark>.</p><p><b>2.º</b> Rompimiento de pared, techo o <span class=\"ex-plg\"><span class=\"ex-plg-t\">suelo, o fractura de puerta o ventana.</span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-1329\">🎯 1 pregunta</mark></p><p><b>3.º</b> Fractura de armarios, arcas u <span class=\"ex-plg\"><span class=\"ex-plg-t\">otra clase de muebles u objetos cerrados o sellados, o forzamiento de sus cerraduras o descubrimiento de sus claves para sustraer su contenido, sea en el lugar del robo o fuera del mismo.</span></span>  <mark class=\"m-resp ex-q\" data-q=\"19-244\">🎯 1 pregunta</mark></p></div></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo</mark> 239: <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-1330,19-ia-1331\">🎯 2 preguntas más de este artículo</mark></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo</mark> 241: <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-1332,19-ia-1333\">🎯 2 preguntas más de este artículo</mark></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo</mark> 242: <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-1334\">🎯 1 pregunta más de este artículo</mark>"],["Artículo 248","<p>Cometen <mark class=\"m-resp\" data-q=\"19-226\">estafa</mark> los que, con ánimo <span class=\"ex-plg\"><span class=\"ex-plg-t\">de lucro, utilizaren engaño bastante para producir error en otro, induciéndolo a realizar un</span></span> acto de disposición en perjuicio <mark class=\"m-resp r-ia\" data-q=\"19-ia-1341\">propio o ajeno</mark>.</p></div></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo</mark> 249: <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-1342,19-ia-1343,19-ia-1344\">🎯 3 preguntas más de este artículo</mark>"],["Artículo 286 ter <span class=\"ex-sello\">EX</span>","<p data-ex=\"EX\"><b>1.</b> <mark class=\"m-personalizado\">Los que mediante el ofrecimiento, promesa o concesión</mark> de cualquier <mark class=\"m-personalizado\">beneficio o</mark> ventaja <mark class=\"m-personalizado\">indebidos,</mark> <mark class=\"m-plazo\">pecuniarios o de otra clase, corrompieren o intentaren corromper, por sí o por</mark> <mark class=\"m-autoridad\">persona interpuesta, a una autoridad o funcionario público en beneficio de estos o de un tercero, o atendieran sus solicitudes al respecto, con el fin de que</mark> <mark class=\"m-destacable\">actúen o se abstengan</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">de actuar en relación con el ejercicio de</span></span> funciones públicas para <mark class=\"m-destacable\">conseguir o conservar <u class=\"m-clave\">un contrato, negocio o cualquier otra ventaja competitiva en la realización de <mark class=\"m-resp\" data-q=\"19-288,19-ia-1522\">actividades económicas internacionales</mark>,</u></mark> <mark class=\"m-accion\">serán castigados,</mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">salvo</u></mark> que ya <mark class=\"m-personalizado\">lo estuvieran</mark> con una <mark class=\"m-personalizado\">pena más grave en otro precepto</mark> de este Código, con las penas de <mark class=\"m-personalizado\">prisión</mark> de prisión de tres a seis años, <mark class=\"m-personalizado\">multa</mark> de doce a veinticuatro meses, <mark class=\"m-personalizado\">salvo</mark> que el <mark class=\"m-personalizado\">beneficio</mark> obtenido fuese <mark class=\"m-personalizado\">superior</mark> a la cantidad resultante, en cuyo caso la multa <mark class=\"m-accion\">será</mark> del tanto al triplo del montante de dicho beneficio. <mark class=\"m-resp ex-q\" data-q=\"19-174\">🎯 1 pregunta</mark></p><p><mark class=\"m-personalizado\">Además</mark> de las penas señaladas, <mark class=\"m-accion\">se impondrá</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">en todo caso al responsable la <mark class=\"m-destacable\">pena de prohibición de contratar</mark> <mark class=\"m-personalizado\">con el sector público,</mark> así como la pérdida de la posibilidad de <mark class=\"m-personalizado\">obtener subvenciones o ayudas</mark> públicas y del derecho a gozar de <mark class=\"m-personalizado\">beneficios o incentivos</mark> <mark class=\"m-autoridad\">fiscales</mark> <mark class=\"m-personalizado\">y de la Seguridad Social, y</mark> la prohibición</span></span> de intervenir en <mark class=\"m-personalizado\">transacciones comerciales</mark> de <mark class=\"m-resp r-ia\" data-q=\"19-ia-1523\">trascendencia pública</mark> por un periodo de siete a doce años.</p><p><b>2.</b> A los efectos de este artículo <mark class=\"m-accion\">se entenderá</mark> por funcionario público los determinados por los artículos <mark class=\"m-resp r-ia\" data-q=\"19-ia-1524\">24 y 427</mark>.</p>"],["Artículo 287 <span class=\"ex-sello\">✱</span>","<p><b>1.</b> Para proceder por los delitos <span class=\"ex-plg\"><span class=\"ex-plg-t\">previstos en la Sección 3ª de este <mark class=\"m-autoridad\">Capítulo, excepto</mark> los previstos en los artículos</span></span> 284 y 285, <mark class=\"m-accion\">será</mark> necesaria <mark class=\"m-resp r-ia\" data-q=\"19-ia-1529\">denuncia de la <mark class=\"m-autoridad\">persona</mark> agraviada o de sus representantes legales</mark>. <span class=\"ex-plg\"><span class=\"ex-plg-t\">Cuando aquella sea <mark class=\"m-autoridad\">menor</mark> de edad, <mark class=\"m-autoridad\">persona</mark> con discapacidad necesitada de especial <mark class=\"m-personalizado\">protección o una</mark> <mark class=\"m-autoridad\">persona</mark> <mark class=\"m-personalizado\">desvalida, también</mark> <mark class=\"m-accion\">podrá denunciar</mark> <mark class=\"m-personalizado\">el</mark> <mark class=\"m-autoridad\">Ministerio Fiscal.</mark></span></span></p><p data-ex=\"*\"><b>2.</b> <mark class=\"m-accion\">No será</mark> <mark class=\"m-personalizado\">precisa la denuncia exigida en el apartado anterior cuando la</mark> <mark class=\"m-autoridad\">comisión</mark> <mark class=\"m-personalizado\">del delito afecte a los <u class=\"m-clave\">intereses generales o</u> a una</mark> pluralidad de <mark class=\"m-autoridad\">personas.</mark> <mark class=\"m-resp ex-q\" data-q=\"19-289,19-ia-1530\">🎯 2 preguntas</mark></p></div></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo</mark> 288: <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-1531\">🎯 1 pregunta más de este artículo</mark></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo</mark> 288 bis: <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-1532\">🎯 1 pregunta más de este artículo</mark>"],["Artículo 290 <span class=\"ex-sello\">EX</span>","<p data-ex=\"EX\">Los <mark class=\"m-resp\" data-q=\"19-148\">administradores</mark><span class=\"ex-plg\"><span class=\"ex-plg-t\">, de hecho o de derecho, de una sociedad constituida o en formación, que falsearen las cuentas anuales u otros documentos que deban reflejar la situación jurídica o económica de la entidad, de forma idónea para causar un perjuicio económico a la misma, a alguno de sus socios, o</span></span> a un tercero, <mark class=\"m-accion\">serán castigados</mark> con la pena de prisión de uno a tres años y multa de seis a doce meses. <mark class=\"m-resp ex-q\" data-q=\"19-197\">🎯 1 pregunta</mark></p>"],["Artículo 291 <span class=\"ex-sello ex-sello-r\">R9</span>","<p data-r=\"R9\"><span class=\"ex-sello ex-sello-r\">R9</span> Los que, prevaliéndose de su situación <span class=\"ex-plg\"><span class=\"ex-plg-t\">mayoritaria en la Junta de accionistas o el <mark class=\"m-autoridad\">órgano</mark> de administración de cualquier sociedad constituida o en formación, impusieren acuerdos abusivos, con ánimo</span></span> de lucro propio o ajeno, <mark class=\"m-resp\" data-q=\"19-290,19-ia-1535\">en perjuicio de los demás socios, y sin que reporten beneficios a la misma</mark>, <mark class=\"m-accion\">serán castigados</mark> con la pena de prisión de seis meses a tres años o multa del tanto al triplo del beneficio obtenido.</p>"],["Artículo 297","<p>A los efectos de este capítulo <span class=\"ex-plg\"><span class=\"ex-plg-t\">se entiende por <mark class=\"m-destacable\">sociedad</mark> <mark class=\"m-personalizado\">toda cooperativa, Caja de Ahorros, mutua, entidad financiera o de crédito, <mark class=\"m-resp\" data-q=\"19-140\">fundación</mark>, sociedad mercantil o cualquier otra</mark> entidad de análoga naturaleza que <mark class=\"m-personalizado\">para el cumplimiento de sus fines participe de modo permanente en <mark class=\"m-resp r-ia\" data-q=\"19-ia-1541\">el mercado</mark>.</mark></span></span></p>"],["Artículo 304 <span class=\"ex-sello\">✱</span>","<p data-ex=\"*\"><mark class=\"m-destacable\">La provocación, la</mark> conspiración y la <mark class=\"m-destacable\">proposición</mark> para <span class=\"ex-plg\"><span class=\"ex-plg-t\">cometer los delitos previstos en los artículos 301 a 303 <mark class=\"m-accion\">se castigará,</mark> respectivamente, con la <mark class=\"m-destacable\"><mark class=\"m-resp\" data-q=\"19-291\">pena inferior en uno o dos grados</mark>.</mark></span></span></p>"],["Artículo 305 <span class=\"ex-sello\">✱</span> <span class=\"ex-sello ex-sello-r\">R10</span>","<p data-ex=\"EXAMEN\" data-r=\"R10\"><span class=\"ex-sello ex-sello-r\">R10</span> <b>1.</b> El que, por <mark class=\"m-personalizado\">acción u omisión, defraude a la</mark> <mark class=\"m-autoridad\"><u class=\"m-clave\">Hacienda Pública</u></mark> <mark class=\"m-personalizado\">estatal, autonómica, foral o local, <u class=\"m-clave\">eludiendo</u> el pago de</mark> <mark class=\"m-destacable\">tributos,</mark> cantidades <mark class=\"m-personalizado\">retenidas</mark> <mark class=\"m-destacable\">o</mark> que <mark class=\"m-personalizado\">se hubieran debido retener o ingresos a cuenta,</mark> obteniendo indebidamente <mark class=\"m-personalizado\">devoluciones o disfrutando beneficios</mark> <mark class=\"m-autoridad\">fiscales</mark> de la misma forma, <mark class=\"m-personalizado\">siempre que</mark> la cuantía de la cuota defraudada, el importe no ingresado de las retenciones o ingresos <mark class=\"m-personalizado\">a</mark> cuenta o de las devoluciones o beneficios <mark class=\"m-autoridad\">fiscales</mark> indebidamente obtenidos o disfrutados <mark class=\"m-destacable\"><u class=\"m-clave\">exceda</u> de <u class=\"m-clave\">ciento veinte mil euros</u></mark> <mark class=\"m-accion\">será castigado</mark> con la pena de <mark class=\"m-personalizado\">prisión</mark> de uno a cinco años <mark class=\"m-personalizado\">y multa</mark> del tanto al séxtuplo de la citada cuantía, <mark class=\"m-personalizado\">salvo</mark> que <mark class=\"m-personalizado\">hubiere regularizado su situación</mark> tributaria en los términos del <mark class=\"m-personalizado\">apartado 4</mark> del presente artículo. <mark class=\"m-resp ex-q\" data-q=\"19-169\">🎯 1 pregunta</mark></p><p><mark class=\"m-personalizado\">La mera presentación de declaraciones o autoliquidaciones <mark class=\"m-resp r-ia\" data-q=\"19-ia-1615\">no excluye la defraudación, cuando ésta se acredite por otros hechos</mark>.</mark></p><p style=\"margin-left:18px\" data-ex=\"*\"><b>a)</b> <mark class=\"m-personalizado\">Si se trata de tributos, retenciones, ingresos</mark> a cuenta o devoluciones, periódicos o de <mark class=\"m-personalizado\">declaración periódica,</mark> <mark class=\"m-accion\">se estará</mark> <mark class=\"m-personalizado\">a lo defraudado <u class=\"m-clave\">en</u></mark> <mark class=\"m-destacable\">cada período impositivo o de declaración,</mark> <mark class=\"m-personalizado\">y si</mark> éstos <mark class=\"m-personalizado\"><u class=\"m-clave\">son inferiores</u> a doce meses,</mark> el importe de lo defraudado <mark class=\"m-accion\">se referirá</mark> <mark class=\"m-personalizado\">al <mark class=\"m-resp r-ia\" data-q=\"19-ia-1616\">año natural</mark>. No obstante</mark> lo anterior, en los casos en los que <mark class=\"m-personalizado\">la</mark> defraudación se lleve a cabo en <mark class=\"m-personalizado\">el seno</mark> de una <mark class=\"m-personalizado\"><u class=\"m-clave\">organización o</u> grupo criminal,</mark> o por <mark class=\"m-autoridad\">personas</mark> o entidades <mark class=\"m-personalizado\">que actúen <u class=\"m-clave\">bajo la apariencia</u> de una</mark> <span class=\"m-circulo\"><mark class=\"m-personalizado\">actividad</mark></span> <mark class=\"m-personalizado\"><u class=\"m-clave\">económica real</u></mark> sin desarrollarla de forma efectiva, el <mark class=\"m-personalizado\">delito</mark> <mark class=\"m-accion\">será</mark> <mark class=\"m-personalizado\">perseguible desde el</mark> mismo momento en que se <mark class=\"m-personalizado\"><u class=\"m-clave\">alcance la cantidad</u></mark> fijada <mark class=\"m-personalizado\">en</mark> el apartado 1. <mark class=\"m-resp ex-q\" data-q=\"19-293\">🎯 1 pregunta</mark></p><p><b>3.</b> <mark class=\"m-personalizado\">Las mismas penas</mark> <mark class=\"m-accion\">se impondrán</mark> <mark class=\"m-personalizado\">a</mark> quien cometa las <mark class=\"m-personalizado\">conductas</mark> descritas en el apartado 1 y a quien <mark class=\"m-personalizado\">eluda el pago de cualquier cantidad</mark> que deba <mark class=\"m-personalizado\">ingresar</mark> o <mark class=\"m-personalizado\">disfrute de</mark> manera indebida <u class=\"m-clave\">de</u> <mark class=\"m-personalizado\">un beneficio obtenido legalmente, cuando</mark> los hechos se cometan <mark class=\"m-personalizado\">contra la Hacienda de la <u class=\"m-clave\">Unión Europea,</u> siempre que la cuantía</mark> defraudada <mark class=\"m-destacable\">excediera de cien mil euros</mark> <mark class=\"m-plazo\">en</mark> <mark class=\"m-autoridad\">el plazo de</mark> <mark class=\"m-plazo\"><mark class=\"m-resp r-ia\" data-q=\"19-ia-1618\">un año natural</mark>.</mark> <mark class=\"m-personalizado\">No obstante</mark> lo anterior, en los casos en los que la defraudación se lleve a cabo en el seno de una <mark class=\"m-personalizado\">organización o grupo criminal, o</mark> por <mark class=\"m-autoridad\">personas</mark> o entidades que actúen <mark class=\"m-personalizado\">bajo la apariencia de una actividad económica real</mark> sin desarrollarla de forma efectiva, el delito <mark class=\"m-accion\">será</mark> <mark class=\"m-personalizado\">perseguible desde</mark> el <mark class=\"m-resp r-ia\" data-q=\"19-ia-1617\">mismo momento en que <mark class=\"m-personalizado\">se alcance la cantidad</mark> fijada</mark> en este apartado.</p><p><b>4.</b> <mark class=\"m-accion\">Se considerará</mark> <mark class=\"m-destacable\">regularizada la situación</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">tributaria cuando se haya procedido por el obligado tributario al completo reconocimiento y pago de</span></span> la deuda tributaria, <mark class=\"m-resp\" data-q=\"19-255\">antes de que por la Administración Tributaria se le haya notificado el inicio de actuaciones de comprobación o investigación</mark> <mark class=\"m-autoridad\">tendentes a la determinación de las deudas tributarias objeto de la regularización o, en el caso de que tales actuaciones no se hubieran producido, antes de que el Ministerio Fiscal, el Abogado del Estado o el representante procesal de la Administración autonómica, foral o local de que se trate, interponga querella o denuncia contra aquél dirigida, o antes de que el Ministerio Fiscal o el Juez de Instrucción</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">realicen actuaciones que le permitan tener conocimiento</span></span> formal de la <mark class=\"m-personalizado\">iniciación de diligencias.</mark> <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-1619\">🎯 1 pregunta</mark></p><p><mark class=\"m-personalizado\">La regularización</mark> por el obligado tributario de <span class=\"ex-plg\"><span class=\"ex-plg-t\">su situación tributaria <mark class=\"m-accion\">impedirá</mark> <mark class=\"m-personalizado\">que</mark> se <mark class=\"m-personalizado\">le persiga</mark> por <mark class=\"m-personalizado\">las</mark> posibles <mark class=\"m-personalizado\">irregularidades contables</mark> <mark class=\"m-destacable\">u otras</mark> <mark class=\"m-personalizado\">falsedades instrumentales</mark> que, exclusivamente <mark class=\"m-personalizado\">en relación a la deuda tributaria</mark> objeto de</span></span> regularización, el mismo pudiera haber <mark class=\"m-resp r-ia\" data-q=\"19-ia-1620\">cometido con carácter previo a la regularización</mark> de su situación tributaria.</p><p><b>5.</b> Cuando <mark class=\"m-personalizado\">la</mark> <mark class=\"m-autoridad\"><mark class=\"m-resp\" data-q=\"19-75\">Administración Tributaria</mark></mark> apreciare indicios de haberse cometido un <mark class=\"m-personalizado\">delito</mark> contra la Hacienda <mark class=\"m-autoridad\">Pública,</mark> <mark class=\"m-accion\">podrá liquidar</mark> <mark class=\"m-personalizado\">de forma separada,</mark> por una parte <mark class=\"m-personalizado\">los conceptos y cuantías</mark> que no se encuentren <mark class=\"m-personalizado\">vinculados</mark> con el posible <mark class=\"m-personalizado\">delito</mark> contra la Hacienda Pública, <mark class=\"m-personalizado\">y por otra,</mark> los que se encuentren <mark class=\"m-personalizado\">vinculados</mark> con el posible delito contra la Hacienda Pública. <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-1621\">🎯 1 pregunta</mark></p><p><span class=\"ex-plg\"><span class=\"ex-plg-t\">La liquidación indicada en primer lugar en</span></span> el párrafo anterior <mark class=\"m-accion\">seguirá</mark> la tramitación ordinaria y <mark class=\"m-accion\">se sujetará</mark> al régimen de recursos propios <mark class=\"m-personalizado\">de</mark> toda <mark class=\"m-personalizado\">liquidación tributaria. Y</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">la liquidación que en su caso derive de aquellos conceptos y cuantías que se encuentren vinculados con el posible delito contra</span></span> la Hacienda Pública <mark class=\"m-accion\">seguirá</mark> la tramitación que al <mark class=\"m-personalizado\">efecto</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">establezca la normativa tributaria, sin perjuicio de que finalmente se ajuste a lo que se decida en el proceso penal.</span></span> <mark class=\"m-resp ex-q\" data-q=\"19-138\">🎯 1 pregunta</mark></p><p>La existencia del <mark class=\"m-personalizado\">procedimiento penal</mark> por delito <span class=\"ex-plg\"><span class=\"ex-plg-t\">contra la Hacienda <mark class=\"m-personalizado\">Pública</mark> <mark class=\"m-accion\">no paralizará</mark> <mark class=\"m-personalizado\">la acción de cobro de la deuda tributaria.</mark> Por parte de la Administración <mark class=\"m-personalizado\">Tributaria</mark> <mark class=\"m-accion\">podrán iniciarse</mark> las <mark class=\"m-personalizado\">actuaciones</mark> dirigidas al cobro, <mark class=\"m-personalizado\">salvo</mark> que <mark class=\"m-autoridad\">el Juez,</mark> de oficio <mark class=\"m-personalizado\">o</mark> a instancia de <mark class=\"m-personalizado\">parte, hubiere acordado la <u class=\"m-clave\">suspensión</u></mark> de las actuaciones de ejecución, <mark class=\"m-personalizado\"><u class=\"m-clave\">previa</u> prestación de garantía. Si no se pudiese</mark> prestar <mark class=\"m-personalizado\">garantía</mark> en todo o en parte, <mark class=\"m-personalizado\">excepcionalmente</mark> el <mark class=\"m-autoridad\">Juez</mark> <mark class=\"m-accion\">podrá acordar</mark> <mark class=\"m-personalizado\">la suspensión</mark> con <mark class=\"m-personalizado\"><u class=\"m-clave\">dispensa</u> total o parcial de garantías</mark> si apreciare que la ejecución <mark class=\"m-personalizado\">pudiese ocasionar daños irreparables o de <mark class=\"m-resp r-ia\" data-q=\"19-ia-1623\">muy difícil reparación</mark>.</mark></span></span> <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-1622\">🎯 1 pregunta</mark></p><p><b>6.</b> Los <mark class=\"m-autoridad\">Jueces y Tribunales</mark> <mark class=\"m-accion\">podrán imponer</mark> al obligado tributario o al autor del delito la <mark class=\"m-destacable\">pena inferior en uno o dos grados,</mark> <mark class=\"m-personalizado\">siempre que,</mark> <mark class=\"m-plazo\">antes de</mark> <mark class=\"m-autoridad\">que transcurran</mark> <mark class=\"m-resp\" data-q=\"19-152\">dos meses</mark> desde la citación <mark class=\"m-plazo\">judicial como</mark> <mark class=\"m-autoridad\">imputado</mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">satisfaga</u> la deuda tributaria y reconozca judicialmente los hechos.</mark> Lo <mark class=\"m-plazo\">anterior</mark> <mark class=\"m-accion\">será</mark> <mark class=\"m-personalizado\">igualmente aplicable</mark> respecto de <mark class=\"m-personalizado\">otros partícipes</mark> en <mark class=\"m-personalizado\">el delito distintos</mark> del obligado tributario o <mark class=\"m-personalizado\">del autor del</mark> delito, <mark class=\"m-personalizado\">cuando colaboren activamente</mark> para la <mark class=\"m-personalizado\">obtención de pruebas decisivas</mark> para <mark class=\"m-destacable\">la</mark> identificación o captura de otros responsables, <mark class=\"m-personalizado\">para</mark> el <mark class=\"m-personalizado\">completo</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">esclarecimiento de los hechos delictivos o para la averiguación del patrimonio del obligado tributario o de otros responsables del delito.</span></span> <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-1624\">🎯 1 pregunta</mark></p>"],["Artículo 305 bis <span class=\"ex-sello\">EX</span>","<p style=\"margin-left:18px\" data-ex=\"EX\"><b>c)</b> <mark class=\"m-personalizado\">Que la utilización</mark> de <mark class=\"m-autoridad\">personas</mark> <mark class=\"m-personalizado\">físicas o jurídicas</mark> o entes sin personalidad jurídica <mark class=\"m-personalizado\">interpuestos, negocios o instrumentos</mark> fiduciarios o <mark class=\"m-personalizado\">paraísos</mark> <mark class=\"m-autoridad\">fiscales o territorios</mark> <mark class=\"m-personalizado\">de nula tributación oculte o dificulte</mark> la determinación <mark class=\"m-personalizado\">de la identidad del</mark> obligado <mark class=\"m-personalizado\">tributario o del responsable del</mark> delito, <mark class=\"m-personalizado\">la determinación de la cuantía</mark> defraudada <mark class=\"m-personalizado\">o del patrimonio del obligado</mark> tributario o del responsable del delito. <mark class=\"m-resp ex-q\" data-q=\"19-190,19-ia-1626\">🎯 2 preguntas</mark></p></div></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo</mark> 306: <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-1627\">🎯 1 pregunta más de este artículo</mark>"],["Artículo 307 <span class=\"ex-sello\">✱</span>","<p><b>1.</b> El que, por <mark class=\"m-personalizado\">acción u omisión, defraude a la</mark> <mark class=\"m-autoridad\">Seguridad Social</mark> <mark class=\"m-personalizado\">eludiendo el pago</mark> de las cuotas de ésta y conceptos de recaudación conjunta, <mark class=\"m-personalizado\">obteniendo indebidamente devoluciones de</mark> las mismas <mark class=\"m-personalizado\">o</mark> disfrutando de <mark class=\"m-personalizado\">deducciones</mark> por cualquier concepto asimismo de forma indebida, <mark class=\"m-personalizado\">siempre que</mark> la cuantía de las cuotas defraudadas o de las devoluciones o deducciones indebidas <mark class=\"m-destacable\">exceda de <mark class=\"m-resp r-ia\" data-q=\"19-ia-1628\">cincuenta mil euros</mark></mark> <mark class=\"m-accion\">será castigado</mark> con la pena de <mark class=\"m-personalizado\">prisión</mark> de uno a cinco años y <mark class=\"m-personalizado\">multa</mark> del tanto al séxtuplo de la citada cuantía <mark class=\"m-personalizado\">salvo</mark> que hubiere <mark class=\"m-personalizado\">regularizado</mark> su situación ante la Seguridad Social en los términos del <mark class=\"m-personalizado\">apartado 3</mark> del presente artículo. <mark class=\"m-resp ex-q\" data-q=\"19-117,19-119,19-162\">🎯 3 preguntas</mark></p><p data-ex=\"*\"><b>2.</b> A los efectos de <mark class=\"m-personalizado\">determinar la cuantía</mark> mencionada en el apartado anterior <mark class=\"m-accion\">se estará</mark> <mark class=\"m-personalizado\">al importe total defraudado</mark> <mark class=\"m-plazo\">durante <mark class=\"m-resp\" data-q=\"19-294,19-ia-1629\">cuatro años naturales</mark>.</mark></p><p><b>5.</b> Los <mark class=\"m-autoridad\">Jueces y Tribunales</mark> <mark class=\"m-accion\">podrán imponer</mark> al obligado frente a la Seguridad Social o al autor del <mark class=\"m-destacable\">delito la pena inferior en uno o dos grados,</mark> <mark class=\"m-personalizado\">siempre</mark> que, <mark class=\"m-autoridad\">antes de que transcurran dos</mark> meses desde <mark class=\"m-personalizado\">la</mark> citación judicial como imputado, satisfaga la <mark class=\"m-personalizado\">deuda</mark> con la Seguridad <mark class=\"m-personalizado\">Social y reconozca judicialmente los hechos. Lo anterior</mark> <mark class=\"m-accion\">será</mark> <mark class=\"m-personalizado\">igualmente aplicable</mark> respecto de otros partícipes en el delito distintos del deudor a la Seguridad Social o del autor del delito, <mark class=\"m-personalizado\">cuando <u class=\"m-clave\">colaboren</u> activamente para la obtención de pruebas <u class=\"m-clave\">decisivas</u></mark> para la <mark class=\"m-personalizado\">identificación</mark> o captura de otros responsables, para el <mark class=\"m-personalizado\">completo esclarecimiento de los</mark> hechos delictivos <mark class=\"m-personalizado\">o</mark> para <mark class=\"m-personalizado\">la averiguación del patrimonio</mark> del <mark class=\"m-personalizado\">obligado</mark> frente a la Seguridad Social o de otros responsables del <mark class=\"m-personalizado\">delito.</mark>  <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-1630\">🎯 1 pregunta</mark></p></div></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo</mark> 307 ter: <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-1632,19-ia-1633,19-ia-1634\">🎯 3 preguntas más de este artículo</mark>"],["Artículo 308 <span class=\"ex-sello\">EX</span> <span class=\"ex-sello\">✱</span>","<p data-ex=\"EX\"><b>1.</b> El que obtenga <mark class=\"m-destacable\"><u class=\"m-clave\">subvenciones o ayudas</u></mark> de las <mark class=\"m-autoridad\">Administraciones Públicas,</mark> <mark class=\"m-personalizado\">incluida la</mark> <mark class=\"m-autoridad\">Unión Europea,</mark> en una cantidad o por un valor <mark class=\"m-destacable\"><u class=\"m-clave\">superior</u> a cien</mark> mil euros falseando las condiciones requeridas para su <mark class=\"m-personalizado\">concesión <u class=\"m-clave\">u</u> ocultando</mark> las que la hubiesen <mark class=\"m-personalizado\">impedido</mark> <mark class=\"m-accion\">será castigado</mark> con la pena de <mark class=\"m-personalizado\">prisión</mark> de uno a cinco años <mark class=\"m-destacable\"><u class=\"m-clave\">y</u></mark> <mark class=\"m-personalizado\">multa</mark> del tanto al séxtuplo de su importe, <mark class=\"m-personalizado\">salvo</mark> que lleve a cabo el <mark class=\"m-personalizado\">reintegro a</mark> que se refiere el <mark class=\"m-personalizado\">apartado 6.</mark> <mark class=\"m-resp ex-q\" data-q=\"19-295,19-ia-1635\">🎯 2 preguntas</mark></p><p><b>2.</b> Las mismas penas <mark class=\"m-accion\">se impondrán</mark> al que, en el desarrollo de una <mark class=\"m-destacable\"><u class=\"m-clave\">actividad sufragada</u> total o parcialmente con fondos</mark> <mark class=\"m-autoridad\">de las Administraciones públicas,</mark> <mark class=\"m-personalizado\">incluida la</mark> <mark class=\"m-autoridad\">Unión Europea,</mark> los aplique en una cantidad <mark class=\"m-destacable\">superior a cien mil euros a</mark> <mark class=\"m-personalizado\">fines distintos</mark> de aquéllos para los que la subvención o ayuda fue concedida, <mark class=\"m-personalizado\"><u class=\"m-clave\">salvo</u></mark> que lleve a cabo el <mark class=\"m-personalizado\">reintegro</mark> a que se refiere el apartado 6. <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-1636\">🎯 1 pregunta</mark></p><p><b>5.</b> A los efectos de <mark class=\"m-destacable\">determinar la cuantía</mark> a que se refiere este artículo, <mark class=\"m-accion\">se atenderá</mark> <mark class=\"m-personalizado\">al total</mark> de lo obtenido, defraudado o indebidamente aplicado, <mark class=\"m-personalizado\">con independencia de si procede de una o de varias Administraciones</mark> Públicas conjuntamente.  <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-1637\">🎯 1 pregunta</mark></p><p data-ex=\"*\"><b>6.</b> <mark class=\"m-accion\">Se entenderá</mark> <mark class=\"m-personalizado\">realizado el reintegro</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">al que se refieren los apartados 1, 2 y 4 cuando por el perceptor de la</span></span> subvención o ayuda <mark class=\"m-personalizado\">se proceda a devolver</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">las subvenciones o ayudas indebidamente</span></span> percibidas o aplicadas, <mark class=\"m-personalizado\">incrementadas en el</mark> <mark class=\"m-destacable\">interés</mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">de</u></mark> <mark class=\"m-destacable\">demora</mark> <mark class=\"m-personalizado\">aplicable en materia de subvenciones</mark> desde el momento en que las percibió, y se lleve a cabo <mark class=\"m-personalizado\">antes de que se haya notificado</mark> la <mark class=\"m-personalizado\">iniciación</mark> de actuaciones de <mark class=\"m-personalizado\">comprobación o control</mark> en relación con dichas subvenciones o ayudas <mark class=\"m-personalizado\">o,</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">en el caso de que tales actuaciones no</span></span> se hubieran producido, <mark class=\"m-personalizado\">antes de que</mark> <mark class=\"m-autoridad\">el Ministerio Fiscal, el Abogado del Estado o</mark> el representante de la Administración <mark class=\"m-autoridad\">autonómica o local</mark> de que se trate, <mark class=\"m-personalizado\">interponga querella o denuncia</mark> contra aquél dirigida o <mark class=\"m-personalizado\">antes de que</mark> <mark class=\"m-autoridad\">el Ministerio Fiscal o el juez de instrucción</mark> realicen actuaciones que le permitan tener <mark class=\"m-personalizado\">conocimiento</mark> formal de la <mark class=\"m-personalizado\">iniciación de diligencias. El reintegro</mark> <mark class=\"m-accion\">impedirá</mark> que a dicho sujeto se le <mark class=\"m-personalizado\">persiga</mark> por las <mark class=\"m-personalizado\">posibles falsedades instrumentales</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">que, exclusivamente en relación a la deuda objeto de</span></span> regularización, el mismo <mark class=\"m-personalizado\">pudiera haber</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">cometido con carácter previo a la regularización de su situación.</span></span> <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-1638\">🎯 1 pregunta</mark></p><p><b>8.</b> Los <mark class=\"m-autoridad\">jueces y tribunales</mark> <mark class=\"m-accion\">podrán imponer</mark> al responsable de este delito la <mark class=\"m-destacable\">pena inferior en uno o dos</mark> <mark class=\"m-plazo\">grados, siempre que, antes de que transcurran dos meses desde la citación judicial como investigado, lleve a cabo el reintegro a que se refiere el apartado 6 y reconozca judicialmente los hechos. Lo anterior</mark> <mark class=\"m-accion\">será</mark> <mark class=\"m-plazo\">igualmente aplicable respecto de otros partícipes en el delito distintos del obligado</mark> al reintegro o del autor del delito, cuando colaboren activamente para la obtención de pruebas <mark class=\"m-personalizado\"><u class=\"m-clave\">decisivas</u></mark> para la identificación o captura de otros responsables, para el completo esclarecimiento de los hechos delictivos <mark class=\"m-personalizado\">o para</mark> la averiguación del patrimonio del obligado o del responsable del delito.  <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-1639\">🎯 1 pregunta</mark></p></div></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo</mark> 308 bis: <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-1640\">🎯 1 pregunta más de este artículo</mark>"],["Artículo 310 <span class=\"ex-sello\">✱</span>","<p data-ex=\"*\"><mark class=\"m-accion\">Será castigado</mark> con la pena de <mark class=\"m-personalizado\">prisión</mark> de cinco a siete meses el que <mark class=\"m-personalizado\">estando <u class=\"m-clave\">obligado</u> por ley tributaria a <u class=\"m-clave\">llevar</u></mark> <mark class=\"m-destacable\"><u class=\"m-clave\">contabilidad</u></mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">mercantil,</u> libros <u class=\"m-clave\">o registros</u></mark> <mark class=\"m-autoridad\"><u class=\"m-clave\">fiscales:</u></mark>  <mark class=\"m-resp ex-q\" data-q=\"19-343\">🎯 1 pregunta</mark></p><p style=\"margin-left:18px\"><b>a)</b> <mark class=\"m-personalizado\"><u class=\"m-clave\">Incumpla absolutamente</u> dicha obligación</mark> <mark class=\"m-resp\" data-q=\"19-296,19-ia-1641\">en régimen de estimación directa de bases tributarias</mark>.</p><p style=\"margin-left:18px\"><b>b)</b> <mark class=\"m-personalizado\">Lleve <u class=\"m-clave\">contabilidades distintas</u></mark> que, referidas a una <span class=\"ex-plg\"><span class=\"ex-plg-t\">misma actividad y ejercicio económico, <mark class=\"m-personalizado\">oculten o</mark> <span class=\"m-circulo\"><mark class=\"m-personalizado\">simulen</mark></span> <mark class=\"m-personalizado\">la verdadera situación</mark> de la empresa.</span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-1642\">🎯 1 pregunta</mark></p><p style=\"margin-left:18px\"><b>c)</b> <mark class=\"m-personalizado\">No hubiere</mark> <span class=\"m-circulo\"><mark class=\"m-personalizado\">anotado</mark></span> en los libros <span class=\"ex-plg\"><span class=\"ex-plg-t\">obligatorios <mark class=\"m-personalizado\">negocios, actos,</mark> operaciones o, en general, transacciones económicas, <mark class=\"m-personalizado\">o</mark> los hubiese <mark class=\"m-personalizado\">anotado con <u class=\"m-clave\">cifras distintas</u> a</mark> las verdaderas.</span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-1643\">🎯 1 pregunta</mark></p><p style=\"margin-left:18px\"><b>d)</b> Hubiere practicado en los libros obligatorios <mark class=\"m-personalizado\"><u class=\"m-clave\">anotaciones</u> contables <mark class=\"m-resp r-ia\" data-q=\"19-ia-1644\">ficticias</mark>.</mark></p><p>La consideración como delito de los supuestos de hecho, a que se refieren los <mark class=\"m-personalizado\">párrafos <u class=\"m-clave\">c) y d)</u></mark> anteriores, <mark class=\"m-accion\">requerirá</mark> que se hayan <mark class=\"m-personalizado\"><u class=\"m-clave\">omitido</u> las declaraciones</mark> tributarias <mark class=\"m-personalizado\">o</mark> que las presentadas fueren <mark class=\"m-personalizado\">reflejo de su <u class=\"m-clave\">falsa contabilidad y</u> que la <u class=\"m-clave\">cuantía,</u> en más o menos, de los cargos o abonos omitidos o falseados</mark> <span class=\"m-circulo\"><mark class=\"m-personalizado\">exceda,</mark></span> <mark class=\"m-personalizado\">sin compensación aritmética entre ellos,</mark> de <mark class=\"m-destacable\">240.000 euros</mark> por <mark class=\"m-personalizado\">cada <mark class=\"m-resp r-ia\" data-q=\"19-ia-1645\">ejercicio económico</mark>.</mark></p></div></div><div class=\"vis\"><div class=\"vis-t\"><i>▦</i>DELITOS CONTRA LA HACIENDA PÚBLICA Y LA SEGURIDAD SOCIAL · arts. 305 a 310 bis (tu esquema manuscrito, ampliado)</div><div class=\"vis-tabla\"><div class=\"vt-cab\"><span>Delito · bien jurídico</span><span>Cuantía, regla y consecuencias</span></div><div class=\"vt-nodo\"><div class=\"vt-et o\">HACIENDA PÚBLICA · art. 305 (estatal, autonómica, foral o local)</div><div class=\"vt-hijos\"><div class=\"vt-hoja\"><span class=\"vt-p o\">Conducta</span><div class=\"vt-t\">Defraudar por acción u omisión: eludir tributos, retenciones o ingresos a cuenta, obtener devoluciones o disfrutar beneficios fiscales indebidos.</div></div><div class=\"vt-hoja\"><span class=\"vt-p o\">Cuantía</span><div class=\"vt-t\">Cuota defraudada <mark class=\"m-plazo\">más de 120.000 €</mark>. <u class=\"m-clave\">La mera presentación</u> de declaraciones o autoliquidaciones <u class=\"m-clave\">no excluye</u> la defraudación.</div></div><div class=\"vt-hoja\"><span class=\"vt-p v\">Cómputo</span><div class=\"vt-t\">Tributos periódicos: lo defraudado en <mark class=\"m-plazo\">cada período impositivo o declaración</mark> (si es inferior a 12 meses, <mark class=\"m-plazo\">año natural</mark>). Resto: cada concepto liquidable. Si hay organización o grupo criminal o sociedades pantalla, es perseguible desde que se alcance la cuantía.</div></div><div class=\"vt-hoja\"><span class=\"vt-p c\">Regularización</span><div class=\"vt-t\">Se regulariza si se reconoce y paga la deuda antes de que se notifique el inicio de actuaciones de comprobación o, sin ellas, antes de querella, denuncia o diligencias → <u class=\"m-clave\">no se castiga</u>. También si se paga una vez prescrito el derecho de la Administración.</div></div><div class=\"vt-hoja\"><span class=\"vt-p v\">Accesoria</span><div class=\"vt-t\">Pérdida de subvenciones, ayudas y beneficios fiscales o de la Seguridad Social: <mark class=\"m-plazo\">3 a 6 años</mark>.</div></div><div class=\"vt-hoja\"><span class=\"vt-p c\">Procedimiento</span><div class=\"vt-t\">La Administración puede liquidar de forma separada lo vinculado al delito. El proceso penal <u class=\"m-clave\">no paraliza</u> el cobro, salvo suspensión judicial con garantía (o dispensa excepcional).</div></div></div></div><div class=\"vt-nodo\"><div class=\"vt-et c\">HACIENDA PÚBLICA · AGRAVADO · art. 305 bis</div><div class=\"vt-hijos\"><div class=\"vt-hoja\"><span class=\"vt-p o\">Cuantía</span><div class=\"vt-t\">Cuota defraudada <mark class=\"m-plazo\">más de 600.000 €</mark>.</div></div><div class=\"vt-hoja\"><span class=\"vt-p v\">Organización</span><div class=\"vt-t\">Defraudación en el seno de una organización o grupo criminal.</div></div><div class=\"vt-hoja\"><span class=\"vt-p v\">Ocultación</span><div class=\"vt-t\">Uso de personas o entes interpuestos, negocios fiduciarios, paraísos fiscales que oculte o dificulte la identidad del obligado o la cuantía.</div></div><div class=\"vt-hoja\"><span class=\"vt-p c\">Accesoria</span><div class=\"vt-t\">Pérdida de subvenciones y beneficios: <mark class=\"m-plazo\">4 a 8 años</mark>.</div></div></div></div><div class=\"vt-nodo\"><div class=\"vt-et v\">HACIENDA DE LA UNIÓN EUROPEA · art. 305.3</div><div class=\"vt-hijos\"><div class=\"vt-hoja\"><span class=\"vt-p o\">Cuantía</span><div class=\"vt-t\">Más de <mark class=\"m-plazo\">100.000 €</mark> en el plazo de <mark class=\"m-plazo\">un año natural</mark>.</div></div><div class=\"vt-hoja\"><span class=\"vt-p c\">Atenuado</span><div class=\"vt-t\">No supera 100.000 € pero excede de <mark class=\"m-plazo\">10.000 €</mark> → prisión de <mark class=\"m-plazo\">3 meses a 1 año</mark> o multa del tanto al triplo, y pérdida de subvenciones <mark class=\"m-plazo\">6 meses a 2 años</mark>.</div></div></div></div><div class=\"vt-nodo\"><div class=\"vt-et o\">PRESUPUESTOS GENERALES DE LA UE · art. 306</div><div class=\"vt-hijos\"><div class=\"vt-hoja\"><span class=\"vt-p o\">Conducta</span><div class=\"vt-t\">Defraudar a los presupuestos de la UE u otros administrados por ésta: eludir pagos, dar a los fondos aplicación distinta u obtenerlos falseando condiciones.</div></div><div class=\"vt-hoja\"><span class=\"vt-p o\">Cuantía</span><div class=\"vt-t\">Más de <mark class=\"m-plazo\">50.000 €</mark>.</div></div><div class=\"vt-hoja\"><span class=\"vt-p c\">Atenuado</span><div class=\"vt-t\">No supera 50.000 € pero excede de <mark class=\"m-plazo\">4.000 €</mark> → prisión de <mark class=\"m-plazo\">3 meses a 1 año</mark> o multa del tanto al triplo, y pérdida de subvenciones <mark class=\"m-plazo\">6 meses a 2 años</mark>.</div></div><div class=\"vt-hoja\"><span class=\"vt-p v\">Accesoria</span><div class=\"vt-t\">Pérdida de subvenciones y beneficios: <mark class=\"m-plazo\">3 a 6 años</mark>.</div></div></div></div><div class=\"vt-nodo\"><div class=\"vt-et v\">SEGURIDAD SOCIAL · art. 307 (cuotas y conceptos de recaudación conjunta)</div><div class=\"vt-hijos\"><div class=\"vt-hoja\"><span class=\"vt-p o\">Conducta</span><div class=\"vt-t\">Defraudar a la Seguridad Social: eludir cuotas, obtener devoluciones o disfrutar deducciones indebidas.</div></div><div class=\"vt-hoja\"><span class=\"vt-p o\">Cuantía</span><div class=\"vt-t\">Más de <mark class=\"m-plazo\">50.000 €</mark>, computado sobre <mark class=\"m-plazo\">cuatro años naturales</mark>. <u class=\"m-clave\">La mera presentación</u> de documentos de cotización <u class=\"m-clave\">no excluye</u> la defraudación.</div></div><div class=\"vt-hoja\"><span class=\"vt-p c\">Regularización</span><div class=\"vt-t\">Se regulariza si se reconoce y paga la deuda antes de que se notifiquen actuaciones inspectoras o, sin ellas, antes de querella o denuncia del Ministerio Fiscal o del Letrado de la Seguridad Social, o de diligencias.</div></div><div class=\"vt-hoja\"><span class=\"vt-p v\">Pena inferior</span><div class=\"vt-t\">Inferior en uno o dos grados si, antes de <mark class=\"m-plazo\">2 meses</mark> desde la citación como imputado, satisface la deuda y reconoce los hechos; también a otros partícipes que colaboren activamente.</div></div><div class=\"vt-hoja\"><span class=\"vt-p c\">Procedimiento</span><div class=\"vt-t\">El proceso penal <u class=\"m-clave\">no paraliza</u> la liquidación y cobro, salvo que el Juez lo acuerde con garantía. Multa y responsabilidad civil: apremio por la Administración de la Seguridad Social.</div></div></div></div><div class=\"vt-nodo\"><div class=\"vt-et c\">SEGURIDAD SOCIAL · AGRAVADO · art. 307 bis</div><div class=\"vt-hijos\"><div class=\"vt-hoja\"><span class=\"vt-p o\">Cuantía</span><div class=\"vt-t\">Más de <mark class=\"m-plazo\">120.000 €</mark>.</div></div><div class=\"vt-hoja\"><span class=\"vt-p v\">Organización</span><div class=\"vt-t\">Organización o grupo criminal u ocultación mediante interpuestos, fiduciarios, paraísos fiscales.</div></div><div class=\"vt-hoja\"><span class=\"vt-p c\">Accesoria</span><div class=\"vt-t\">Pérdida de subvenciones y beneficios: <mark class=\"m-plazo\">4 a 8 años</mark>. Le son aplicables todas las previsiones del art. 307.</div></div></div></div><div class=\"vt-nodo\"><div class=\"vt-et v\">FRAUDE EN PRESTACIONES DE LA SEGURIDAD SOCIAL · art. 307 ter</div><div class=\"vt-hijos\"><div class=\"vt-hoja\"><span class=\"vt-p o\">Conducta</span><div class=\"vt-t\">Obtener, prolongar o facilitar a otros prestaciones por error provocado mediante simulación, tergiversación u ocultación consciente de hechos, con perjuicio a la Administración Pública.</div></div><div class=\"vt-hoja\"><span class=\"vt-p o\">Pena</span><div class=\"vt-t\">Prisión de <mark class=\"m-plazo\">6 meses a 3 años</mark>; si no hay especial gravedad, multa del tanto al séxtuplo.</div></div><div class=\"vt-hoja\"><span class=\"vt-p v\">Agravado</span><div class=\"vt-t\">Prestaciones de <mark class=\"m-plazo\">más de 50.000 €</mark> o circunstancias b) o c) del art. 307 bis.1 → prisión de <mark class=\"m-plazo\">2 a 6 años</mark> y multa del tanto al séxtuplo.</div></div><div class=\"vt-hoja\"><span class=\"vt-p c\">Exención</span><div class=\"vt-t\"><u class=\"m-clave\">Exento de responsabilidad</u> quien reintegre el valor de la prestación con interés, antes de que se le notifique la iniciación de actuaciones o de querella, denuncia o diligencias. El proceso penal <u class=\"m-clave\">no impide</u> el reintegro administrativo.</div></div></div></div><div class=\"vt-nodo\"><div class=\"vt-et o\">SUBVENCIONES Y AYUDAS PÚBLICAS · art. 308</div><div class=\"vt-hijos\"><div class=\"vt-hoja\"><span class=\"vt-p o\">Conducta</span><div class=\"vt-t\">Obtener subvenciones o ayudas de las Administraciones Públicas (incluida la UE) falseando las condiciones u ocultando las que lo hubieran impedido, o aplicarlas a fines distintos.</div></div><div class=\"vt-hoja\"><span class=\"vt-p o\">Cuantía</span><div class=\"vt-t\">Más de <mark class=\"m-plazo\">100.000 €</mark> → prisión de <mark class=\"m-plazo\">1 a 5 años</mark> y multa del tanto al séxtuplo, <u class=\"m-clave\">salvo</u> reintegro.</div></div><div class=\"vt-hoja\"><span class=\"vt-p c\">Atenuado</span><div class=\"vt-t\">No supera 100.000 € pero excede de <mark class=\"m-plazo\">10.000 €</mark> → prisión de <mark class=\"m-plazo\">3 meses a 1 año</mark> o multa del tanto al triplo, <u class=\"m-clave\">salvo</u> reintegro.</div></div><div class=\"vt-hoja\"><span class=\"vt-p v\">Accesoria</span><div class=\"vt-t\">Pérdida de subvenciones y beneficios: <mark class=\"m-plazo\">3 a 6 años</mark> (<mark class=\"m-plazo\">6 meses a 2 años</mark> en el atenuado).</div></div><div class=\"vt-hoja\"><span class=\"vt-p c\">Reintegro</span><div class=\"vt-t\">Devolver lo percibido con interés de demora <mark class=\"m-plazo\">antes</mark> de que se notifiquen actuaciones de comprobación o control, o de querella, denuncia o diligencias. Evita perseguir las falsedades instrumentales.</div></div><div class=\"vt-hoja\"><span class=\"vt-p v\">Pena inferior</span><div class=\"vt-t\">Uno o dos grados si, antes de <mark class=\"m-plazo\">2 meses</mark> desde la citación como investigado, reintegra y reconoce los hechos; también a partícipes que colaboren.</div></div></div></div><div class=\"vt-nodo\"><div class=\"vt-et c\">SUSPENSIÓN DE LA PENA · art. 308 bis (todo el Título)</div><div class=\"vt-hijos\"><div class=\"vt-hoja\"><span class=\"vt-p o\">Requisito</span><div class=\"vt-t\">Además del art. 80: haber abonado la deuda o reintegrado la subvención. Se entiende cumplido si asume el compromiso de pagar según su capacidad económica y facilitar el decomiso, y es razonable esperar que lo cumplirá.</div></div><div class=\"vt-hoja\"><span class=\"vt-p c\">No se concede</span><div class=\"vt-t\">Si ha facilitado información inexacta o insuficiente sobre su patrimonio. Se revoca si incumple el compromiso o la oculta.</div></div></div></div><div class=\"vt-nodo\"><div class=\"vt-et v\">ART. 309 · derogado</div><div class=\"vt-hijos\"><div class=\"vt-hoja sp\"><div class=\"vt-t\"><u class=\"m-clave\">Derogado</u>: no hay contenido que estudiar.</div></div></div></div><div class=\"vt-nodo\"><div class=\"vt-et o\">DELITO CONTABLE · art. 310 (obligado por ley tributaria a llevar contabilidad)</div><div class=\"vt-hijos\"><div class=\"vt-hoja\"><span class=\"vt-p o\">Pena</span><div class=\"vt-t\">Prisión de <mark class=\"m-plazo\">5 a 7 meses</mark>.</div></div><div class=\"vt-hoja\"><span class=\"vt-p o\">a)</span><div class=\"vt-t\">Incumplir absolutamente la obligación en régimen de estimación directa.</div></div><div class=\"vt-hoja\"><span class=\"vt-p v\">b)</span><div class=\"vt-t\">Llevar contabilidades distintas que oculten o simulen la verdadera situación de la empresa.</div></div><div class=\"vt-hoja\"><span class=\"vt-p c\">c) y d)</span><div class=\"vt-t\">No anotar o anotar con cifras distintas operaciones; o practicar anotaciones ficticias. Solo son delito si se omitieron las declaraciones (o reflejan la falsa contabilidad) y la cuantía excede de <mark class=\"m-plazo\">240.000 € por ejercicio</mark>, <u class=\"m-clave\">sin compensación aritmética</u>.</div></div></div></div><div class=\"vt-nodo\"><div class=\"vt-et v\">PERSONAS JURÍDICAS · art. 310 bis</div><div class=\"vt-hijos\"><div class=\"vt-hoja\"><span class=\"vt-p o\">Multa</span><div class=\"vt-t\">Del <mark class=\"m-plazo\">tanto al doble</mark> de lo defraudado (física con prisión de más de 2 años) · del <mark class=\"m-plazo\">doble al cuádruple</mark> (más de 5 años) · de <mark class=\"m-plazo\">6 meses a 1 año</mark> (art. 310).</div></div><div class=\"vt-hoja\"><span class=\"vt-p c\">Además</span><div class=\"vt-t\">Pérdida de subvenciones y beneficios <mark class=\"m-plazo\">3 a 6 años</mark>; podrá imponerse la prohibición de contratar con las Administraciones Públicas y las penas del art. 33.7 b), c), d), e) y g) (art. 66 bis).</div></div></div></div>"],["Artículo 311 <span class=\"ex-sello\">EX</span> <span class=\"ex-sello ex-sello-r\">R11</span>","<p><b>1.º</b> Los que, <mark class=\"m-personalizado\">mediante <u class=\"m-clave\">engaño o abuso</u> de situación</mark> de <mark class=\"m-personalizado\"><u class=\"m-clave\">necesidad, impongan</u></mark> a los trabajadores a su servicio <mark class=\"m-personalizado\">condiciones laborales</mark> <span class=\"m-circulo\"><mark class=\"m-personalizado\">o</mark></span> <mark class=\"m-personalizado\">de Seguridad Social</mark> que <span class=\"m-circulo\"><mark class=\"m-personalizado\">perjudiquen,</mark></span> <mark class=\"m-personalizado\">supriman o restrinjan los derechos</mark> que tengan reconocidos por disposiciones <mark class=\"m-personalizado\">legales, convenios</mark> colectivos o <mark class=\"m-personalizado\">contrato</mark> individual. <mark class=\"m-resp ex-q\" data-q=\"19-154,19-ia-1701\">🎯 2 preguntas</mark></p><p data-ex=\"EX\"><b>2.º</b> Los que impongan condiciones ilegales a sus trabajadores <mark class=\"m-resp\" data-q=\"19-297\">mediante su contratación bajo fórmulas ajenas al contrato de trabajo, o las mantengan en contra de requerimiento o sanción administrativa</mark>.</p><p><b><mark class=\"m-destacable\">4.º</mark></b> Los que en el <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-personalizado\">supuesto de transmisión de empresas, con conocimiento</mark> de los procedimientos descritos en los apartados anteriores, <mark class=\"m-personalizado\">mantengan las referidas condiciones</mark> impuestas por otro.</span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-1705\">🎯 1 pregunta</mark></p></div></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo</mark> 311 bis: <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-1706,19-ia-1707\">🎯 2 preguntas más de este artículo</mark></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo</mark> 312: <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-1708,19-ia-1709\">🎯 2 preguntas más de este artículo</mark></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo</mark> 313: <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-1710\">🎯 1 pregunta más de este artículo</mark></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo</mark> 315: <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-1712,19-ia-1713\">🎯 2 preguntas más de este artículo</mark></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo</mark> 316: <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-1714\">🎯 1 pregunta más de este artículo</mark></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo</mark> 317: <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-1715\">🎯 1 pregunta más de este artículo</mark></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo</mark> 318: <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-1716\">🎯 1 pregunta más de este artículo</mark>"],["Artículo 327 <span class=\"ex-sello\">EX</span> <span class=\"ex-sello\">✱</span>","<p style=\"margin-left:18px\"><b>a)</b> Que la <mark class=\"m-personalizado\">industria o actividad funcione clandestinamente,</mark> sin <span class=\"ex-plg\"><span class=\"ex-plg-t\">haber obtenido la preceptiva autorización o aprobación administrativa de sus instalaciones.</span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-1740\">🎯 1 pregunta</mark></p><p style=\"margin-left:18px\" data-ex=\"EX\"><b>b)</b> Que <mark class=\"m-resp\" data-q=\"19-300,19-ia-1741\">se hayan <mark class=\"m-personalizado\"><u class=\"m-clave\">desobedecido</u></mark> las órdenes expresas de la <mark class=\"m-autoridad\">autoridad</mark> <mark class=\"m-personalizado\">administrativa</mark> de <mark class=\"m-personalizado\">corrección o suspensión de las actividades</mark> tipificadas</mark> en el <mark class=\"m-personalizado\">artículo anterior.</mark></p><p style=\"margin-left:18px\"><b>e)</b> Que se haya producido un <mark class=\"m-personalizado\">riesgo de <u class=\"m-clave\">deterioro</u> <mark class=\"m-resp r-ia\" data-q=\"19-ia-1742\">irreversible o catastrófico</mark>.</mark></p><p style=\"margin-left:18px\" data-ex=\"*\"><b>f)</b> Que se produzca una <mark class=\"m-personalizado\"><u class=\"m-clave\">extracción</u> ilegal de</mark> <span class=\"m-circulo\"><mark class=\"m-personalizado\">aguas</mark></span> <mark class=\"m-personalizado\">en período de <mark class=\"m-resp r-ia\" data-q=\"19-ia-1743\">restricciones</mark>.</mark> <mark class=\"m-resp ex-q\" data-q=\"19-301\">🎯 1 pregunta</mark></p>"],["Artículo 329","<p><b>1.</b> La <mark class=\"m-autoridad\">autoridad</mark> o funcionario público <span class=\"ex-plg\"><span class=\"ex-plg-t\">que, a sabiendas, hubiere informado favorablemente</span></span> la concesión de licencias manifiestamente <mark class=\"m-resp\" data-q=\"19-44\">ilegales</mark> que <span class=\"ex-plg\"><span class=\"ex-plg-t\">autoricen el funcionamiento de las industrias o actividades contaminantes a que se refieren los artículos anteriores, o que con motivo de sus inspecciones hubiere silenciado la infracción de leyes o disposiciones normativas de carácter general que las regulen, o que hubiere omitido</span></span> la realización de inspecciones de <mark class=\"m-resp r-ia\" data-q=\"19-ia-1744\">carácter obligatorio</mark>, <mark class=\"m-accion\">será castigado</mark> con la pena establecida en el artículo 404 de este Código y, además, con la de prisión de seis meses a tres años y la de multa de ocho a veinticuatro meses.</p></div></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo</mark> 330: <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-1745\">🎯 1 pregunta más de este artículo</mark></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo</mark> 331: <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-1746\">🎯 1 pregunta más de este artículo</mark>"],["Artículo 336","<p>El <mark class=\"m-resp\" data-q=\"19-214,19-ia-1753\">que, <mark class=\"m-personalizado\">sin</mark> <mark class=\"m-destacable\">estar legalmente autorizado,</mark> <mark class=\"m-personalizado\">emplee</mark> para la <mark class=\"m-personalizado\">caza o pesca</mark> <mark class=\"m-destacable\">veneno, medios explosivos</mark> u <mark class=\"m-destacable\">otros</mark> instrumentos o artes de <mark class=\"m-destacable\">similar eficacia <u class=\"m-clave\">destructiva</u> o <u class=\"m-clave\">no selectiva</u></mark> para la fauna</mark>, <mark class=\"m-accion\">será castigado</mark> con la pena de prisión de cuatro meses a dos años o multa de ocho a veinticuatro meses y, en cualquier caso, la de inhabilitación especial para profesión u oficio e inhabilitación especial para el ejercicio del derecho a cazar o pescar por tiempo de uno a tres años, con la privación del derecho para la tenencia y porte de armas por el mismo periodo.  <span class=\"ex-plg\"><span class=\"ex-plg-t\">Si el daño causado fuera de <mark class=\"m-destacable\">notoria importancia,</mark> <mark class=\"m-accion\">se impondrá</mark> la pena de prisión antes mencionada en su <mark class=\"m-personalizado\">mitad superior.</mark></span></span></p>"],["Artículo 346 <span class=\"ex-sello\">EXOF</span> <span class=\"ex-sello\">✱</span>","<p data-ex=\"EXOF,*\"><b>1.</b> Los que <mark class=\"m-destacable\">provocando</mark> <span class=\"m-circulo\"><mark class=\"m-destacable\"><mark class=\"m-resp\" data-q=\"19-223\">explosiones</mark></mark></span> o utilizando cualquier <mark class=\"m-personalizado\">otro medio de</mark> <mark class=\"m-destacable\">similar</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">potencia destructiva, causaren la destrucción de aeropuertos, puertos, estaciones, edificios, locales públicos, depósitos que contengan materiales inflamables o explosivos, vías de comunicación, medios de transporte colectivos, o la inmersión o varamiento de nave, inundación, explosión de una mina o instalación industrial, levantamiento de los carriles de una vía férrea, cambio malicioso de las señales empleadas en el servicio de ésta para la seguridad de los medios de transporte, voladura de puente, destrozo de calzada pública, daño a oleoductos, perturbación grave de cualquier clase o medio de comunicación, perturbación o interrupción del suministro de agua, electricidad, hidrocarburos u otro</span></span> recurso natural fundamental <mark class=\"m-accion\">incurrirán</mark> en la pena de prisión de diez a veinte años, cuando los <mark class=\"m-resp\" data-q=\"19-65,19-134\">estragos</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">comportaran necesariamente un peligro para la vida o</span></span> integridad de las <mark class=\"m-autoridad\">personas.</mark> <mark class=\"m-resp ex-q\" data-q=\"19-178,19-ia-1815\">🎯 2 preguntas</mark></p><p><b>3.</b> <mark class=\"m-personalizado\">Si, además</mark> del peligro, se hubiere <mark class=\"m-personalizado\">producido lesión</mark> para la <mark class=\"m-personalizado\">vida, integridad</mark> física <mark class=\"m-personalizado\">o salud de</mark> las <mark class=\"m-autoridad\">personas,</mark> los hechos <mark class=\"m-accion\">se castigarán</mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">separadamente</u></mark> con la pena correspondiente al delito cometido. <mark class=\"m-resp ex-q\" data-q=\"19-63,19-ia-1816\">🎯 2 preguntas</mark></p>"],["Artículo 348 <span class=\"ex-sello\">EX</span>","<p><b>1.</b> Los que en la <mark class=\"m-personalizado\">fabricación, manipulación, transporte, tenencia o comercialización de explosivos, sustancias inflamables o corrosivas, tóxicas y asfixiantes,</mark> <mark class=\"m-destacable\">o</mark> cualesquiera <mark class=\"m-personalizado\">otras</mark> materias, aparatos o <mark class=\"m-personalizado\">artificios que</mark> <mark class=\"m-destacable\">puedan causar <mark class=\"m-resp\" data-q=\"19-73\">estragos</mark>,</mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">contravinieran</u> las normas de seguridad</mark> establecidas, <mark class=\"m-personalizado\">poniendo en concreto <u class=\"m-clave\">peligro</u> la vida, la</mark> <span class=\"m-circulo\"><mark class=\"m-personalizado\">integridad</mark></span> <mark class=\"m-personalizado\">física</mark> <mark class=\"m-destacable\"><u class=\"m-clave\">o</u></mark> <mark class=\"m-personalizado\">la salud</mark> de las <mark class=\"m-autoridad\">personas,</mark> o <mark class=\"m-personalizado\">el <mark class=\"m-resp r-ia\" data-q=\"19-ia-1818\">medio ambiente</mark>,</mark> <mark class=\"m-accion\">serán castigados</mark> con la pena de <mark class=\"m-personalizado\">prisión</mark> de seis meses a tres años, multa de doce a veinticuatro meses <mark class=\"m-personalizado\">e inhabilitación especial para empleo</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">o cargo público, profesión u oficio por tiempo de seis</span></span> a doce años. <mark class=\"m-personalizado\"><u class=\"m-clave\">Las</u> mismas penas</mark> <mark class=\"m-accion\">se impondrán</mark> a quien, <mark class=\"m-personalizado\">de forma ilegal, produzca, importe, exporte, comercialice <u class=\"m-clave\">o</u> utilice</mark> <mark class=\"m-destacable\">sustancias destructoras del <u class=\"m-clave\">ozono.</u></mark> <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-1819,19-ia-1821\">🎯 2 preguntas</mark></p><p><b>2.</b> Los responsables de la vigilancia, <span class=\"ex-plg\"><span class=\"ex-plg-t\">control y utilización de explosivos que puedan causar estragos que, contraviniendo la normativa en materia de explosivos, hayan</span></span> facilitado su efectiva pérdida o <mark class=\"m-resp r-ia\" data-q=\"19-ia-1820\">sustracción</mark> <mark class=\"m-accion\">serán castigados</mark> con las penas de prisión de seis meses a tres años, multa de doce a veinticuatro meses e inhabilitación especial para empleo o cargo público, profesión u oficio de seis a doce años.</p><p style=\"margin-left:18px\" data-ex=\"EX\"><b>b)</b> <mark class=\"m-personalizado\">Falsear u ocultar a</mark> la Administración <mark class=\"m-personalizado\">información relevante</mark> sobre el <mark class=\"m-personalizado\">cumplimiento de las</mark> medidas de <mark class=\"m-personalizado\">seguridad</mark> obligatorias relativas a explosivos. <mark class=\"m-resp ex-q\" data-q=\"19-302,19-ia-1822\">🎯 2 preguntas</mark></p></div></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo</mark> 349: <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-1823\">🎯 1 pregunta más de este artículo</mark></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo</mark> 350: <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-1824\">🎯 1 pregunta más de este artículo</mark>"],["Artículo 351 <span class=\"ex-sello ex-sello-r\">R14</span>","<p data-r=\"R14\"><span class=\"ex-sello ex-sello-r\">R14</span> Los que <mark class=\"m-destacable\"><u class=\"m-clave\">provocaren</u></mark> un incendio que <span class=\"ex-plg\"><span class=\"ex-plg-t\">comporte un peligro <mark class=\"m-personalizado\">para la vida</mark> o integridad</span></span> <mark class=\"m-personalizado\">física</mark> de las <mark class=\"m-autoridad\">personas,</mark> <mark class=\"m-accion\">serán castigados</mark> <mark class=\"m-resp\" data-q=\"19-113\">con la pena de prisión <mark class=\"m-personalizado\">de</mark> diez a veinte años</mark>. <span class=\"ex-plg\"><span class=\"ex-plg-t\">Los <mark class=\"m-autoridad\">Jueces o Tribunales</mark> <mark class=\"m-accion\">podrán imponer</mark> la pena inferior en grado atendidas la <mark class=\"m-autoridad\">menor</mark> entidad del peligro causado y <mark class=\"m-personalizado\">las</mark> demás circunstancias del hecho.</span></span> <mark class=\"m-resp ex-q\" data-q=\"19-85\">🎯 1 pregunta</mark></p><p>Cuando no concurra tal peligro para <span class=\"ex-plg\"><span class=\"ex-plg-t\">la <mark class=\"m-personalizado\">vida o integridad física</mark> de las <mark class=\"m-autoridad\">personas,</mark> los hechos <mark class=\"m-accion\">se castigarán</mark> como <mark class=\"m-destacable\">daños</mark> previstos en el artículo 266 de este Código.</span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-1825\">🎯 1 pregunta</mark></p>"],["Artículo 355 <span class=\"ex-sello\">EXOF</span>","<p data-ex=\"EXOF\"><mark class=\"m-personalizado\"><u class=\"m-clave\">En todos los casos</u> previstos</mark> en esta sección, los <mark class=\"m-autoridad\">Jueces o Tribunales</mark> <mark class=\"m-accion\">podrán acordar</mark> que <mark class=\"m-destacable\">la calificación</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">del suelo en las zonas afectadas por un incendio forestal no pueda modificarse en</span></span> un plazo de <mark class=\"m-resp\" data-q=\"19-62,19-224,19-ia-1833\">hasta treinta años</mark>. Igualmente <mark class=\"m-accion\">podrán acordar</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">que se limiten o supriman los usos que se vinieran llevando a cabo en las zonas afectadas por</span></span> el incendio, así <mark class=\"m-personalizado\">como la intervención</mark> <mark class=\"m-destacable\">administrativa</mark> <mark class=\"m-personalizado\">de la madera</mark> quemada procedente del incendio. <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-1834\">🎯 1 pregunta</mark></p>"],["Artículo 357 <span class=\"ex-sello\">✱</span>","<p data-ex=\"*\"><mark class=\"m-personalizado\">El incendiario de</mark> <mark class=\"m-autoridad\">bienes</mark> propios <mark class=\"m-accion\">será castigado</mark> con la pena de <mark class=\"m-personalizado\">prisión</mark> de uno a cuatro años si tuviere <mark class=\"m-personalizado\"><u class=\"m-clave\">propósito</u> de <u class=\"m-clave\">defraudar</u></mark> o <mark class=\"m-personalizado\"><u class=\"m-clave\">perjudicar</u> a <u class=\"m-clave\">terceros,</u> hubiere causado <u class=\"m-clave\">defraudación</u></mark> <mark class=\"m-autoridad\">o perjuicio, existiere peligro de propagación a edificio, arbolado o plantío ajeno</mark> <mark class=\"m-personalizado\">o hubiere perjudicado gravemente las condiciones de la</mark> <span class=\"m-circulo\"><mark class=\"m-personalizado\">vida</mark></span> <mark class=\"m-personalizado\">silvestre, los bosques</mark> <span class=\"m-circulo\"><mark class=\"m-destacable\">o</mark></span> <mark class=\"m-personalizado\">los espacios naturales.</mark>  <mark class=\"m-resp ex-q\" data-q=\"19-304,19-ia-1836\">🎯 2 preguntas</mark></p>"],["Artículo 359","<p><mark class=\"m-personalizado\">El que, sin hallarse <u class=\"m-clave\">debidamente autorizado,</u></mark> <mark class=\"m-destacable\">elabore</mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">sustancias</u> nocivas <u class=\"m-clave\">para</u> la salud</mark> o <mark class=\"m-personalizado\">productos químicos que <u class=\"m-clave\">puedan</u></mark> <mark class=\"m-destacable\"><u class=\"m-clave\">causar <mark class=\"m-resp\" data-q=\"19-147\">estragos</mark>,</u></mark> <mark class=\"m-personalizado\">o los</mark> <mark class=\"m-destacable\">despache</mark> <mark class=\"m-personalizado\">o suministre, o comercie</mark> con ellos, <mark class=\"m-accion\">será castigado</mark> <mark class=\"m-personalizado\">con</mark> la pena <mark class=\"m-personalizado\">de prisión</mark> de seis meses a tres <mark class=\"m-personalizado\">años y multa</mark> de seis a doce meses, e <mark class=\"m-personalizado\">inhabilitación especial para profesión</mark> o industria por tiempo de seis meses a dos años. <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-1838\">🎯 1 pregunta</mark></p></div></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo</mark> 360: <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-1839\">🎯 1 pregunta más de este artículo</mark></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo</mark> 361: <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-1840\">🎯 1 pregunta más de este artículo</mark>"],["Artículo 365 <span class=\"ex-sello\">EX</span>","<p data-ex=\"EX\"><mark class=\"m-accion\">Será castigado</mark> con la pena de <mark class=\"m-personalizado\">prisión</mark> de dos a seis años el <mark class=\"m-destacable\">que envenenare o adulterare con sustancias infecciosas, u</mark> <mark class=\"m-personalizado\">otras</mark> que puedan ser <mark class=\"m-destacable\">gravemente <mark class=\"m-resp\" data-q=\"19-69\">nocivas</mark></mark> <mark class=\"m-autoridad\">para la salud, las aguas potables o las sustancias alimenticias</mark> destinadas al <mark class=\"m-personalizado\">uso público</mark> <mark class=\"m-destacable\">o</mark> <mark class=\"m-personalizado\">al consumo de una</mark> <mark class=\"m-plazo\">colectividad de</mark> <mark class=\"m-autoridad\">personas.</mark> <mark class=\"m-resp ex-q\" data-q=\"19-306,19-ia-1901\">🎯 2 preguntas</mark></p></div></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo</mark> 366: <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-1902\">🎯 1 pregunta más de este artículo</mark></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo</mark> 367: <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-1903\">🎯 1 pregunta más de este artículo</mark></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo</mark> 368: <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-1904,19-ia-1905\">🎯 2 preguntas más de este artículo</mark>"],["<mark class=\"m-destacable\">Artículo</mark> 369 <span class=\"ex-sello\">EX</span> <span class=\"ex-sello\">✱</span>","<p><b>1.ª</b> El culpable <mark class=\"m-autoridad\">fuere autoridad, funcionario público, facultativo, trabajador social, docente o educador y</mark> <mark class=\"m-personalizado\">obrase en el</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\"><span class=\"m-circulo\"><mark class=\"m-personalizado\">ejercicio</mark></span> <mark class=\"m-personalizado\"><u class=\"m-clave\">de</u> su cargo,</mark> profesión u oficio.</span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-1906\">🎯 1 pregunta</mark></p><p data-ex=\"EX\"><b>2.ª</b> El culpable <mark class=\"m-personalizado\">participare</mark> en otras <mark class=\"m-destacable\">actividades</mark> <mark class=\"m-personalizado\">organizadas o</mark> cuya ejecución se vea <mark class=\"m-personalizado\">facilitada por la</mark> <mark class=\"m-autoridad\"><u class=\"m-clave\">comisión</u></mark> <mark class=\"m-personalizado\">del delito.</mark> <mark class=\"m-resp ex-q\" data-q=\"19-307,19-ia-1907\">🎯 2 preguntas</mark></p><p data-ex=\"*\"><b><mark class=\"m-personalizado\"><u class=\"m-clave\">4.ª</u></mark></b> <mark class=\"m-personalizado\"><u class=\"m-clave\">Las sustancias a</u></mark> que se refiere el artículo anterior <mark class=\"m-personalizado\">se faciliten a</mark> <mark class=\"m-autoridad\">menores</mark> <mark class=\"m-personalizado\">de 18</mark> <mark class=\"m-destacable\">años, a disminuidos</mark> psíquicos o a <mark class=\"m-autoridad\">personas</mark> <mark class=\"m-destacable\">sometidas a</mark> tratamiento de <mark class=\"m-resp r-ia\" data-q=\"19-ia-1908\">deshabituación o rehabilitación</mark>.</p><p><b>5.ª</b> Fuere de <mark class=\"m-personalizado\">notoria importancia la cantidad</mark> de <span class=\"ex-plg\"><span class=\"ex-plg-t\">las citadas sustancias objeto de las conductas a que se refiere el artículo anterior.</span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-1909\">🎯 1 pregunta</mark></p><p><b>6.ª</b> Las referidas sustancias <mark class=\"m-personalizado\">se adulteren, manipulen o mezclen entre sí</mark> o <mark class=\"m-personalizado\">con otras, incrementando el posible</mark> daño <mark class=\"m-personalizado\">a <mark class=\"m-resp r-ia\" data-q=\"19-ia-1910\">la salud</mark>.</mark></p><p><b>7.ª</b> Las conductas descritas en <span class=\"ex-plg\"><span class=\"ex-plg-t\">el artículo anterior tengan <mark class=\"m-personalizado\">lugar en centros docentes,</mark> en centros, establecimientos o <mark class=\"m-personalizado\">unidades militares,</mark> en establecimientos <mark class=\"m-personalizado\">penitenciarios o</mark> en centros de <mark class=\"m-personalizado\">deshabituación</mark> o rehabilitación, <mark class=\"m-destacable\">o</mark> en sus <mark class=\"m-personalizado\">proximidades.</mark></span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-1911\">🎯 1 pregunta</mark></p><p><b>8.ª</b> El culpable <mark class=\"m-personalizado\">empleare violencia o exhibiere o hiciese uso de armas</mark> para cometer el hecho. <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-1912\">🎯 1 pregunta</mark></p></div></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo</mark> 369 bis: <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-1913\">🎯 1 pregunta más de este artículo</mark>"],["Artículo 370 <span class=\"ex-sello\">EX</span>","<p><mark class=\"m-accion\">Se impondrá</mark> la <mark class=\"m-destacable\">pena superior en uno o dos grados</mark> a la señalada en el artículo 368 cuando: <mark class=\"m-resp ex-q\" data-q=\"19-64\">🎯 1 pregunta</mark></p><p><b>1.º</b> <mark class=\"m-resp\" data-q=\"19-25,19-ia-1914\">Se utilice a <mark class=\"m-autoridad\"><u class=\"m-clave\">menores</u></mark> de 18 años <mark class=\"m-personalizado\">o a</mark> disminuidos psíquicos para cometer estos delitos</mark>.</p><p><b>2.º</b> Se trate de los <span class=\"ex-plg\"><span class=\"ex-plg-t\"><span class=\"m-circulo\"><mark class=\"m-personalizado\">jefes,</mark></span> <mark class=\"m-personalizado\">administradores o encargados de las <u class=\"m-clave\">organizaciones</u></mark> a que se refiere la circunstancia 2.ª del apartado 1 del artículo 369.</span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-1915\">🎯 1 pregunta</mark></p><p data-ex=\"EX\"><b>3.º</b> Las conductas descritas en el artículo 368 fuesen de <mark class=\"m-personalizado\">extrema gravedad.</mark> <mark class=\"m-resp ex-q\" data-q=\"19-308\">🎯 1 pregunta</mark></p><p>Se consideran de <mark class=\"m-destacable\">extrema gravedad</mark> los casos <span class=\"ex-plg\"><span class=\"ex-plg-t\">en que la <mark class=\"m-personalizado\">cantidad de las sustancias</mark> a que se refiere el artículo 368 <mark class=\"m-personalizado\">excediere notablemente</mark> de la considerada como de <mark class=\"m-personalizado\"><u class=\"m-clave\"><mark class=\"m-resp r-ia\" data-q=\"19-ia-1916\">notoria importancia</mark>, o</u> se</mark> hayan <mark class=\"m-personalizado\">utilizado buques, embarcaciones o aeronaves</mark> como medio de transporte específico, <mark class=\"m-personalizado\">o</mark> se hayan llevado a cabo las conductas indicadas <mark class=\"m-personalizado\">simulando operaciones de comercio internacional</mark> entre empresas, <mark class=\"m-personalizado\">o</mark> se trate de <mark class=\"m-personalizado\">redes internacionales</mark> dedicadas a este tipo de actividades, <mark class=\"m-destacable\">o</mark> cuando concurrieren <mark class=\"m-personalizado\">tres o más de las circunstancias</mark> previstas en el artículo <mark class=\"m-personalizado\">369.1.</mark></span></span> <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-1917\">🎯 1 pregunta</mark></p>"],["Artículo 373 <span class=\"ex-sello\">✱</span>","<p data-ex=\"*\">La provocación, la conspiración y la <span class=\"ex-plg\"><span class=\"ex-plg-t\">proposición para cometer los delitos previstos en los artículos 368</span></span> al 372, <mark class=\"m-accion\">se castigarán</mark> con la <mark class=\"m-resp\" data-q=\"19-309\">pena inferior en uno a <mark class=\"m-personalizado\">dos grados a</mark> la que corresponde, respectivamente, a los hechos previstos en los preceptos anteriores</mark>. <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-1923\">🎯 1 pregunta</mark></p></div></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo</mark> 374: <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-1924,19-ia-1925\">🎯 2 preguntas más de este artículo</mark></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo</mark> 375: <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-1926\">🎯 1 pregunta más de este artículo</mark>"],["Artículo 378 <span class=\"ex-sello\">✱</span>","<p data-ex=\"*\">Los <mark class=\"m-personalizado\">pagos</mark> que se efectúen por <span class=\"ex-plg\"><span class=\"ex-plg-t\">el penado por uno o varios de los delitos a que se refieren los artículos 361 al 372 <mark class=\"m-accion\">se imputarán</mark> por <mark class=\"m-destacable\">el orden</mark> siguiente:</span></span> </p><p><b>1.º</b> <mark class=\"m-personalizado\">A la <u class=\"m-clave\">reparación</u> del daño</mark> causado <mark class=\"m-destacable\">e</mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">indemnización</u> de perjuicios.</mark> <mark class=\"m-resp ex-q\" data-q=\"19-76,19-216,19-311,19-ia-1930\">🎯 4 preguntas</mark></p>"],["Artículo 404 <span class=\"ex-sello ex-sello-r\">R18</span>","<p data-ex=\"EXAMEN\" data-r=\"R18\"><span class=\"ex-sello ex-sello-r\">R18</span> A <mark class=\"m-plazo\">la</mark> <mark class=\"m-autoridad\">autoridad</mark> o <mark class=\"m-plazo\">funcionario público</mark> que, <mark class=\"m-destacable\">a sabiendas de su injusticia,</mark> <mark class=\"m-personalizado\">dictare</mark> una <mark class=\"m-destacable\">resolución arbitraria en un asunto administrativo se le</mark> <mark class=\"m-accion\">castigará</mark> <mark class=\"m-destacable\">con la pena de inhabilitación especial para empleo</mark> o cargo público y para el ejercicio del derecho <mark class=\"m-personalizado\">de sufragio</mark> <mark class=\"m-destacable\">pasivo</mark> por tiempo de nueve a quince años. <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-2019\">🎯 1 pregunta</mark></p>"],["Artículo 405 <span class=\"ex-sello\">EX</span>","<p data-ex=\"EX\"><mark class=\"m-plazo\">A la</mark> <mark class=\"m-autoridad\">autoridad o funcionario</mark> público que, en el <mark class=\"m-personalizado\">ejercicio</mark> <span class=\"m-caja\">de su competencia</span> <mark class=\"m-personalizado\">y</mark> <mark class=\"m-destacable\"><u class=\"m-clave\">a</u></mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">sabiendas de su ilegalidad, propusiere, nombrare o diere posesión para el</span></span> ejercicio de un <mark class=\"m-personalizado\">determinado cargo público a cualquier</mark> <mark class=\"m-autoridad\">persona</mark> <mark class=\"m-personalizado\">sin que concurran los <u class=\"m-clave\">requisitos legalmente</u></mark> establecidos para ello, se le <mark class=\"m-accion\">castigará</mark> con las penas de <mark class=\"m-personalizado\">multa</mark> de tres a ocho meses <mark class=\"m-personalizado\">y suspensión de empleo</mark> o cargo público por tiempo de uno a tres años. <mark class=\"m-resp ex-q\" data-q=\"19-312,19-ia-2020\">🎯 2 preguntas</mark></p></div></div><div class=\"vis\"><div class=\"vis-t\"><i>▦</i>PREVARICACIÓN · NOMBRAMIENTO ILEGAL (cuadro del temario · arts. 404 a 406)</div><div class=\"vis-tabla\"><div class=\"vt-cab\"><span>Conducta</span><span>Sujeto activo</span></div><div class=\"vt-nodo\"><div class=\"vt-et o\">Prevaricación de funcionario público · art. 404</div><div class=\"vt-hijos\"><div class=\"vt-hoja\"><span class=\"vt-p o\">Conducta</span><div class=\"vt-t\">Dictar resolución ARBITRARIA en un asunto administrativo, <u class=\"m-clave\">a sabiendas</u> de su injusticia.</div></div><div class=\"vt-hoja\"><span class=\"vt-p v\">Sujeto activo</span><div class=\"vt-t\">Autoridad o funcionario público.</div></div></div></div><div class=\"vt-nodo\"><div class=\"vt-et v\">Nombramiento ilegal · art. 405</div><div class=\"vt-hijos\"><div class=\"vt-hoja\"><span class=\"vt-p o\">Conducta</span><div class=\"vt-t\">Propusiere, nombrare o diere posesión para el ejercicio de un determinado cargo público a cualquier persona sin que concurran los requisitos legalmente establecidos, <u class=\"m-clave\">a sabiendas</u> de su ilegalidad.</div></div><div class=\"vt-hoja\"><span class=\"vt-p v\">Sujeto activo</span><div class=\"vt-t\">En el ejercicio de sus competencias: autoridad o funcionario público.</div></div></div></div><div class=\"vt-nodo\"><div class=\"vt-et c\">Aceptar nombramiento ilegal · art. 406</div><div class=\"vt-hijos\"><div class=\"vt-hoja\"><span class=\"vt-p o\">Conducta</span><div class=\"vt-t\">Aceptar propuesta, nombramiento o toma de posesión, <u class=\"m-clave\">sabiendo</u> que carece de los requisitos legales exigibles.</div></div><div class=\"vt-hoja\"><span class=\"vt-p v\">Sujeto activo</span><div class=\"vt-t\">Cualquier persona.</div></div></div></div></div></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo</mark> 406: <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-2021\">🎯 1 pregunta más de este artículo</mark>"],["Artículo 425","<p>Cuando el <mark class=\"m-destacable\">soborno</mark> <mark class=\"m-personalizado\">mediare en causa criminal a <u class=\"m-clave\">favor del</u> reo</mark> por parte de su <mark class=\"m-personalizado\">cónyuge</mark> u otra <mark class=\"m-autoridad\">persona</mark> a la que <mark class=\"m-personalizado\">se halle</mark> ligado de <mark class=\"m-personalizado\">forma estable</mark> por análoga relación de afectividad, <mark class=\"m-personalizado\">o</mark> de algún <mark class=\"m-personalizado\"><mark class=\"m-resp\" data-q=\"19-109\">ascendiente</mark>, descendiente o hermano</mark> por naturaleza, por adopción o <mark class=\"m-personalizado\">afines</mark> en los mismos grados, <mark class=\"m-accion\">se impondrá</mark> al sobornador la pena <mark class=\"m-personalizado\">de prisión</mark> de seis meses a un año.</p>"],["Artículo 428","<p><mark class=\"m-personalizado\">El funcionario público o</mark> <mark class=\"m-autoridad\">autoridad</mark> <mark class=\"m-personalizado\">que influyere en otro funcionario público o</mark> <mark class=\"m-autoridad\">autoridad</mark> <mark class=\"m-personalizado\">prevaliéndose</mark> del ejercicio de <mark class=\"m-personalizado\">las facultades de su cargo</mark> o <mark class=\"m-personalizado\">de cualquier otra situación derivada de su relación personal <u class=\"m-clave\">o</u> jerárquica con éste o con otro</mark> funcionario o <mark class=\"m-autoridad\">autoridad</mark> <mark class=\"m-personalizado\">para conseguir una resolución</mark> que le <mark class=\"m-personalizado\">pueda generar directa o indirectamente un <u class=\"m-clave\">beneficio</u></mark> económico <mark class=\"m-personalizado\">para</mark> sí <mark class=\"m-personalizado\"><u class=\"m-clave\">o</u></mark> para un <mark class=\"m-personalizado\">tercero,</mark> <mark class=\"m-accion\">incurrirá</mark> en las penas de <mark class=\"m-personalizado\">prisión</mark> de seis meses a dos años, <mark class=\"m-personalizado\">multa</mark> del tanto <mark class=\"m-personalizado\">al</mark> duplo del beneficio perseguido u obtenido <mark class=\"m-personalizado\">e inhabilitación especial</mark> para empleo <mark class=\"m-personalizado\">o</mark> cargo público <mark class=\"m-destacable\"><u class=\"m-clave\">y</u></mark> <mark class=\"m-personalizado\">para</mark> el ejercicio del derecho de <mark class=\"m-personalizado\">sufragio pasivo</mark> por tiempo de cinco a nueve años. <mark class=\"m-personalizado\">Si obtuviere el beneficio</mark> perseguido, estas penas <mark class=\"m-accion\">se impondrán</mark> en <mark class=\"m-personalizado\">su mitad superior.</mark>  <mark class=\"m-resp ex-q\" data-q=\"19-137,19-160,19-ia-2106\">🎯 3 preguntas</mark></p>"],["Artículo 429 <span class=\"ex-sello\">EX</span>","<p data-ex=\"EX\"><mark class=\"m-destacable\">El particular</mark> <mark class=\"m-personalizado\">que influyere en un funcionario público o</mark> <mark class=\"m-autoridad\">autoridad</mark> <mark class=\"m-personalizado\">prevaliéndose</mark> de cualquier situación derivada de <mark class=\"m-personalizado\">su relación personal con éste o con otro</mark> funcionario público o <mark class=\"m-autoridad\">autoridad</mark> <mark class=\"m-personalizado\">para conseguir una resolución</mark> que le pueda <mark class=\"m-personalizado\">generar directa o indirectamente</mark> un <mark class=\"m-personalizado\">beneficio económico para sí o</mark> para un <mark class=\"m-personalizado\">tercero,</mark> <mark class=\"m-accion\">será castigado</mark> con las penas de <mark class=\"m-personalizado\">prisión</mark> de seis meses a <mark class=\"m-personalizado\">dos años, multa del tanto</mark> al duplo del beneficio perseguido u obtenido, <mark class=\"m-destacable\"><u class=\"m-clave\">y</u></mark> <mark class=\"m-personalizado\">prohibición de contratar</mark> con el <mark class=\"m-personalizado\">sector</mark> público, así como la pérdida <mark class=\"m-personalizado\">de la</mark> posibilidad de obtener <mark class=\"m-personalizado\">subvenciones o ayudas</mark> públicas y del derecho a gozar de <mark class=\"m-personalizado\">beneficios o incentivos</mark> <mark class=\"m-autoridad\">fiscales</mark> y de la Seguridad Social por tiempo de seis a diez años. <mark class=\"m-personalizado\"><u class=\"m-clave\">Si</u> obtuviere el beneficio</mark> perseguido, estas penas <mark class=\"m-accion\">se impondrán</mark> en su <mark class=\"m-personalizado\">mitad superior.</mark> <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-2107\">🎯 1 pregunta</mark></p></div></div><div class=\"vis\"><div class=\"vis-t\"><i>▦</i>TRÁFICO DE INFLUENCIAS (cuadro del temario · arts. 428 a 430; con círculo «Ex»)</div><div class=\"vis-tabla\"><div class=\"vt-cab\"><span>Conducta · finalidad</span><span>Sujeto activo</span></div><div class=\"vt-nodo\"><div class=\"vt-et o\">Influencia por funcionario o autoridad · art. 428</div><div class=\"vt-hijos\"><div class=\"vt-hoja\"><span class=\"vt-p o\">Conducta</span><div class=\"vt-t\">Influenciar a funcionario público o autoridad <u class=\"m-clave\">prevaliéndose</u> de: el ejercicio de facultades de su cargo, o situación derivada de su relación personal o jerárquica con éste o con otro funcionario o autoridad.</div></div><div class=\"vt-hoja\"><span class=\"vt-p v\">Finalidad</span><div class=\"vt-t\">Conseguir una resolución que le pueda generar directa o indirectamente un beneficio económico para sí o para un tercero.</div></div><div class=\"vt-hoja\"><span class=\"vt-p c\">Sujeto activo</span><div class=\"vt-t\">Funcionario público o autoridad.</div></div></div></div><div class=\"vt-nodo\"><div class=\"vt-et v\">Influencia por particular · art. 429</div><div class=\"vt-hijos\"><div class=\"vt-hoja\"><span class=\"vt-p o\">Conducta</span><div class=\"vt-t\">Influenciar a funcionario público o autoridad <u class=\"m-clave\">prevaliéndose</u> de situación derivada de su relación personal con éste o con otro funcionario público o autoridad.</div></div><div class=\"vt-hoja\"><span class=\"vt-p v\">Finalidad</span><div class=\"vt-t\">Conseguir una resolución que le pueda generar directa o indirectamente un beneficio económico para sí o para un tercero.</div></div><div class=\"vt-hoja\"><span class=\"vt-p c\">Sujeto activo</span><div class=\"vt-t\">Particular.</div></div></div></div><div class=\"vt-nodo\"><div class=\"vt-et c\">Ofrecimiento de influencias · art. 430</div><div class=\"vt-hijos\"><div class=\"vt-hoja\"><span class=\"vt-p v\">Finalidad</span><div class=\"vt-t\">Solicitaren de terceros dádivas, presentes o cualquier otra remuneración, o aceptaren ofrecimiento o promesa.</div></div><div class=\"vt-hoja\"><span class=\"vt-p c\">Sujeto activo</span><div class=\"vt-t\">Funcionario o autoridad; particular (incluye personas jurídicas).</div></div></div></div></div></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo</mark> 430: <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-2108\">🎯 1 pregunta más de este artículo</mark></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo</mark> 431: <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-2109\">🎯 1 pregunta más de este artículo</mark>"],["Artículo 432 <span class=\"ex-sello\">EXOF</span>","<p data-ex=\"EXOF\"><b>1.</b> <mark class=\"m-autoridad\">La autoridad o funcionario público</mark> <mark class=\"m-personalizado\">que, con <mark class=\"m-resp r-ia\" data-q=\"19-ia-2110\">ánimo de lucro</mark>, se apropiare o consintiere que un tercero, con igual ánimo, se apropie</mark> del <mark class=\"m-personalizado\">patrimonio público</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">que tenga a su cargo por razón de sus funciones o con ocasión</span></span> de las mismas, <mark class=\"m-accion\">será castigado</mark> con una pena de <mark class=\"m-personalizado\">prisión</mark> de dos a seis años, <mark class=\"m-personalizado\">inhabilitación especial</mark> para cargo o empleo público <mark class=\"m-personalizado\">y</mark> para el ejercicio del derecho de <mark class=\"m-personalizado\">sufragio pasivo</mark> por tiempo de seis a diez años.</p><p style=\"margin-left:18px\"><b>a)</b> <mark class=\"m-personalizado\">se hubiera</mark> causado un daño o entorpecimiento graves al <mark class=\"m-resp r-ia\" data-q=\"19-ia-2111\">servicio público</mark>,</p><p style=\"margin-left:18px\"><b>b)</b> <mark class=\"m-destacable\">el valor del perjuicio</mark> causado o del patrimonio <mark class=\"m-destacable\">público</mark> apropiado excediere <mark class=\"m-plazo\">de</mark> <mark class=\"m-destacable\"><mark class=\"m-resp r-ia\" data-q=\"19-ia-2112\">50.000 euros</mark>,</mark></p><p>Si el valor del <mark class=\"m-destacable\">perjuicio causado o del patrimonio público apropiado excediere de 250.000</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">euros, <mark class=\"m-accion\">se impondrá</mark> la pena de prisión en su <mark class=\"m-personalizado\">mitad superior,</mark> pudiéndose llegar <mark class=\"m-personalizado\">hasta la superior en</mark> grado.</span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-2113\">🎯 1 pregunta</mark></p><p><b>3.</b> Los hechos a que se refiere el presente artículo <mark class=\"m-accion\">serán castigados</mark> con una pena de <mark class=\"m-personalizado\">prisión</mark> de uno a dos años <mark class=\"m-personalizado\">y multa</mark> de tres meses y un día a doce meses, y en todo caso <mark class=\"m-personalizado\">inhabilitación especial</mark> para cargo o empleo público <mark class=\"m-personalizado\">y derecho de sufragio pasivo</mark> por tiempo de uno a cinco años, cuando el perjuicio causado o el valor del patrimonio público <mark class=\"m-destacable\">sea inferior a <mark class=\"m-resp r-ia\" data-q=\"19-ia-2115\">4.000 euros</mark>.</mark></p></div></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo</mark> 432 bis: <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-2116\">🎯 1 pregunta más de este artículo</mark></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo</mark> 433: <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-2117\">🎯 1 pregunta más de este artículo</mark></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo</mark> 433 bis: <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-2118\">🎯 1 pregunta más de este artículo</mark>"],["Artículo 438","<p><mark class=\"m-autoridad\">La autoridad o funcionario</mark> <mark class=\"m-destacable\"><u class=\"m-clave\">público</u></mark> que, <mark class=\"m-personalizado\">abusando de su</mark> <mark class=\"m-autoridad\">cargo,</mark> cometiere algún delito de <mark class=\"m-personalizado\">estafa</mark> o de <mark class=\"m-resp\" data-q=\"19-88\">fraude</mark> de <span class=\"ex-plg\"><span class=\"ex-plg-t\">prestaciones del Sistema de Seguridad Social del artículo 307 ter, <mark class=\"m-accion\">incurrirá</mark> en las penas respectivamente señaladas a éstos, en su mitad</span></span> superior, pudiéndose llegar hasta la <mark class=\"m-resp r-ia\" data-q=\"19-ia-2126\">superior en grado</mark>, e inhabilitación especial para empleo o cargo público y para el ejercicio del derecho de sufragio pasivo por tiempo de tres a nueve años, salvo que los hechos estén castigados con una pena más grave en algún otro precepto de este Código.</p></div></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo</mark> 438 bis: <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-2127\">🎯 1 pregunta más de este artículo</mark>"],["Artículo 446 <span class=\"ex-sello\">✱</span> <span class=\"ex-sello ex-sello-r\">R21</span>","<p data-ex=\"*,EXAMEN\" data-r=\"R21\"><span class=\"ex-sello ex-sello-r\">R21</span> El <mark class=\"m-autoridad\">juez o magistrado</mark> que, a <mark class=\"m-personalizado\">sabiendas, dictare sentencia o resolución injusta</mark> <mark class=\"m-accion\">será castigado:</mark> <mark class=\"m-resp ex-q\" data-q=\"19-345\">🎯 1 pregunta</mark></p><p><b>1.º</b> Con la pena <mark class=\"m-personalizado\">de</mark> <mark class=\"m-destacable\"><u class=\"m-clave\">prisión</u></mark> <u class=\"m-clave\">de uno a cuatro</u> años si <u class=\"m-clave\">se</u> trata de <mark class=\"m-personalizado\">sentencia injusta</mark> contra el reo en causa criminal por <mark class=\"m-personalizado\">delito grave o <u class=\"m-clave\">menos grave y</u></mark> la sentencia no <mark class=\"m-personalizado\">hubiera llegado a ejecutarse,</mark> y con la misma pena en su <mark class=\"m-personalizado\">mitad superior y multa</mark> de doce a veinticuatro <mark class=\"m-personalizado\">meses</mark> si se <mark class=\"m-personalizado\">ha <u class=\"m-clave\">ejecutado.</u></mark> En ambos casos <mark class=\"m-accion\">se impondrá,</mark> <mark class=\"m-personalizado\">además,</mark> la pena de <mark class=\"m-personalizado\">inhabilitación absoluta</mark> por tiempo de diez a veinte años. <mark class=\"m-resp ex-q\" data-q=\"19-317\">🎯 1 pregunta</mark></p><p><b>2.º</b> Con la pena de <mark class=\"m-destacable\">multa</mark> de seis a doce meses <mark class=\"m-personalizado\">e inhabilitación <u class=\"m-clave\">especial</u></mark> para empleo o cargo público por tiempo de <u class=\"m-clave\">seis a</u> diez años, si se tratara de una <mark class=\"m-personalizado\">sentencia injusta contra el reo</mark> dictada en proceso por <mark class=\"m-personalizado\"><u class=\"m-clave\">delito</u></mark> <mark class=\"m-destacable\">leve.</mark>  <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-2202\">🎯 1 pregunta</mark></p>"],["Artículo 447 <span class=\"ex-sello\">EX</span>","<p data-ex=\"EX\"><mark class=\"m-autoridad\">El Juez o Magistrado</mark> <mark class=\"m-personalizado\">que por <mark class=\"m-resp\" data-q=\"19-188\">imprudencia grave o ignorancia inexcusable</mark> dictara sentencia</mark> <span class=\"m-circulo\"><mark class=\"m-personalizado\">o</mark></span> <mark class=\"m-personalizado\">resolución <mark class=\"m-resp r-ia\" data-q=\"19-ia-2203\">manifiestamente injusta</mark></mark> <mark class=\"m-accion\">incurrirá</mark> en la pena de <mark class=\"m-personalizado\">inhabilitación especial</mark> para empleo o cargo público por tiempo de dos a seis años.</p></div></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo</mark> 448: <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-2204\">🎯 1 pregunta más de este artículo</mark>"],["Artículo 449 <span class=\"ex-sello\">EX</span>","<p data-ex=\"EX\"><b>1.</b> En la <mark class=\"m-personalizado\">misma</mark> pena señalada en el artículo anterior <mark class=\"m-accion\">incurrirá</mark> el <mark class=\"m-autoridad\">Juez, Magistrado o Secretario</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">Judicial culpable de retardo malicioso en la</span></span> Administración de Justicia. <mark class=\"m-accion\">Se entenderá</mark> por malicioso el retardo provocado para conseguir cualquier <mark class=\"m-resp\" data-q=\"19-170\">finalidad ilegítima</mark>. <mark class=\"m-resp ex-q\" data-q=\"19-21,19-ia-2205\">🎯 2 preguntas</mark></p></div></div><div class=\"vis\"><div class=\"vis-t\"><i>▦</i>PREVARICACIÓN JUDICIAL · RETARDO MALICIOSO (cuadro del temario · arts. 446 a 449; con círculo «Ex»)</div><div class=\"vis-tabla\"><div class=\"vt-cab\"><span>Conducta</span><span>Sujeto activo</span></div><div class=\"vt-nodo\"><div class=\"vt-et o\">Prevaricación dolosa · art. 446</div><div class=\"vt-hijos\"><div class=\"vt-hoja\"><span class=\"vt-p o\">Conducta</span><div class=\"vt-t\">Dictar sentencia o resolución INJUSTA. «<u class=\"m-clave\">A sabiendas</u>» (requiere DOLO).</div></div><div class=\"vt-hoja\"><span class=\"vt-p v\">Sujeto activo</span><div class=\"vt-t\">Juez o Magistrado.</div></div></div></div><div class=\"vt-nodo\"><div class=\"vt-et v\">Prevaricación imprudente · art. 447</div><div class=\"vt-hijos\"><div class=\"vt-hoja\"><span class=\"vt-p o\">Conducta</span><div class=\"vt-t\">Dictar sentencia o resolución manifiestamente INJUSTA, por imprudencia grave o ignorancia inexcusable.</div></div><div class=\"vt-hoja\"><span class=\"vt-p v\">Sujeto activo</span><div class=\"vt-t\">Juez o Magistrado.</div></div></div></div><div class=\"vt-nodo\"><div class=\"vt-et c\">Prevaricación omisiva · art. 448</div><div class=\"vt-hijos\"><div class=\"vt-hoja\"><span class=\"vt-p o\">Conducta</span><div class=\"vt-t\">NEGARSE a juzgar, sin alegar causa legal, o so pretexto de oscuridad, insuficiencia o silencio de la ley.</div></div><div class=\"vt-hoja\"><span class=\"vt-p v\">Sujeto activo</span><div class=\"vt-t\">Juez o Magistrado.</div></div></div></div><div class=\"vt-nodo\"><div class=\"vt-et o\">Retardo malicioso · art. 449</div><div class=\"vt-hijos\"><div class=\"vt-hoja\"><span class=\"vt-p o\">Conducta</span><div class=\"vt-t\">Causar retardo MALICIOSO en la Administración de Justicia, provocado para conseguir cualquier finalidad ilegítima.</div></div><div class=\"vt-hoja\"><span class=\"vt-p v\">Sujeto activo</span><div class=\"vt-t\">Juez, Magistrado o Secretario Judicial.</div></div></div></div>"],["Artículo 459","<p>Las penas de los artículos precedentes <mark class=\"m-accion\">se impondrán</mark> en su <mark class=\"m-personalizado\"><u class=\"m-clave\">mitad</u> superior a los</mark> peritos o intérpretes <mark class=\"m-personalizado\">que faltaren a la verdad</mark> maliciosamente en su dictamen o traducción, los cuales <mark class=\"m-accion\">serán,</mark> <mark class=\"m-personalizado\">además,</mark> castigados con la pena de <mark class=\"m-personalizado\"><mark class=\"m-resp\" data-q=\"19-250\">inhabilitación especial</mark></mark> para profesión u oficio, empleo o cargo público, por tiempo de seis a doce años.</p></div></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo</mark> 461: <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-2219,19-ia-2220\">🎯 2 preguntas más de este artículo</mark>"],["Artículo 462 <span class=\"ex-sello\">EXOF</span>","<p data-ex=\"EXOF\"><mark class=\"m-accion\">Quedará</mark> <mark class=\"m-destacable\">exento</mark> de pena el que, habiendo prestado un <mark class=\"m-personalizado\">falso testimonio en causa criminal,</mark> <mark class=\"m-destacable\">se retracte</mark> <mark class=\"m-personalizado\">en tiempo y forma,</mark> manifestando la verdad <mark class=\"m-personalizado\">para que surta efecto <u class=\"m-clave\">antes</u> de que se dicte</mark> <mark class=\"m-destacable\">sentencia</mark> en el proceso de que se trate. <mark class=\"m-personalizado\">Si a consecuencia</mark> del falso testimonio, <mark class=\"m-personalizado\">se hubiese producido la privación de libertad,</mark> <mark class=\"m-accion\">se impondrán</mark> las penas correspondientes <mark class=\"m-personalizado\">inferiores <u class=\"m-clave\">en grado.</u></mark> <mark class=\"m-resp ex-q\" data-q=\"19-202,19-ia-2221\">🎯 2 preguntas</mark></p>"],["Artículo 463 <span class=\"ex-sello\">EXOF</span> <span class=\"ex-sello ex-sello-r\">R22</span>","<p data-ex=\"EXOF\" data-r=\"R22\"><span class=\"ex-sello ex-sello-r\">R22</span> <b>1.</b> El que, <mark class=\"m-destacable\">citado</mark> <mark class=\"m-personalizado\">en legal forma, <u class=\"m-clave\">dejare</u></mark> <mark class=\"m-destacable\"><u class=\"m-clave\">voluntariamente</u></mark> <mark class=\"m-personalizado\">de comparecer, sin justa causa, ante un</mark> <mark class=\"m-autoridad\">juzgado o tribunal</mark> en <mark class=\"m-personalizado\">proceso criminal</mark> <mark class=\"m-destacable\"><u class=\"m-clave\">con reo en</u></mark> prisión provisional, <mark class=\"m-personalizado\">provocando la suspensión</mark> <mark class=\"m-destacable\">del <mark class=\"m-resp r-ia\" data-q=\"19-ia-2222\">juicio oral</mark>,</mark> <mark class=\"m-accion\">será castigado</mark> con la pena de <mark class=\"m-personalizado\">prisión</mark> de tres a seis meses <mark class=\"m-personalizado\">o multa</mark> de seis a 24 meses. En la pena de <mark class=\"m-personalizado\">multa</mark> de seis a 10 meses <mark class=\"m-accion\">incurrirá</mark> el que, habiendo <u class=\"m-clave\">sido</u> <mark class=\"m-personalizado\">advertido, lo hiciera por</mark> <mark class=\"m-autoridad\"><u class=\"m-clave\">segunda vez en causa criminal sin</u> reo <u class=\"m-clave\">en</u></mark> <mark class=\"m-personalizado\">prisión, haya provocado</mark> <mark class=\"m-autoridad\">o no</mark> la suspensión.</p></div></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo</mark> 464: <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-2223,19-ia-2224\">🎯 2 preguntas más de este artículo</mark>"],["Artículo 468 <span class=\"ex-sello\">EX</span>","<p data-ex=\"EX\"><b>1.</b> <mark class=\"m-personalizado\"><u class=\"m-clave\">Los</u> que quebrantaren</mark> su <mark class=\"m-personalizado\">condena, medida de seguridad, prisión, <u class=\"m-clave\">medida cautelar,</u> conducción o</mark> <mark class=\"m-destacable\"><u class=\"m-clave\">custodia</u></mark> <mark class=\"m-accion\">serán castigados</mark> con la pena de <mark class=\"m-personalizado\">prisión</mark> de seis meses a un año <mark class=\"m-personalizado\">si estuvieran privados de libertad, y</mark> con la pena de <mark class=\"m-personalizado\">multa</mark> de doce a veinticuatro meses en <mark class=\"m-personalizado\">los demás casos.</mark></p></div></div><div class=\"vis\"><div class=\"vis-t\"><i>⇄</i>DEL QUEBRANTAMIENTO DE CONDENA (cuadro del temario · art. 468)</div><div class=\"vis-comp\" style=\"--n:3\"><div class=\"vis-col\"><h5>Art. 468.1</h5><ul><li>QUEBRANTAR: condena, <mark class=\"m-personalizado\">prisión</mark>, <mark class=\"m-personalizado\">medida</mark> de <mark class=\"m-personalizado\">seguridad</mark>, <mark class=\"m-personalizado\">medida</mark> <u class=\"m-clave\">cautelar</u>, <mark class=\"m-destacable\">custodia</mark> o conducción.</li><li><mark class=\"m-personalizado\">Si</mark> estuvieran <u class=\"m-clave\">privados de libertad</u> → una <mark class=\"m-personalizado\">pena</mark>; <u class=\"m-clave\">demás</u> <mark class=\"m-personalizado\">casos</mark> → otra.</li></ul></div><div class=\"vis-col\"><h5>Art. 468.2</h5><ul><li>QUEBRANTAR: <mark class=\"m-personalizado\">pena</mark> de las contempladas en el art. 48 CP; <mark class=\"m-personalizado\">medida</mark> <u class=\"m-clave\">cautelar</u> o de <mark class=\"m-personalizado\">seguridad</mark> de la <u class=\"m-clave\">misma</u> naturaleza impuesta <mark class=\"m-personalizado\">en procesos</mark> criminales en los que <mark class=\"m-personalizado\">el ofendido sea</mark> <mark class=\"m-personalizado\">alguna</mark> de las <mark class=\"m-autoridad\">personas</mark> del art. 173.2 CP; <u class=\"m-clave\">libertad</u> vigilada.</li></ul></div><div class=\"vis-col\"><h5>Art. 468.3</h5><ul><li>INUTILIZAR o PERTURBAR el <mark class=\"m-personalizado\">funcionamiento</mark> normal de los dispositivos técnicos dispuestos para <mark class=\"m-personalizado\">controlar</mark> el cumplimiento de <mark class=\"m-personalizado\">penas</mark>, <mark class=\"m-personalizado\">medidas de seguridad</mark> o cautelares.</li><li><u class=\"m-clave\">NO</u> <u class=\"m-clave\">LLEVAR</u> CONSIGO estos dispositivos de control.</li><li>OMITIR <mark class=\"m-personalizado\">medidas</mark> exigibles para mantener su correcto <mark class=\"m-autoridad\">estado</mark> de <mark class=\"m-personalizado\">funcionamiento</mark>.</li></ul></div></div></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo</mark> 469: <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-2228\">🎯 1 pregunta más de este artículo</mark>"],["Artículo 470","<p><b>1.</b> <mark class=\"m-personalizado\">El particular</mark> que <mark class=\"m-personalizado\">proporcionare la evasión a un condenado, preso o detenido,</mark> bien del lugar en <mark class=\"m-personalizado\">que esté recluido,</mark> bien <mark class=\"m-personalizado\">durante su <mark class=\"m-resp r-ia\" data-q=\"19-ia-2229\">conducción</mark>,</mark> <mark class=\"m-accion\">será castigado</mark> con la pena de <mark class=\"m-personalizado\">prisión</mark> de seis meses a un año y multa de doce a veinticuatro meses. <mark class=\"m-resp ex-q\" data-q=\"19-45\">🎯 1 pregunta</mark></p></div></div><div class=\"vis\"><div class=\"vis-t\"><i>▦</i>QUEBRANTAMIENTO CUALIFICADO · FAVORECIMIENTO DE LA EVASIÓN (cuadro del temario · arts. 469 a 471)</div><div class=\"vis-tabla\"><div class=\"vt-cab\"><span>Conducta</span><span>Sujeto activo</span></div><div class=\"vt-nodo\"><div class=\"vt-et o\">Quebrantamiento cualificado · art. 469</div><div class=\"vt-hijos\"><div class=\"vt-hoja\"><span class=\"vt-p o\">Conducta</span><div class=\"vt-t\">FUGARSE del lugar en que estén recluidos: haciendo uso de violencia o intimidación en las personas, o de fuerza en las cosas, o tomando parte en motín.</div></div><div class=\"vt-hoja\"><span class=\"vt-p v\">Sujeto activo</span><div class=\"vt-t\">Sentenciados o presos.</div></div></div></div><div class=\"vt-nodo\"><div class=\"vt-et v\">Favorecimiento de la evasión · art. 470</div><div class=\"vt-hijos\"><div class=\"vt-hoja\"><span class=\"vt-p o\">Conducta</span><div class=\"vt-t\">PROPORCIONAR la evasión de un condenado, preso o detenido: bien del lugar en que esté recluido, o durante su conducción.</div></div><div class=\"vt-hoja\"><span class=\"vt-p v\">Sujeto activo</span><div class=\"vt-t\">Particular.</div></div></div></div><div class=\"vt-nodo\"><div class=\"vt-et c\">Favorecimiento de la evasión · art. 471</div><div class=\"vt-hijos\"><div class=\"vt-hoja\"><span class=\"vt-p o\">Conducta</span><div class=\"vt-t\">PROPORCIONAR la evasión de un condenado, preso o detenido.</div></div><div class=\"vt-hoja\"><span class=\"vt-p v\">Sujeto activo</span><div class=\"vt-t\">Funcionario público encargado de la conducción o custodia de un condenado, preso o detenido.</div></div></div></div></div></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo</mark> 471: <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-2230\">🎯 1 pregunta más de este artículo</mark>"],["Artículo 471 bis <span class=\"ex-sello\">EX</span>","<p data-ex=\"EX\"><b>1.</b> El <mark class=\"m-autoridad\">testigo que,</mark> <mark class=\"m-personalizado\">intencionadamente,</mark> <mark class=\"m-destacable\"><u class=\"m-clave\">faltare a</u> la <u class=\"m-clave\">verdad</u></mark> en su testimonio <mark class=\"m-personalizado\">ante</mark> la <mark class=\"m-autoridad\">Corte Penal Internacional,</mark> estando <mark class=\"m-personalizado\">obligado</mark> a <mark class=\"m-personalizado\">decir verdad</mark> conforme a las <mark class=\"m-personalizado\">normas</mark> estatutarias <mark class=\"m-personalizado\">y reglas</mark> de procedimiento y prueba de <mark class=\"m-personalizado\">dicha</mark> <mark class=\"m-autoridad\">Corte,</mark> <mark class=\"m-accion\">será castigado</mark> con <mark class=\"m-personalizado\">prisión</mark> de seis meses a dos años. Si el <mark class=\"m-resp\" data-q=\"19-114\">falso testimonio</mark> se diera <mark class=\"m-personalizado\">en contra del acusado,</mark> la pena <mark class=\"m-accion\">será</mark> <mark class=\"m-personalizado\">de prisión</mark> de dos a cuatro años. <mark class=\"m-personalizado\">Si a consecuencia del testimonio</mark> se dictara <mark class=\"m-personalizado\">un <u class=\"m-clave\">fallo</u> condenatorio,</mark> <mark class=\"m-accion\">se impondrá</mark> pena de prisión de cuatro a cinco años. <mark class=\"m-resp ex-q\" data-q=\"19-49,19-ia-2231\">🎯 2 preguntas</mark></p><p><b><mark class=\"m-personalizado\">2.</mark></b> <mark class=\"m-personalizado\">El que presentare pruebas ante la</mark> <mark class=\"m-autoridad\">Corte</mark> Penal Internacional <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-personalizado\">a sabiendas</mark> de que son <mark class=\"m-personalizado\">falsas o han sido falsificadas</mark> <mark class=\"m-accion\">será castigado</mark> con las <mark class=\"m-personalizado\">penas</mark> señaladas en <mark class=\"m-personalizado\">el apartado anterior de este artículo.</mark></span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-2232\">🎯 1 pregunta</mark></p><p><b>3.</b> <mark class=\"m-personalizado\">El que intencionadamente destruya</mark> o <mark class=\"m-personalizado\">altere pruebas,</mark> o <mark class=\"m-personalizado\">interfiera en las diligencias de prueba ante la</mark> <mark class=\"m-autoridad\">Corte</mark> Penal Internacional <mark class=\"m-accion\">será castigado</mark> con la <mark class=\"m-personalizado\">pena de prisión de seis meses a dos años y multa de siete a 12 meses.</mark>  <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-2233\">🎯 1 pregunta</mark></p><p><b><mark class=\"m-personalizado\">4.</mark></b> <mark class=\"m-personalizado\">El que corrompiera a un testigo, obstruyera su comparecencia</mark> o testimonio ante la <mark class=\"m-autoridad\">Corte</mark> Penal Internacional o <mark class=\"m-personalizado\">interfiriera</mark> en ellos <mark class=\"m-accion\">será castigado</mark> con la pena <mark class=\"m-personalizado\">de prisión</mark> de uno a cuatro años y multa de seis a 24 meses. <mark class=\"m-resp ex-q\" data-q=\"19-256,19-ia-2234\">🎯 2 preguntas</mark></p><p>En <mark class=\"m-personalizado\">la misma pena</mark> <mark class=\"m-accion\">incurrirá</mark> quien tome <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-personalizado\">represalias contra un testigo</mark> por su declaración ante la <mark class=\"m-autoridad\">Corte.</mark></span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-2235\">🎯 1 pregunta</mark></p><p><b>7.</b> <mark class=\"m-personalizado\">El que solicitara o aceptara un</mark> <mark class=\"m-destacable\"><mark class=\"m-resp\" data-q=\"19-230\">soborno</mark></mark> <mark class=\"m-personalizado\">en calidad de funcionario de la</mark> <mark class=\"m-autoridad\">Corte</mark> <mark class=\"m-personalizado\">y en relación con</mark> sus <mark class=\"m-personalizado\">funciones</mark> oficiales <mark class=\"m-accion\">incurrirá</mark> en la pena de <mark class=\"m-personalizado\">prisión</mark> de dos a cinco años <mark class=\"m-personalizado\">y multa</mark> del tanto al triplo del valor de la <mark class=\"m-resp r-ia\" data-q=\"19-ia-2236\">dádiva solicitada o aceptada</mark>.</p>"],["Artículo 472 <span class=\"ex-sello\">EX</span>","<p data-ex=\"EX\">Son reos del delito de <span class=\"m-caja\"><mark class=\"m-resp\" data-q=\"19-239\">rebelión</mark></span> los que se <mark class=\"m-destacable\"><u class=\"m-clave\">alzaren violenta y</u></mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">públicamente</u></mark> para cualquiera de los <mark class=\"m-personalizado\">fines siguientes:</mark> <mark class=\"m-resp ex-q\" data-q=\"19-93\">🎯 1 pregunta</mark></p><p><b>1.º</b> <mark class=\"m-destacable\">Derogar, suspender o modificar</mark> <mark class=\"m-personalizado\">total o parcialmente la</mark> <mark class=\"m-resp r-ia\" data-q=\"19-ia-2237\">Constitución</mark>.</p><p><b>3.º</b> <mark class=\"m-personalizado\"><u class=\"m-clave\">Impedir</u></mark> la libre celebración de <mark class=\"m-autoridad\">elecciones</mark> para cargos públicos. <mark class=\"m-resp ex-q\" data-q=\"19-259,19-ia-2238\">🎯 2 preguntas</mark></p><p><b>5.º</b> <mark class=\"m-destacable\"><u class=\"m-clave\">Declarar la independencia</u></mark> de <mark class=\"m-resp r-ia\" data-q=\"19-ia-2239\">una parte del territorio nacional</mark>.</p><p><b>7.º</b> <mark class=\"m-destacable\">Sustraer</mark> cualquier clase de <mark class=\"m-personalizado\">fuerza armada a la obediencia del</mark> <mark class=\"m-autoridad\"><mark class=\"m-resp r-ia\" data-q=\"19-ia-2240\">Gobierno</mark>.</mark></p></div></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo</mark> 473: <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-2301\">🎯 1 pregunta más de este artículo</mark>"],["Artículo 474","<p>Cuando la rebelión <mark class=\"m-personalizado\">no haya llegado a organizarse</mark> con jefes <span class=\"ex-plg\"><span class=\"ex-plg-t\">conocidos, <mark class=\"m-accion\">se reputarán</mark> como tales los <mark class=\"m-personalizado\">que de hecho dirijan a los demás, o lleven la voz por ellos, o firmen escritos expedidos</mark> a su <mark class=\"m-personalizado\">nombre, o</mark> ejerzan otros <mark class=\"m-personalizado\">actos</mark> semejantes <mark class=\"m-personalizado\">de <mark class=\"m-resp\" data-q=\"19-194,19-ia-2302\">dirección o representación</mark>.</mark></span></span></p>"],["Artículo 477 <span class=\"ex-sello\">✱</span>","<p data-ex=\"*\"><mark class=\"m-destacable\">La provocación, la conspiración y la proposición</mark> para cometer rebelión <mark class=\"m-accion\">serán castigadas,</mark> <mark class=\"m-personalizado\">además</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">de con la <mark class=\"m-personalizado\">inhabilitación</mark> prevista en</span></span> los artículos anteriores, con la <mark class=\"m-resp\" data-q=\"19-320\">pena de <mark class=\"m-personalizado\">prisión inferior en uno o</mark> dos <mark class=\"m-personalizado\">grados</mark> a la del delito correspondiente</mark>.</p>"],["Artículo 479","<p>Si los sublevados <mark class=\"m-personalizado\">no depusieran</mark> su actitud <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-personalizado\"><u class=\"m-clave\">inmediatamente después</u> de la intimación,</mark> la <mark class=\"m-autoridad\">autoridad</mark> <mark class=\"m-accion\">hará</mark> <mark class=\"m-destacable\">uso de la fuerza</mark> <mark class=\"m-personalizado\">de que disponga</mark> para disolverlos.</span></span>  <mark class=\"m-resp ex-q\" data-q=\"19-222,19-ia-2305\">🎯 2 preguntas</mark></p><p><mark class=\"m-accion\">No será</mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">necesaria</u> la intimación</mark> desde el momento en que los <mark class=\"m-personalizado\">rebeldes <mark class=\"m-resp\" data-q=\"19-193,19-ia-2306\">rompan el fuego</mark>.</mark></p>"],["Artículo 485 <span class=\"ex-sello ex-sello-r\">R23</span>","<p data-r=\"R23\"><span class=\"ex-sello ex-sello-r\">R23</span> <b>1.</b> <mark class=\"m-personalizado\">El que matare al <u class=\"m-clave\">Rey</u> o <u class=\"m-clave\">a la Reina</u> o al <u class=\"m-clave\">Príncipe</u> o a la Princesa de Asturias</mark> <mark class=\"m-accion\">será castigado</mark> con la <span class=\"m-circulo\"><mark class=\"m-autoridad\">pena de prisión permanente</mark></span> <mark class=\"m-autoridad\">revisable.</mark> <mark class=\"m-resp ex-q\" data-q=\"19-1\">🎯 1 pregunta</mark></p><p><b>3.</b> En el caso <mark class=\"m-destacable\">de tentativa</mark> de estos delitos <mark class=\"m-accion\">podrá imponerse</mark> la pena <mark class=\"m-personalizado\"><mark class=\"m-resp r-ia\" data-q=\"19-ia-2313\">inferior en un grado</mark>.</mark></p>"],["Artículo 493 <span class=\"ex-sello ex-sello-r\">R24</span>","<p data-r=\"R24\"><span class=\"ex-sello ex-sello-r\">R24</span> <mark class=\"m-personalizado\">Los que, sin alzarse públicamente, invadieren <u class=\"m-clave\">con fuerza,</u> violencia o intimidación las sedes</mark> del <mark class=\"m-personalizado\">Congreso de los</mark> Diputados, <mark class=\"m-personalizado\">del Senado</mark> <mark class=\"m-destacable\"><u class=\"m-clave\">o</u></mark> <mark class=\"m-personalizado\">de una</mark> <mark class=\"m-autoridad\">Asamblea</mark> Legislativa de Comunidad Autónoma, si <mark class=\"m-personalizado\"><u class=\"m-clave\"><mark class=\"m-resp\" data-q=\"19-321\">están reunidos</mark>,</u></mark> <mark class=\"m-accion\">serán castigados</mark> con la pena de <mark class=\"m-personalizado\">prisión</mark> de tres a cinco años.</p></div></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo</mark> 494: <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-2314\">🎯 1 pregunta más de este artículo</mark>"],["Artículo 506 <span class=\"ex-sello\">EX</span>","<p data-ex=\"EX\"><mark class=\"m-autoridad\">La autoridad o funcionario</mark> público que, <mark class=\"m-destacable\">careciendo de atribuciones para</mark> ello, <mark class=\"m-personalizado\">dictare una <u class=\"m-clave\">disposición general</u> o suspendiere su <mark class=\"m-resp r-ia\" data-q=\"19-ia-2319\">ejecución</mark>,</mark> <mark class=\"m-accion\">será castigado</mark> con la pena de <mark class=\"m-personalizado\">prisión</mark> de uno a tres años, <mark class=\"m-personalizado\">multa</mark> de seis a doce meses <mark class=\"m-personalizado\">e inhabilitación especial</mark> para empleo o cargo público por tiempo de <mark class=\"m-personalizado\">seis a</mark> doce años. <mark class=\"m-resp ex-q\" data-q=\"19-108,19-161,19-186\">🎯 3 preguntas</mark></p>"],["Artículo 508 <span class=\"ex-sello\">EX</span>","<p data-ex=\"EX\"><b>1.</b> <mark class=\"m-autoridad\">La autoridad o funcionario público</mark> <mark class=\"m-personalizado\">que se arrogare atribuciones</mark> <mark class=\"m-destacable\">judiciales</mark> <mark class=\"m-personalizado\">o impidiere ejecutar una resolución dictada por la</mark> <mark class=\"m-autoridad\">autoridad</mark> <mark class=\"m-personalizado\">judicial <mark class=\"m-resp r-ia\" data-q=\"19-ia-2320\">competente</mark>,</mark> <mark class=\"m-accion\">será castigado</mark> con las penas de <mark class=\"m-personalizado\">prisión</mark> de seis meses a un año, <mark class=\"m-personalizado\">multa</mark> de tres a ocho meses <mark class=\"m-personalizado\">y suspensión</mark> de empleo o cargo público por tiempo de uno a tres años.</p><p data-ex=\"EX\"><b>2.</b> <mark class=\"m-autoridad\">La autoridad o funcionario administrativo o militar</mark> que <mark class=\"m-personalizado\"><u class=\"m-clave\">atentare</u></mark> contra la <mark class=\"m-personalizado\">independencia de los</mark> <mark class=\"m-autoridad\">Jueces o Magistrados,</mark> garantizada por la Constitución, <mark class=\"m-personalizado\">dirigiéndoles instrucción, <u class=\"m-clave\">orden</u> o <u class=\"m-clave\">intimación</u> relativas a causas o actuaciones que estén <mark class=\"m-resp r-ia\" data-q=\"19-ia-2321\">conociendo</mark>,</mark> <mark class=\"m-accion\">será castigado</mark> <mark class=\"m-personalizado\">con la pena de prisión</mark> de uno a dos años, <mark class=\"m-personalizado\">multa</mark> de cuatro a diez meses <mark class=\"m-personalizado\">e inhabilitación especial</mark> para empleo o cargo público por tiempo de dos a seis años.</p>"],["Artículo 509 <span class=\"ex-sello\">EX</span>","<p data-ex=\"EX\"><mark class=\"m-autoridad\">El Juez o Magistrado, la autoridad o el funcionario</mark> público que, <mark class=\"m-personalizado\">legalmente requerido</mark> de <mark class=\"m-destacable\">inhibición,</mark> <mark class=\"m-personalizado\">continuare</mark> procediendo <mark class=\"m-personalizado\">sin esperar</mark> a que se decida el correspondiente <mark class=\"m-personalizado\">conflicto jurisdiccional, salvo</mark> en los casos <mark class=\"m-personalizado\">permitidos por la Ley,</mark> <mark class=\"m-accion\">será castigado</mark> con la pena de <mark class=\"m-personalizado\">multa de</mark> tres a diez meses <mark class=\"m-personalizado\">e inhabilitación especial</mark> para empleo o cargo público por tiempo de seis meses a un año. <mark class=\"m-resp ex-q\" data-q=\"19-97,19-ia-2322\">🎯 2 preguntas</mark></p></div></div><div class=\"vis\"><div class=\"vis-t\"><i>▦</i>USURPACIÓN DE ATRIBUCIONES (cuadro del temario · arts. 506 a 509; con círculo «Ex»)</div><div class=\"vis-tabla\"><div class=\"vt-cab\"><span>Conducta</span><span>Sujeto activo</span></div><div class=\"vt-nodo\"><div class=\"vt-et o\">Art. 506</div><div class=\"vt-hijos\"><div class=\"vt-hoja\"><span class=\"vt-p o\">Conducta</span><div class=\"vt-t\">Dictar una disposición general, o suspender la ejecución de una disposición general, careciendo de las atribuciones.</div></div><div class=\"vt-hoja\"><span class=\"vt-p v\">Sujeto activo</span><div class=\"vt-t\">Autoridad o funcionario público.</div></div></div></div><div class=\"vt-nodo\"><div class=\"vt-et v\">Art. 507</div><div class=\"vt-hijos\"><div class=\"vt-hoja\"><span class=\"vt-p o\">Conducta</span><div class=\"vt-t\">Arrogarse atribuciones administrativas de las que careciere, o impedir su legítimo ejercicio por quien las ostentare.</div></div><div class=\"vt-hoja\"><span class=\"vt-p v\">Sujeto activo</span><div class=\"vt-t\">Juez o Magistrado.</div></div></div></div><div class=\"vt-nodo\"><div class=\"vt-et c\">Art. 508.1</div><div class=\"vt-hijos\"><div class=\"vt-hoja\"><span class=\"vt-p o\">Conducta</span><div class=\"vt-t\">Arrogarse atribuciones judiciales, o impedir ejecutar una resolución dictada por la autoridad judicial competente.</div></div><div class=\"vt-hoja\"><span class=\"vt-p v\">Sujeto activo</span><div class=\"vt-t\">Autoridad o funcionario público.</div></div></div></div><div class=\"vt-nodo\"><div class=\"vt-et o\">Art. 508.2</div><div class=\"vt-hijos\"><div class=\"vt-hoja\"><span class=\"vt-p o\">Conducta</span><div class=\"vt-t\">Atentar contra la independencia de los Jueces y Magistrados, garantizada por la Constitución, dirigiendo instrucción, orden o intimación relativas a causas o actuaciones que estén conociendo los Jueces o Magistrados.</div></div><div class=\"vt-hoja\"><span class=\"vt-p v\">Sujeto activo</span><div class=\"vt-t\">Autoridad o funcionario administrativo o militar.</div></div></div></div><div class=\"vt-nodo\"><div class=\"vt-et v\">Art. 509</div><div class=\"vt-hijos\"><div class=\"vt-hoja\"><span class=\"vt-p o\">Conducta</span><div class=\"vt-t\">Continuar procediendo sin esperar a que se decida el correspondiente conflicto jurisdiccional (salvo casos permitidos por la ley), estando legalmente requerido de inhibición.</div></div><div class=\"vt-hoja\"><span class=\"vt-p v\">Sujeto activo</span><div class=\"vt-t\">Juez o Magistrado, o autoridad o funcionario público.</div></div></div></div>"],["Artículo 510","<p style=\"margin-left:18px\"><b>a)</b> Quienes <mark class=\"m-destacable\">públicamente</mark> <mark class=\"m-personalizado\">fomenten, promuevan o inciten directa</mark> o <mark class=\"m-personalizado\">indirectamente</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">al <mark class=\"m-destacable\">odio, hostilidad, discriminación o violencia</mark> <mark class=\"m-personalizado\">contra</mark> un grupo, una parte del mismo o contra una <mark class=\"m-autoridad\">persona</mark> determinada por razón de su pertenencia a aquel, por <mark class=\"m-destacable\">motivos racistas, antisemitas, antigitanos u otros</mark> referentes a la ideología, religión o creencias, situación familiar, la pertenencia de sus miembros a una etnia, raza o nación, su origen nacional, su sexo, orientación o identidad sexual, por razones de género, aporofobia, enfermedad o discapacidad.</span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-2323\">🎯 1 pregunta</mark></p><p style=\"margin-left:18px\"><b>b)</b> Quienes <mark class=\"m-personalizado\">produzcan, elaboren, posean</mark> con la <mark class=\"m-destacable\">finalidad</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">de <mark class=\"m-personalizado\">distribuir, faciliten</mark> a terceras <mark class=\"m-autoridad\">personas</mark> el acceso, <mark class=\"m-personalizado\">distribuyan, difundan o vendan</mark> escritos o cualquier otra clase de material o soportes que por su contenido sean idóneos para fomentar, promover, o incitar directa o indirectamente al <mark class=\"m-destacable\">odio, hostilidad, discriminación o violencia</mark> contra un grupo, una parte del mismo, o contra una <mark class=\"m-autoridad\">persona</mark> determinada por razón de su pertenencia a aquel, por <mark class=\"m-destacable\">motivos racistas, antisemitas, antigitanos u otros</mark> referentes a la ideología, religión o creencias, situación familiar, la pertenencia de sus miembros a una etnia, raza o nación, su origen nacional, su sexo, orientación o identidad sexual, por razones de género, aporofobia, enfermedad o discapacidad.</span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-2324\">🎯 1 pregunta</mark></p><p style=\"margin-left:18px\"><b>c)</b> Quienes <mark class=\"m-destacable\">públicamente</mark> <mark class=\"m-personalizado\">nieguen, trivialicen gravemente o enaltezcan</mark> los delitos <span class=\"ex-plg\"><span class=\"ex-plg-t\">de <mark class=\"m-personalizado\"><mark class=\"m-resp\" data-q=\"19-100\">genocidio</mark>,</mark> de <mark class=\"m-personalizado\">lesa humanidad</mark> o contra las <mark class=\"m-autoridad\">personas</mark> <mark class=\"m-personalizado\">y bienes protegidos</mark> en <mark class=\"m-personalizado\">caso de conflicto armado, o enaltezcan a sus autores,</mark> cuando se hubieran cometido contra un grupo o una <mark class=\"m-personalizado\">parte</mark> del mismo, o contra una <mark class=\"m-autoridad\">persona</mark> determinada por razón de su pertenencia al mismo, por <mark class=\"m-destacable\">motivos racistas, antisemitas, antigitanos, u otros</mark> referentes a la ideología, religión o creencias, la <mark class=\"m-destacable\">situación</mark> familiar o la pertenencia de sus miembros a una etnia, raza o nación, su origen nacional, su sexo, orientación o identidad sexual, por razones de género, aporofobia, enfermedad o discapacidad, cuando de este modo se promueva</span></span> o favorezca un clima de <mark class=\"m-resp r-ia\" data-q=\"19-ia-2325\">violencia, hostilidad, odio o discriminación contra los mismos</mark>.</p><p style=\"margin-left:18px\"><b>a)</b> Quienes <mark class=\"m-personalizado\">lesionen la dignidad de las</mark> <mark class=\"m-autoridad\">personas</mark> mediante acciones <span class=\"ex-plg\"><span class=\"ex-plg-t\">que entrañen <mark class=\"m-destacable\">humillación, menosprecio o descrédito</mark> de alguno de los grupos a que se refiere el apartado anterior, o de una parte de los mismos, o de cualquier <mark class=\"m-autoridad\">persona</mark> determinada por razón de su pertenencia a ellos por <mark class=\"m-destacable\">motivos <mark class=\"m-resp r-ia\" data-q=\"19-ia-2326\">racistas, antisemitas, antigitanos u otros</mark></mark> referentes a la ideología, religión o creencias, situación familiar, la pertenencia de sus miembros a una etnia, raza o nación, su origen nacional, su sexo, orientación o identidad sexual, por razones de género, aporofobia, enfermedad o discapacidad, o produzcan, elaboren, posean con la finalidad de distribuir, faciliten a terceras <mark class=\"m-autoridad\">personas</mark> el acceso, distribuyan, difundan o vendan escritos o cualquier otra clase de material o soportes que por su contenido sean idóneos para lesionar la dignidad de las <mark class=\"m-autoridad\">personas</mark> por representar una grave humillación, menosprecio o descrédito de alguno de los grupos mencionados, de una parte de ellos, o de cualquier <mark class=\"m-autoridad\">persona</mark> determinada por razón de su pertenencia a los mismos.</span></span></p><p style=\"margin-left:18px\"><b>b)</b> Quienes <mark class=\"m-personalizado\">enaltezcan o justifiquen por cualquier medio de expresión pública o de difusión</mark> los delitos <mark class=\"m-personalizado\">que hubieran sido</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">cometidos contra un grupo, una parte del mismo, o contra una <mark class=\"m-autoridad\">persona</mark> determinada por razón de su pertenencia a aquel por <mark class=\"m-personalizado\">motivos racistas, antisemitas,</mark> <mark class=\"m-destacable\">antigitanos u otros</mark> referentes a la ideología, religión o creencias, situación familiar, la pertenencia de sus miembros a una etnia, raza o nación, su origen nacional, su sexo, orientación o identidad sexual, por razones de género, aporofobia, enfermedad o discapacidad, o a</span></span> quienes hayan participado en su <mark class=\"m-resp r-ia\" data-q=\"19-ia-2327\">ejecución</mark>.</p><p><b>3.</b> Las penas previstas en los <span class=\"ex-plg\"><span class=\"ex-plg-t\">apartados anteriores <mark class=\"m-accion\">se impondrán</mark> en su mitad superior cuando los hechos se hubieran llevado a cabo a través de un medio de comunicación social, por medio de internet o mediante el uso de tecnologías de la información, de modo que, aquel se hiciera accesible a un elevado número de <mark class=\"m-autoridad\">personas.</mark></span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-2328\">🎯 1 pregunta</mark></p></div></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo</mark> 514: <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-2402,19-ia-2403\">🎯 2 preguntas más de este artículo</mark>"],["Artículo 515 <span class=\"ex-sello\">✱</span>","<p data-ex=\"*\"><mark class=\"m-personalizado\">Son punibles las</mark> <mark class=\"m-destacable\">asociaciones ilícitas,</mark> teniendo tal <mark class=\"m-personalizado\">consideración:</mark></p><p><b>1.º</b> Las que tengan por <mark class=\"m-destacable\"><u class=\"m-clave\">objeto</u></mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-personalizado\">cometer algún delito o, después de constituidas,</mark> <mark class=\"m-destacable\">promuevan</mark> su <mark class=\"m-autoridad\">comisión.</mark></span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-2404\">🎯 1 pregunta</mark></p><p><b>2.º</b> Las que, <mark class=\"m-personalizado\">aun</mark> teniendo por <span class=\"ex-plg\"><span class=\"ex-plg-t\">objeto <mark class=\"m-personalizado\">un fin lícito, empleen medios violentos o de alteración o control de <u class=\"m-clave\">la personalidad</u> para su consecución.</mark></span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-2405\">🎯 1 pregunta</mark></p><p><b>3.º</b> <mark class=\"m-personalizado\">Las organizaciones de <u class=\"m-clave\">carácter</u></mark> <mark class=\"m-destacable\"><u class=\"m-clave\">paramilitar.</u></mark> <mark class=\"m-resp ex-q\" data-q=\"19-323\">🎯 1 pregunta</mark></p><p><b>4.º</b> <mark class=\"m-personalizado\">Las que <u class=\"m-clave\">fomenten,</u> promuevan o inciten directa o indirectamente <u class=\"m-clave\">al odio,</u> hostilidad, discriminación o violencia</mark> contra <mark class=\"m-autoridad\">personas,</mark> grupos o <span class=\"ex-plg\"><span class=\"ex-plg-t\">asociaciones <mark class=\"m-personalizado\">por <u class=\"m-clave\">razón</u> de su ideología,</mark> religión o creencias, la pertenencia de sus miembros o de alguno de ellos <mark class=\"m-personalizado\">a</mark> una <mark class=\"m-personalizado\">etnia,</mark> raza o nación, su origen nacional, su sexo, edad, orientación o identidad sexual o de género, razones de género, de <mark class=\"m-personalizado\">aporofobia</mark> o de exclusión social, situación familiar, enfermedad <mark class=\"m-personalizado\">o discapacidad.</mark></span></span>  <mark class=\"m-resp ex-q\" data-q=\"19-52,19-ia-2406\">🎯 2 preguntas</mark></p>"],["Artículo 519 <span class=\"ex-sello\">✱</span>","<p data-ex=\"*\">La <mark class=\"m-destacable\">provocación, la conspiración y la proposición</mark> para cometer el delito de <mark class=\"m-personalizado\">asociación ilícita</mark> <mark class=\"m-accion\">se castigarán</mark> con la <mark class=\"m-resp\" data-q=\"19-324\">pena <mark class=\"m-personalizado\">inferior en uno o dos grados</mark> a la que corresponda, <mark class=\"m-personalizado\">respectivamente, a</mark> los hechos previstos en los artículos anteriores</mark>.</p>"],["Artículo 526","<p>El que, <mark class=\"m-destacable\"><u class=\"m-clave\">faltando al respeto</u></mark> <mark class=\"m-personalizado\">debido <u class=\"m-clave\">a</u></mark> la <mark class=\"m-personalizado\">memoria de</mark> los <mark class=\"m-personalizado\">muertos, <u class=\"m-clave\">violare</u> los <u class=\"m-clave\">sepulcros</u> o sepulturas,</mark> <mark class=\"m-destacable\"><u class=\"m-clave\">profanare</u></mark> <mark class=\"m-personalizado\">un</mark> <span class=\"m-circulo\"><mark class=\"m-personalizado\">cadáver</mark></span> <mark class=\"m-personalizado\">o sus cenizas o, con <mark class=\"m-resp\" data-q=\"19-195,19-ia-2410\">ánimo de ultraje</mark>,</mark> <span class=\"m-circulo\"><mark class=\"m-destacable\">destruyere,</mark></span> <mark class=\"m-destacable\">alterare o <u class=\"m-clave\">dañare</u></mark> <mark class=\"m-personalizado\">las urnas funerarias, panteones, lápidas o nichos</mark> <mark class=\"m-accion\">será castigado</mark> con la pena de <mark class=\"m-personalizado\">prisión</mark> de tres a cinco meses o multa de seis a 10 meses.</p>"],["Artículo 529 <span class=\"ex-sello\">EX</span>","<p data-ex=\"EX\"><b>1.</b> <mark class=\"m-autoridad\">El Juez o Magistrado que entregare una</mark> <mark class=\"m-personalizado\">causa criminal a otra</mark> <mark class=\"m-autoridad\">autoridad</mark> o <mark class=\"m-personalizado\">funcionario, militar</mark> o <mark class=\"m-personalizado\"><u class=\"m-clave\">administrativo,</u> que</mark> <mark class=\"m-destacable\"><u class=\"m-clave\">ilegalmente</u></mark> <mark class=\"m-personalizado\">se la reclame,</mark> <mark class=\"m-accion\">será castigado</mark> con la pena de <mark class=\"m-personalizado\">inhabilitación especial</mark> para empleo o cargo público por tiempo de seis meses a dos años.</p>"],["Artículo 530 <span class=\"ex-sello\">✱</span> <span class=\"ex-sello ex-sello-r\">R26</span>","<p data-ex=\"*\" data-r=\"R26\"><span class=\"ex-sello ex-sello-r\">R26</span> <mark class=\"m-autoridad\">La autoridad o funcionario público</mark> que, <mark class=\"m-personalizado\">mediando <u class=\"m-clave\">causa por delito,</u> acordare, practicare o prolongare</mark> cualquier <mark class=\"m-destacable\"><u class=\"m-clave\">privación de libertad</u></mark> <mark class=\"m-personalizado\">de un detenido, preso o sentenciado, <u class=\"m-clave\">con violación</u> de los <u class=\"m-clave\">plazos</u></mark> o <mark class=\"m-personalizado\"><u class=\"m-clave\">demás</u> garantías constitucionales o <mark class=\"m-resp r-ia\" data-q=\"19-ia-2411\">legales</mark>,</mark> <mark class=\"m-accion\">será castigado</mark> con la pena de <mark class=\"m-personalizado\">inhabilitación especial</mark> para empleo o cargo público por tiempo de cuatro a ocho años.</p></div></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo</mark> 531: <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-2412\">🎯 1 pregunta más de este artículo</mark>"],["Artículo 533 <span class=\"ex-sello\">EX</span> <span class=\"ex-sello\">✱</span>","<p data-ex=\"EX,*\"><mark class=\"m-autoridad\">El funcionario penitenciario o</mark> de centros de protección o corrección de <mark class=\"m-autoridad\">menores</mark> <mark class=\"m-personalizado\">que</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">impusiere a los reclusos o internos sanciones o privaciones indebidas, o usare con</span></span> ellos de un <mark class=\"m-resp r-ia\" data-q=\"19-ia-2413\">rigor innecesario</mark>, <mark class=\"m-accion\">será castigado</mark> con la pena de inhabilitación especial para empleo o cargo público por tiempo de dos a seis años. <mark class=\"m-resp ex-q\" data-q=\"19-18\">🎯 1 pregunta</mark></p></div></div><div class=\"vis\"><div class=\"vis-t\"><i>▦</i>DELITOS DE FUNCIONARIOS CONTRA LA LIBERTAD INDIVIDUAL Y LAS GARANTÍAS (cuadro del temario · arts. 529 a 533)</div><div class=\"vis-tabla\"><div class=\"vt-cab\"><span>Conducta</span><span>Sujeto activo</span></div><div class=\"vt-nodo\"><div class=\"vt-et o\">Entrega ilegal de causa criminal · art. 529</div><div class=\"vt-hijos\"><div class=\"vt-hoja\"><span class=\"vt-p o\">Conducta</span><div class=\"vt-t\">Hacer entrega de: causa criminal, o persona detenida, entregando a otra autoridad o funcionario, militar o administrativo, que <u class=\"m-clave\">ilegalmente</u> se la reclame.</div></div><div class=\"vt-hoja\"><span class=\"vt-p v\">Sujeto activo</span><div class=\"vt-t\">Juez o Magistrado.</div></div></div></div><div class=\"vt-nodo\"><div class=\"vt-et v\">Detención ilegal · art. 530</div><div class=\"vt-hijos\"><div class=\"vt-hoja\"><span class=\"vt-p o\">Conducta</span><div class=\"vt-t\">Acordar, practicar o prolongar cualquier PRIVACIÓN DE LIBERTAD de un detenido, preso o sentenciado: mediando causa por delito, <u class=\"m-clave\">violando plazos</u> o demás garantías constitucionales o legales.</div></div><div class=\"vt-hoja\"><span class=\"vt-p v\">Sujeto activo</span><div class=\"vt-t\">Autoridad o funcionario público.</div></div></div></div><div class=\"vt-nodo\"><div class=\"vt-et c\">Incomunicación ilegal · art. 531</div><div class=\"vt-hijos\"><div class=\"vt-hoja\"><span class=\"vt-p o\">Conducta</span><div class=\"vt-t\">Decretar, practicar o prolongar la INCOMUNICACIÓN de un detenido, preso o sentenciado.</div></div><div class=\"vt-hoja\"><span class=\"vt-p v\">Sujeto activo</span><div class=\"vt-t\">Autoridad o funcionario público.</div></div></div></div><div class=\"vt-nodo\"><div class=\"vt-et o\">Excesos cometidos por funcionarios de prisiones · art. 533</div><div class=\"vt-hijos\"><div class=\"vt-hoja\"><span class=\"vt-p o\">Conducta</span><div class=\"vt-t\">Imponer sanciones o privaciones indebidas, o usare rigor innecesario; dirigida a <mark class=\"m-plazo\">reclusos o internos</mark> (no a detenidos).</div></div><div class=\"vt-hoja\"><span class=\"vt-p v\">Sujeto activo</span><div class=\"vt-t\">Funcionario penitenciario, o de centros de protección o corrección de menores.</div></div></div></div>"],["Artículo 538 <span class=\"ex-sello\">EX</span>","<p data-ex=\"EX\"><mark class=\"m-autoridad\">La autoridad o funcionario público</mark> <mark class=\"m-personalizado\">que establezca la</mark> <mark class=\"m-destacable\">censura previa</mark> o, <mark class=\"m-personalizado\"><u class=\"m-clave\">fuera de</u> los casos permitidos por la Constitución y las Leyes, recoja ediciones de libros o periódicos</mark> <span class=\"m-circulo\"><mark class=\"m-personalizado\">o</mark></span> <mark class=\"m-personalizado\"><u class=\"m-clave\"><mark class=\"m-resp\" data-q=\"19-59\">suspenda</mark></u> su publicación o la difusión</mark> de cualquier <mark class=\"m-personalizado\">emisión <u class=\"m-clave\">radiotelevisiva,</u></mark> <mark class=\"m-accion\">incurrirá</mark> en la <mark class=\"m-personalizado\">pena de <mark class=\"m-resp\" data-q=\"19-326\">inhabilitación absoluta</mark> de seis</mark> a diez años.</p>"],["Artículo 543 <span class=\"ex-sello\">EXOF</span>","<p data-ex=\"EXOF\"><mark class=\"m-personalizado\">Las <u class=\"m-clave\">ofensas o</u> <mark class=\"m-resp\" data-q=\"19-143\">ultrajes</mark> de <u class=\"m-clave\">palabra,</u> por</mark> <mark class=\"m-destacable\"><u class=\"m-clave\">escrito</u> o de <u class=\"m-clave\">hecho</u></mark> <mark class=\"m-personalizado\">a España, a sus Comunidades</mark> Autónomas <mark class=\"m-destacable\">o a sus símbolos o emblemas, efectuados con</mark> <span class=\"m-circulo\"><mark class=\"m-destacable\">publicidad,</mark></span> <mark class=\"m-accion\">se castigarán</mark> con la pena de <mark class=\"m-personalizado\">multa</mark> de siete a doce meses. <mark class=\"m-resp ex-q\" data-q=\"19-227,19-327\">🎯 2 preguntas</mark></p>"],["Artículo 550 <span class=\"ex-sello\">EXOF</span> <span class=\"ex-sello\">✱</span>","<p data-ex=\"EXOF,*\"><b>1.</b> Son reos <u class=\"m-clave\">de</u> <mark class=\"m-destacable\">atentado</mark> <mark class=\"m-personalizado\">los que agredieren</mark> o, <mark class=\"m-personalizado\">con intimidación</mark> grave o <mark class=\"m-personalizado\">violencia, opusieren resistencia</mark> <mark class=\"m-destacable\"><u class=\"m-clave\">grave</u></mark> <mark class=\"m-personalizado\">a la</mark> <mark class=\"m-autoridad\">autoridad,</mark> <mark class=\"m-personalizado\">a sus agentes o funcionarios</mark> públicos, <span class=\"m-circulo\"><mark class=\"m-personalizado\">o</mark></span> <mark class=\"m-personalizado\">los <u class=\"m-clave\">acometieren,</u> cuando</mark> se <mark class=\"m-personalizado\">hallen en el ejercicio de las funciones de sus</mark> cargos o <mark class=\"m-personalizado\">con ocasión de ellas.</mark> <mark class=\"m-resp ex-q\" data-q=\"19-82,19-104,19-241,19-328,19-ia-2416\">🎯 5 preguntas</mark></p><p><u class=\"m-clave\">En</u> todo caso, <mark class=\"m-accion\">se considerarán</mark> actos <span class=\"ex-plg\"><span class=\"ex-plg-t\">de <mark class=\"m-destacable\">atentado</mark> los cometidos <mark class=\"m-personalizado\">contra los</mark> <mark class=\"m-destacable\">funcionarios docentes</mark> o <mark class=\"m-destacable\">sanitarios</mark> que se hallen <mark class=\"m-personalizado\">en</mark> el <mark class=\"m-personalizado\">ejercicio de <u class=\"m-clave\">las funciones</u></mark> propias de su cargo, o <mark class=\"m-personalizado\">con ocasión de ellas.</mark></span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-2417\">🎯 1 pregunta</mark></p>"],["Artículo 551 <span class=\"ex-sello\">EX</span>","<p data-ex=\"EX\"><mark class=\"m-accion\">Se impondrán</mark> las <mark class=\"m-destacable\">penas superiores en grado</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">a las respectivamente previstas en el artículo anterior siempre</span></span> que el atentado <mark class=\"m-personalizado\">se cometa:</mark></p><p><b>3.º</b> <mark class=\"m-personalizado\"><u class=\"m-clave\">Acometiendo</u></mark> a <mark class=\"m-personalizado\">la</mark> <mark class=\"m-autoridad\">autoridad,</mark> a su agente o al funcionario público <mark class=\"m-personalizado\">haciendo uso de</mark> un <mark class=\"m-personalizado\"><mark class=\"m-resp r-ia\" data-q=\"19-ia-2419\">vehículo de motor</mark>.</mark> <mark class=\"m-resp ex-q\" data-q=\"19-329\">🎯 1 pregunta</mark></p><p><b>4.º</b> Cuando los hechos se lleven <mark class=\"m-personalizado\">a cabo <u class=\"m-clave\">con</u> ocasión de un <u class=\"m-clave\">motín, plante o</u> incidente colectivo en el interior de un <mark class=\"m-resp r-ia\" data-q=\"19-ia-2420\">centro penitenciario</mark>.</mark></p>"],["Artículo 553 <span class=\"ex-sello\">✱</span>","<p data-ex=\"*\"><mark class=\"m-destacable\">La provocación, la conspiración</mark> y la proposición para cualquiera <span class=\"ex-plg\"><span class=\"ex-plg-t\">de los delitos previstos en los</span></span> artículos anteriores, <mark class=\"m-accion\">será castigada</mark> con la <mark class=\"m-resp\" data-q=\"19-330\">pena inferior <mark class=\"m-personalizado\">en uno o</mark> dos <mark class=\"m-personalizado\">grados</mark> a la del delito correspondiente</mark>.</p>"],["Artículo 557 bis","<p>Los que, <mark class=\"m-resp\" data-q=\"19-70\">actuando en grupo</mark>, invadan u ocupen, contra la voluntad de su titular, el domicilio de una <mark class=\"m-autoridad\">persona</mark> jurídica pública o privada, un despacho, <mark class=\"m-autoridad\">oficina,</mark> establecimiento o local, aunque se encuentre abierto al público, y causen con ello una perturbación relevante de la paz pública y de su actividad normal, <mark class=\"m-accion\">serán castigados</mark> con una pena de prisión de tres a seis meses o multa de seis a doce meses, salvo que los hechos ya estuvieran castigados con una pena más grave en otro precepto de este Código.</p>"],["Artículo 560","<p><b>1.</b> Los que <mark class=\"m-personalizado\">causaren</mark> <mark class=\"m-destacable\"><u class=\"m-clave\">daños que interrumpan, obstaculicen o destruyan líneas o instalaciones</u></mark> <mark class=\"m-personalizado\">de <u class=\"m-clave\">telecomunicaciones</u></mark> o <mark class=\"m-personalizado\">la correspondencia <mark class=\"m-resp r-ia\" data-q=\"19-ia-2504\">postal</mark>,</mark> <mark class=\"m-accion\">serán castigados</mark> con la pena de <mark class=\"m-personalizado\">prisión</mark> de uno a cinco años.</p><p><b>2.</b> En la <mark class=\"m-personalizado\">misma pena</mark> <mark class=\"m-accion\">incurrirán</mark> los <span class=\"ex-plg\"><span class=\"ex-plg-t\">que causen <mark class=\"m-personalizado\"><u class=\"m-clave\">daños</u> en vías férreas u originen un grave daño para</mark> la <mark class=\"m-personalizado\"><u class=\"m-clave\">circulación</u> <mark class=\"m-resp r-ia\" data-q=\"19-ia-2505\">ferroviaria</mark></mark> de alguna de las formas previstas en el artículo 382.</span></span></p><p data-ex=\"EXAMEN\"><b>3.</b> <mark class=\"m-personalizado\">Igual pena</mark> <mark class=\"m-accion\">se impondrá</mark> a los que <mark class=\"m-personalizado\"><u class=\"m-clave\">dañen</u> las conducciones o transmisiones de agua, gas o electricidad para las poblaciones, <mark class=\"m-resp\" data-q=\"19-332,19-ia-2506\">interrumpiendo o alterando gravemente el suministro o servicio</mark>.</mark></p></div></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo</mark> 561: <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-2507\">🎯 1 pregunta más de este artículo</mark>"],["Artículo 564 <span class=\"ex-sello\">EX</span>","<p><b>1.</b> La tenencia de armas de fuego reglamentadas, careciendo de las <mark class=\"m-resp r-ia\" data-q=\"19-ia-2510\">licencias o permisos necesarios</mark>, <mark class=\"m-accion\">será castigada:</mark></p><p data-ex=\"EX\"><b>2.</b> Los delitos previstos en el número anterior <mark class=\"m-accion\">se castigarán,</mark> respectivamente, con las penas de <mark class=\"m-personalizado\">prisión</mark> de dos a tres años y de uno a dos años, cuando concurra alguna de las circunstancias siguientes:</p><p><b>1.ª</b> Que las armas <mark class=\"m-personalizado\"><u class=\"m-clave\">carezcan</u> de <u class=\"m-clave\">marcas</u> de fábrica</mark> o <mark class=\"m-personalizado\">de número, o los tengan <mark class=\"m-resp r-ia\" data-q=\"19-ia-2511\">alterados o borrados</mark>.</mark> <mark class=\"m-resp ex-q\" data-q=\"19-334\">🎯 1 pregunta</mark></p><p><b>2.ª</b> Que hayan sido <mark class=\"m-personalizado\"><u class=\"m-clave\">introducidas ilegalmente</u></mark> en territorio <mark class=\"m-personalizado\">español.</mark> <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-2512\">🎯 1 pregunta</mark></p><p><b>3.ª</b> Que hayan sido <mark class=\"m-personalizado\"><u class=\"m-clave\">transformadas,</u> modificando sus <u class=\"m-clave\">características</u></mark> <span class=\"m-caja\"><mark class=\"m-personalizado\"><mark class=\"m-resp r-ia\" data-q=\"19-ia-2513\">originales</mark>.</mark></span></p></div></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo</mark> 565: <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-2514\">🎯 1 pregunta más de este artículo</mark></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo</mark> 566: <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-2515\">🎯 1 pregunta más de este artículo</mark>"],["Artículo 570 bis <span class=\"ex-sello\">EXOF</span>","<p data-ex=\"EXOF\"><b>1.</b> <mark class=\"m-personalizado\">Quienes <u class=\"m-clave\">promovieren, constituyeren, organizaren,</u> coordinaren o dirigieren una organización criminal</mark> <mark class=\"m-accion\">serán castigados</mark> con la pena de <mark class=\"m-personalizado\">prisión</mark> de cuatro a ocho años si aquélla tuviere por <mark class=\"m-personalizado\">finalidad u objeto</mark> la <mark class=\"m-autoridad\">comisión</mark> de <mark class=\"m-personalizado\">delitos graves, y con</mark> la pena de <mark class=\"m-personalizado\">prisión</mark> de tres a seis años en los <mark class=\"m-personalizado\">demás casos; <u class=\"m-clave\">y</u> quienes participaren activamente</mark> en la organización, <mark class=\"m-personalizado\"><u class=\"m-clave\">formaren</u> parte</mark> de ella <mark class=\"m-personalizado\"><u class=\"m-clave\">o</u> cooperaren <u class=\"m-clave\">económicamente</u> o</mark> de cualquier <mark class=\"m-personalizado\">otro modo</mark> con la misma <mark class=\"m-accion\">serán castigados</mark> con las penas <mark class=\"m-personalizado\">de prisión</mark> de dos a cinco años si tuviere como <mark class=\"m-personalizado\">fin</mark> la <mark class=\"m-autoridad\">comisión</mark> de <mark class=\"m-personalizado\">delitos graves, y</mark> con la pena de <mark class=\"m-personalizado\">prisión</mark> de uno a tres años en los <mark class=\"m-personalizado\">demás casos.</mark> <mark class=\"m-resp ex-q\" data-q=\"19-337\">🎯 1 pregunta</mark></p><p>A los efectos de este Código se entiende por <mark class=\"m-destacable\">organización criminal</mark> la <mark class=\"m-personalizado\"><u class=\"m-clave\">agrupación</u></mark> formada por <mark class=\"m-personalizado\"><u class=\"m-clave\">más de dos</u></mark> <mark class=\"m-autoridad\">personas</mark> <mark class=\"m-personalizado\">con <u class=\"m-clave\">carácter</u> estable o</mark> por tiempo <mark class=\"m-personalizado\"><u class=\"m-clave\">indefinido,</u> que de</mark> <span class=\"m-circulo\"><mark class=\"m-personalizado\">manera</mark></span> <mark class=\"m-personalizado\">concertada</mark> <span class=\"m-circulo\"><mark class=\"m-personalizado\">y coordinada</mark></span> <mark class=\"m-personalizado\">se repartan</mark> diversas <mark class=\"m-personalizado\">tareas</mark> o funciones con <mark class=\"m-personalizado\">el fin de cometer <u class=\"m-clave\">delitos.</u></mark> <mark class=\"m-resp ex-q\" data-q=\"19-118,19-264\">🎯 2 preguntas</mark></p><p style=\"margin-left:18px\"><b>a)</b> esté formada por un <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-personalizado\"><u class=\"m-clave\">elevado</u> número de</mark> <mark class=\"m-autoridad\">personas.</mark></span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-2525\">🎯 1 pregunta</mark></p><p style=\"margin-left:18px\"><b>c)</b> disponga de <mark class=\"m-personalizado\">medios tecnológicos avanzados de <u class=\"m-clave\">comunicación</u></mark> o <mark class=\"m-personalizado\">transporte</mark> que por sus características resulten <mark class=\"m-personalizado\"><u class=\"m-clave\">especialmente aptos</u> para facilitar la ejecución</mark> de los delitos <mark class=\"m-personalizado\">o la impunidad</mark> de los culpables. <mark class=\"m-resp ex-q\" data-q=\"19-158,19-ia-2527\">🎯 2 preguntas</mark></p><p><b>3.</b> <mark class=\"m-accion\">Se impondrán</mark> en su <mark class=\"m-personalizado\"><u class=\"m-clave\">mitad superior</u></mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">las penas respectivamente previstas en este artículo si los <mark class=\"m-personalizado\">delitos fueren contra la</mark> <span class=\"m-circulo\"><mark class=\"m-personalizado\">vida o la</mark></span> <mark class=\"m-personalizado\">integridad</mark> de las <mark class=\"m-autoridad\">personas,</mark> la <mark class=\"m-personalizado\">libertad, la libertad e indemnidad sexuales o la <u class=\"m-clave\">trata</u> de seres humanos.</mark></span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-2528\">🎯 1 pregunta</mark></p>"],["Artículo 570 ter","<p style=\"margin-left:18px\"><b>c)</b> Con la pena de tres meses a un año de <mark class=\"m-personalizado\">prisión</mark> cuando se trate de <mark class=\"m-personalizado\">cometer uno</mark> o <mark class=\"m-personalizado\">varios delitos <u class=\"m-clave\">menos</u> graves</mark> no incluidos en el apartado <mark class=\"m-personalizado\">a) o</mark> de <mark class=\"m-personalizado\">la perpetración reiterada de <u class=\"m-clave\">delitos leves.</u></mark>  <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-2530\">🎯 1 pregunta</mark></p><p>A los efectos de este Código <span class=\"ex-plg\"><span class=\"ex-plg-t\">se entiende por <mark class=\"m-destacable\">grupo criminal</mark> <mark class=\"m-personalizado\">la unión de <u class=\"m-clave\">más de</u> dos</mark> <mark class=\"m-autoridad\">personas</mark> que, <mark class=\"m-personalizado\">sin reunir <u class=\"m-clave\">alguna</u> o algunas de las características de la organización criminal</mark> definida en el artículo anterior, tenga <mark class=\"m-personalizado\">por finalidad</mark> o por objeto la <mark class=\"m-personalizado\">perpetración <u class=\"m-clave\">concertada</u> de delitos.</mark></span></span>  <mark class=\"m-resp ex-q\" data-q=\"19-38\">🎯 1 pregunta</mark></p><p><b>1.</b> <mark class=\"m-autoridad\">Los jueces o tribunales,</mark> en los supuestos previstos <span class=\"ex-plg\"><span class=\"ex-plg-t\">en este Capítulo y el siguiente, <mark class=\"m-accion\">acordarán</mark> <mark class=\"m-destacable\">la disolución</mark> de la organización o grupo y, en su caso, cualquier otra de las consecuencias de los artículos 33.7 y 129 de este Código.</span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-2531\">🎯 1 pregunta</mark></p><p><b>2.</b> <mark class=\"m-personalizado\">Asimismo</mark> <mark class=\"m-accion\">se impondrá</mark> a los responsables de las conductas descritas en los dos artículos anteriores, además de las penas en ellos previstas, la de <mark class=\"m-personalizado\">inhabilitación especial</mark> para todas aquellas <mark class=\"m-personalizado\">actividades</mark> económicas o negocios jurídicos <mark class=\"m-personalizado\">relacionados</mark> con la actividad de la organización o grupo criminal o con su actuación en el seno de los mismos, por un tiempo superior entre seis y veinte años al de la duración de la pena de privación de libertad impuesta en su caso, <mark class=\"m-personalizado\">atendiendo proporcionalmente a la gravedad</mark> del delito, <mark class=\"m-personalizado\">al número de</mark> los cometidos <mark class=\"m-personalizado\">y a las circunstancias</mark> que concurran en el delincuente.  <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-2532\">🎯 1 pregunta</mark></p><p><b>3.</b> Las disposiciones de este Capítulo <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-accion\">serán</mark> <mark class=\"m-personalizado\">aplicables</mark> a toda organización o grupo criminal que lleve a cabo cualquier <mark class=\"m-personalizado\"><u class=\"m-clave\">acto</u> penalmente relevante en España, aunque</mark> se hayan <mark class=\"m-personalizado\">constituido, estén asentados o desarrollen su actividad en el</mark> <mark class=\"m-autoridad\"><mark class=\"m-resp r-ia\" data-q=\"19-ia-2533\">extranjero</mark>.</mark></span></span></p></div></div><div class=\"vis\"><div class=\"vis-t\"><i>▦</i>ORGANIZACIÓN CRIMINAL · GRUPO CRIMINAL (cuadro del temario · arts. 570 bis y 570 ter; con círculo «Exof»)</div><div class=\"vis-tabla\"><div class=\"vt-cab\"><span>Organización criminal · 570 bis</span><span>Grupo criminal · 570 ter</span></div><div class=\"vt-nodo\"><div class=\"vt-et o\">Concepto</div><div class=\"vt-hijos\"><div class=\"vt-hoja\"><span class=\"vt-p o\">570 bis</span><div class=\"vt-t\">Agrupación formada por <mark class=\"m-plazo\">más de dos</mark> personas: con carácter estable o por tiempo indefinido; que de manera concertada y coordinada se repartan diversas tareas o funciones con el fin de cometer delitos.</div></div><div class=\"vt-hoja\"><span class=\"vt-p v\">570 ter</span><div class=\"vt-t\">Unión de <mark class=\"m-plazo\">más de dos</mark> personas: que <u class=\"m-clave\">no</u> reúnan alguna o algunas de las características de la organización criminal; que tengan por finalidad la perpetración concertada de delitos.</div></div></div></div><div class=\"vt-nodo\"><div class=\"vt-et v\">Conducta</div><div class=\"vt-hijos\"><div class=\"vt-hoja\"><span class=\"vt-p o\">570 bis</span><div class=\"vt-t\">Promover, constituir, organizar, coordinar o dirigir una organización criminal, o participar activamente, formar parte o cooperar económicamente o de cualquier otro modo.</div></div><div class=\"vt-hoja\"><span class=\"vt-p v\">570 ter</span><div class=\"vt-t\">Constituir, financiar o integrar un grupo criminal.</div></div></div></div><div class=\"vt-nodo\"><div class=\"vt-et c\">Finalidad del delito</div><div class=\"vt-hijos\"><div class=\"vt-hoja\"><span class=\"vt-p o\">570 bis</span><div class=\"vt-t\">Comisión de delitos graves; demás casos.</div></div><div class=\"vt-hoja\"><span class=\"vt-p v\">570 ter</span><div class=\"vt-t\">Comisión de delitos del art. 570 ter.1 (*delitos del art. 570.3 bis CP*), de cualquier otro delito grave, de uno o varios delitos menos graves, o perpetración reiterada de delitos leves.</div></div></div></div>"],["Artículo 573 <span class=\"ex-sello\">EX</span>","<p data-ex=\"EX\"><b>1.</b> <mark class=\"m-accion\">Se considerará</mark> <mark class=\"m-destacable\">delito de terrorismo</mark> la <mark class=\"m-autoridad\">comisión</mark> de <mark class=\"m-personalizado\">cualquier delito</mark> grave <mark class=\"m-personalizado\">contra la vida o la integridad física, la libertad, la <u class=\"m-clave\">integridad moral,</u> la libertad e indemnidad sexuales, el patrimonio, los recursos naturales o el</mark> <span class=\"m-circulo\"><mark class=\"m-personalizado\">medio</mark></span> <mark class=\"m-personalizado\">ambiente, la salud pública, de riesgo catastrófico, incendio, de falsedad documental, contra la Corona, de atentado y tenencia, tráfico y depósito de armas, municiones o explosivos,</mark> previstos en el presente Código, <mark class=\"m-personalizado\"><u class=\"m-clave\">y</u> el <u class=\"m-clave\">apoderamiento de</u> aeronaves, buques u otros medios</mark> de <mark class=\"m-personalizado\"><u class=\"m-clave\">transporte colectivo o</u> de mercancías,</mark> cuando se llevaran a cabo con cualquiera <mark class=\"m-personalizado\">de las siguientes</mark> <mark class=\"m-resp r-ia\" data-q=\"19-ia-2601\">finalidades</mark>:</p><p><b>1.ª</b> <mark class=\"m-personalizado\"><u class=\"m-clave\">Subvertir</u> el orden constitucional, o <u class=\"m-clave\">suprimir</u></mark> <mark class=\"m-destacable\"><u class=\"m-clave\">o desestabilizar</u></mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">gravemente</u> el funcionamiento de las instituciones políticas o de las estructuras económicas o sociales del</mark> <mark class=\"m-autoridad\">Estado,</mark> u <mark class=\"m-personalizado\"><mark class=\"m-resp r-ia\" data-q=\"19-ia-2602\">obligar a los poderes públicos a realizar un <u class=\"m-clave\">acto o</u> a <u class=\"m-clave\">abstenerse</u> de hacerlo</mark>.</mark> <mark class=\"m-resp ex-q\" data-q=\"19-23\">🎯 1 pregunta</mark></p><p><b>2.ª</b> Alterar <mark class=\"m-personalizado\"><u class=\"m-clave\">gravemente la</u> paz pública.</mark> <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-2603\">🎯 1 pregunta</mark></p><p><b>3.ª</b> <mark class=\"m-personalizado\"><u class=\"m-clave\">Desestabilizar</u></mark> <span class=\"m-circulo\"><mark class=\"m-personalizado\">gravemente</mark></span> <mark class=\"m-personalizado\">el funcionamiento de una <mark class=\"m-resp r-ia\" data-q=\"19-ia-2604\">organización internacional</mark>.</mark></p><p><b>4.ª</b> <mark class=\"m-personalizado\">Provocar un <u class=\"m-clave\">estado de terror</u> en la población o en una <u class=\"m-clave\">parte</u></mark> de ella. <mark class=\"m-resp ex-q\" data-q=\"19-128,19-ia-2605\">🎯 2 preguntas</mark></p><p><b>3.</b> <mark class=\"m-personalizado\">Asimismo,</mark> <mark class=\"m-accion\">tendrán</mark> la consideración <span class=\"ex-plg\"><span class=\"ex-plg-t\">de delitos de terrorismo <mark class=\"m-personalizado\">el resto de los delitos</mark> tipificados en <mark class=\"m-personalizado\">este Capítulo.</mark></span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-2606\">🎯 1 pregunta</mark></p>"],["Artículo 594","<p><b>1.</b> El español que, <mark class=\"m-resp\" data-q=\"19-275\">en tiempo de guerra</mark>, comunicare o hiciere circular noticias o rumores falsos encaminados a perjudicar el crédito del <mark class=\"m-autoridad\">Estado</mark> o los intereses de la Nación, <mark class=\"m-accion\">será castigado</mark> con las penas de prisión de seis meses a dos años.</p>"],["Artículo 605","<p><b>1.</b> <mark class=\"m-personalizado\">El que matare al</mark> <mark class=\"m-autoridad\">Jefe</mark> de un <mark class=\"m-autoridad\">Estado extranjero, o</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-personalizado\">a otra</mark> <mark class=\"m-autoridad\">persona</mark> <mark class=\"m-personalizado\">internacionalmente protegida por un Tratado, que se halle <u class=\"m-clave\">en</u> España,</mark> <mark class=\"m-accion\">será castigado</mark> con la pena de <mark class=\"m-personalizado\">prisión permanente revisable.</mark></span></span>  <mark class=\"m-resp ex-q\" data-q=\"19-90\">🎯 1 pregunta</mark></p></div></div><div class=\"vis\"><div class=\"vis-t\"><i>⇄</i>DELITOS CONTRA EL DERECHO DE GENTES (cuadro del temario · arts. 605 y 606)</div><div class=\"vis-comp\" style=\"--n:4\"><div class=\"vis-col\"><h5>Delitos contra la vida · 605.1</h5><ul><li>Matar al <mark class=\"m-autoridad\">Jefe</mark> de un <mark class=\"m-autoridad\">Estado</mark> <mark class=\"m-autoridad\">extranjero</mark> o a otra <mark class=\"m-autoridad\">persona</mark> internacionalmente <mark class=\"m-personalizado\">protegida</mark> por un Tratado que <mark class=\"m-personalizado\">se halle</mark> <mark class=\"m-personalizado\">en España</mark>.</li></ul></div><div class=\"vis-col\"><h5>Contra la salud e integridad física · 605.2</h5><ul><li>Causar <mark class=\"m-personalizado\">lesiones</mark> de las <mark class=\"m-personalizado\">previstas</mark> en el art. 149 o 150.</li></ul></div><div class=\"vis-col\"><h5>Otros delitos · 605.3</h5><ul><li>Cometer <mark class=\"m-personalizado\">cualquier</mark> <u class=\"m-clave\">otro delito</u> <mark class=\"m-autoridad\">contra</mark>: el sujeto <mark class=\"m-destacable\">pasivo</mark>, o sus <mark class=\"m-personalizado\">locales</mark> <u class=\"m-clave\">oficiales</u>, residencia <u class=\"m-clave\">particular</u> o <mark class=\"m-personalizado\">transporte</mark>.</li></ul></div><div class=\"vis-col\"><h5>Violación de la inmunidad personal · 606.1</h5><ul><li>Violar la inmunidad <u class=\"m-clave\">personal</u> del <mark class=\"m-autoridad\">Jefe</mark> de otro <mark class=\"m-autoridad\">Estado</mark> o de otra <mark class=\"m-autoridad\">persona</mark> internacionalmente <mark class=\"m-personalizado\">protegida</mark> por un Tratado.</li></ul></div></div></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo</mark> 606: <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-2630\">🎯 1 pregunta más de este artículo</mark>"],["Artículo 607 bis <span class=\"ex-sello\">EX</span>","<p><b>1.</b> Son reos de delitos <span class=\"ex-plg\"><span class=\"ex-plg-t\">de lesa humanidad quienes <mark class=\"m-personalizado\">cometan los hechos</mark> previstos en el <mark class=\"m-personalizado\">apartado siguiente como parte de un ataque generalizado o sistemático contra la población civil o</mark> <mark class=\"m-autoridad\">contra</mark> <mark class=\"m-personalizado\">una</mark> <mark class=\"m-autoridad\">parte de ella.</mark></span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-2701\">🎯 1 pregunta</mark></p><p><b>1.º</b> <mark class=\"m-personalizado\"><u class=\"m-clave\">Por</u> razón de pertenencia de la víctima</mark> a un grupo o <span class=\"ex-plg\"><span class=\"ex-plg-t\">colectivo perseguido por <mark class=\"m-personalizado\">motivos políticos, raciales, nacionales, étnicos, culturales, religiosos, de género, discapacidad u otros motivos universalmente reconocidos como <mark class=\"m-resp r-ia\" data-q=\"19-ia-2702\">inaceptables con arreglo al derecho internacional</mark>.</mark></span></span></p><p><b>2.º</b> <mark class=\"m-personalizado\">En el contexto de un régimen institucionalizado de</mark> opresión y dominación <span class=\"ex-plg\"><span class=\"ex-plg-t\">sistemáticas de <mark class=\"m-personalizado\">un grupo racial sobre</mark> uno <mark class=\"m-destacable\"><u class=\"m-clave\">o</u></mark> <mark class=\"m-personalizado\">más grupos</mark> raciales y <mark class=\"m-personalizado\">con la intención de mantener</mark> ese régimen.</span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-2703\">🎯 1 pregunta</mark></p><p data-ex=\"EX\"><b>2.</b> Los reos de delitos de lesa humanidad <mark class=\"m-accion\">serán castigados:</mark></p><p><b>1.º</b> Con la pena de <mark class=\"m-personalizado\">prisión permanente revisable</mark> si causaran <mark class=\"m-personalizado\">la muerte</mark> de alguna <mark class=\"m-autoridad\">persona.</mark> <mark class=\"m-resp ex-q\" data-q=\"19-341\">🎯 1 pregunta</mark></p><p><b>4.º</b> Con la pena de <mark class=\"m-personalizado\">prisión</mark> de ocho a 12 años si <mark class=\"m-personalizado\">deportaran o trasladaran por la fuerza, sin motivos autorizados por el derecho internacional,</mark> a una o más <mark class=\"m-autoridad\">personas</mark> <mark class=\"m-personalizado\">a otro</mark> <mark class=\"m-autoridad\">Estado</mark> <mark class=\"m-personalizado\">o lugar,</mark> mediante la <mark class=\"m-personalizado\">expulsión u otros</mark> actos de <mark class=\"m-personalizado\"><mark class=\"m-resp r-ia\" data-q=\"19-ia-2704\">coacción</mark>.</mark></p><p><b>6.º</b> Con la pena de <mark class=\"m-personalizado\">prisión</mark> de doce a quince años <mark class=\"m-personalizado\">la desaparición forzada</mark> de <mark class=\"m-autoridad\">personas.</mark> <mark class=\"m-accion\">Se entenderá</mark> por <mark class=\"m-destacable\">desaparición forzada</mark> la <mark class=\"m-personalizado\">aprehensión,</mark> detención o <mark class=\"m-personalizado\">el secuestro o</mark> cualquier <mark class=\"m-personalizado\">otra</mark> forma de <mark class=\"m-personalizado\"><u class=\"m-clave\">privación de libertad</u></mark> que sean obra de <mark class=\"m-personalizado\"><u class=\"m-clave\">agentes del</u></mark> <mark class=\"m-autoridad\">Estado</mark> o por <mark class=\"m-autoridad\">personas</mark> o grupos de <mark class=\"m-autoridad\">personas</mark> <mark class=\"m-personalizado\">que actúan con la <u class=\"m-clave\">autorización,</u></mark> <span class=\"m-circulo\"><mark class=\"m-personalizado\">el apoyo</mark></span> <mark class=\"m-personalizado\">o la <u class=\"m-clave\">aquiescencia</u> del</mark> <mark class=\"m-autoridad\">Estado,</mark> seguida de la <mark class=\"m-personalizado\"><u class=\"m-clave\">negativa</u> a <u class=\"m-clave\">reconocer</u></mark> dicha privación de libertad o del <mark class=\"m-personalizado\">ocultamiento de la <u class=\"m-clave\">suerte o el</u> paradero de la</mark> <mark class=\"m-autoridad\">persona</mark> desaparecida, sustrayéndola <mark class=\"m-personalizado\"><u class=\"m-clave\">de</u> la</mark> <span class=\"m-circulo\"><mark class=\"m-personalizado\">protección</mark></span> <mark class=\"m-personalizado\">de la ley.</mark>  <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-2706\">🎯 1 pregunta</mark></p><p><b>7.º</b> Con la pena de <mark class=\"m-personalizado\">prisión</mark> de ocho a 12 años <mark class=\"m-personalizado\">si detuvieran</mark> a otro, <mark class=\"m-personalizado\">privándolo de su libertad, con <u class=\"m-clave\">infracción</u> de las normas internacionales sobre la <mark class=\"m-resp r-ia\" data-q=\"19-ia-2707\">detención</mark>.</mark></p><p>A los efectos de este artículo, se entiende por <mark class=\"m-destacable\">tortura</mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">el</u> sometimiento de la</mark> <mark class=\"m-autoridad\">persona</mark> <mark class=\"m-personalizado\">a</mark> sufrimientos <mark class=\"m-resp r-ia\" data-q=\"19-ia-2708\">físicos o psíquicos</mark>.</p><p><mark class=\"m-accion\">Se impondrá</mark> la pena de seis a ocho años a quienes <mark class=\"m-personalizado\">trasladen a</mark> <mark class=\"m-autoridad\">personas</mark> de un lugar a otro, <mark class=\"m-personalizado\">con el <u class=\"m-clave\">propósito de su</u> explotación sexual, empleando violencia, intimidación o engaño, o abusando</mark> de una situación de <mark class=\"m-personalizado\">superioridad o de necesidad o de vulnerabilidad</mark> de la víctima.  <mark class=\"m-resp ex-q r-ia\" data-q=\"19-ia-2709\">🎯 1 pregunta</mark></p><p>Por <mark class=\"m-destacable\">esclavitud</mark> <mark class=\"m-accion\">se entenderá</mark> la <mark class=\"m-personalizado\">situación de la</mark> <mark class=\"m-autoridad\">persona</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-personalizado\">sobre la que otro ejerce,</mark> incluso de hecho, todos o algunos de los <mark class=\"m-personalizado\">atributos del <u class=\"m-clave\">derecho de</u> <mark class=\"m-resp r-ia\" data-q=\"19-ia-2710\">propiedad, como comprarla, venderla, prestarla o darla en trueque</mark>.</mark></span></span></p><p><b><mark class=\"m-personalizado\">3.</mark></b> <mark class=\"m-personalizado\">En todos los casos</mark> previstos en el apartado anterior <mark class=\"m-accion\">se impondrá</mark> además la pena <mark class=\"m-personalizado\">de inhabilitación especial</mark> para profesión u oficio <mark class=\"m-personalizado\">educativos,</mark> en el ámbito <mark class=\"m-personalizado\">docente, deportivo y de tiempo libre,</mark> por un tiempo superior entre tres y cinco años al de la duración de la pena de privación de libertad impuesta en su caso en la sentencia, atendiendo proporcionalmente a la gravedad del delito y a las <mark class=\"m-resp r-ia\" data-q=\"19-ia-2711\">circunstancias que concurran en el delincuente</mark>.</p>"],["Artículo 616 ter <span class=\"ex-sello ex-sello-r\">R29</span>","<p data-r=\"R29\"><span class=\"ex-sello ex-sello-r\">R29</span> El que con <mark class=\"m-personalizado\">violencia, intimidación</mark> <mark class=\"m-destacable\">o</mark> <mark class=\"m-personalizado\">engaño,</mark> se <mark class=\"m-personalizado\">apodere, dañe o destruya una aeronave, buque u otro tipo de embarcación o plataforma en el mar, o bien atente contra las</mark> <mark class=\"m-autoridad\">personas,</mark> <mark class=\"m-personalizado\">cargamento o bienes</mark> que se hallaren <mark class=\"m-personalizado\">a bordo de</mark> las mismas, <mark class=\"m-accion\">será castigado</mark> como reo del delito de piratería con la pena de <mark class=\"m-personalizado\">prisión</mark> de diez a quince años.  <mark class=\"m-resp ex-q\" data-q=\"19-56\">🎯 1 pregunta</mark></p></div></div><div class=\"vis\"><div class=\"vis-t\"><i>⇄</i>DELITO DE PIRATERÍA (cuadro del temario · arts. 616 ter y 616 quater)</div><div class=\"vis-comp\" style=\"--n:3\"><div class=\"vis-col\"><h5>Tipo básico · art. 616 ter</h5><ul><li>Apoderarse, dañar o <mark class=\"m-destacable\">destruir</mark>: aeronave, buque u otro tipo de embarcación o plataforma en el mar.</li><li>Atentar <mark class=\"m-autoridad\">contra</mark>: <mark class=\"m-autoridad\">personas</mark>, <mark class=\"m-personalizado\">cargamento o bienes</mark> que se hallaren en <mark class=\"m-personalizado\">las mismas</mark>.</li><li>Cometer <mark class=\"m-personalizado\">el delito</mark> con: <mark class=\"m-destacable\">violencia, intimidación</mark> o <mark class=\"m-personalizado\">engaño</mark>.</li></ul></div><div class=\"vis-col\"><h5>Resistencia o desobediencia · art. 616 quater</h5><ul><li>Con <mark class=\"m-personalizado\">ocasión de la prevención</mark> o <mark class=\"m-personalizado\">persecución de los hechos</mark> del art. 616 ter: resistirse, o desobedecer.</li><li>Se ha de <mark class=\"m-destacable\">realizar</mark> <mark class=\"m-autoridad\">contra</mark>: buque de <u class=\"m-clave\">guerra</u> o aeronave <mark class=\"m-personalizado\">militar</mark>, u <mark class=\"m-personalizado\">otro buque o aeronave que</mark> lleve <mark class=\"m-personalizado\">signos claros y sea identificable</mark> como <mark class=\"m-personalizado\">buque o aeronave</mark> <mark class=\"m-personalizado\">al servicio del</mark> <mark class=\"m-autoridad\">Estado</mark> <mark class=\"m-personalizado\">español</mark>, y esté <mark class=\"m-personalizado\">autorizado</mark> a <mark class=\"m-personalizado\">tal</mark> <mark class=\"m-personalizado\">fin</mark>.</li></ul></div><div class=\"vis-col\"><h5>Disposición común · arts. 616 ter y 616 quater.3</h5><ul><li><mark class=\"m-personalizado\">Las penas</mark> <mark class=\"m-personalizado\">previstas</mark> en estos artículos <mark class=\"m-accion\">se impondrán</mark> <u class=\"m-clave\">sin perjuicio</u> de las que correspondan por <mark class=\"m-personalizado\">los delitos</mark> <mark class=\"m-personalizado\">cometidos</mark>.</li></ul></div>"]];
